        },
        MESSAGE_LOADING_311_PC = {
          ContentEN = "An underground palace built by the Jishu Sect during its ancient heyday. Rumour has it that deep within lies a relic left behind by the Sect's forebears, one powerful enough to turn the tide of battle. Yet its defensive mechanisms are so intricate that, to this day, no one has reached its depths.",
          TextMapId = "MESSAGE_LOADING_311_PC"
        },
        MESSAGE_LOADING_312_PC = {
          ContentEN = "After the battle with Zhuyin, Zhiliu took {nickname} away and revealed the future through three prophecies.",
          TextMapId = "MESSAGE_LOADING_312_PC"
        },
        MESSAGE_LOADING_313_PC = {
          ContentEN = "At the dawn of all things lay the nameless void...",
          TextMapId = "MESSAGE_LOADING_313_PC"
        },
        MESSAGE_LOADING_31_PC = {
          ContentEN = "Equipping Demon Wedges significantly empowers your characters and weapons. Some rare Wedges can even adorn the bearer's skill effects.",
          TextMapId = "MESSAGE_LOADING_31_PC"
        },
        MESSAGE_LOADING_32_PC = {
          ContentEN = "Demon Wedges place a strain on the bearer, and the maximum amount of strain a bearer can handle is known as Tolerance. Elevating your character and weapon levels can increase this limit, allowing for more Wedges to be equipped for greater combat leverage.",
          TextMapId = "MESSAGE_LOADING_32_PC"
        },
        MESSAGE_LOADING_33_PC = {
          ContentEN = "Each Demon Wedge has an affinity that resonates with certain bearers, which is known as Track. When a Wedge's Track matches the bearer's (character/weapon), it requires less Tolerance, while mismatching requires more.",
          TextMapId = "MESSAGE_LOADING_33_PC"
        },
        MESSAGE_LOADING_34_PC = {
          ContentEN = "The latest innovation in Demon Wedge technology from the Imperial Alchemy Academy capable of altering the Track of slots.",
          TextMapId = "MESSAGE_LOADING_34_PC"
        },
        MESSAGE_LOADING_35_PC = {
          ContentEN = "The Asphodel's specific quests for Phoxhunters. These commissions typically offer handsome rewards. Complete them to enhance team combat power.",
          TextMapId = "MESSAGE_LOADING_35_PC"
        },
        MESSAGE_LOADING_36_PC = {
          ContentEN = "Don't let the endless enemy waves slow you down. Locating your target ASAP is key to nailing the commission quickly.",
          TextMapId = "MESSAGE_LOADING_36_PC"
        },
        MESSAGE_LOADING_37_PC = {
          ContentEN = "Utilize Bouncepads to reach the Evacuation Point more quickly after dealing with the evil \"Finale Flare\" bomb.",
          TextMapId = "MESSAGE_LOADING_37_PC"
        },
        MESSAGE_LOADING_38_PC = {
          ContentEN = "Within the imperial fortress, observe the paths of the differently colored cables to help you disable the defences.",
          TextMapId = "MESSAGE_LOADING_38_PC"
        },
        MESSAGE_LOADING_39_PC = {
          ContentEN = "Click &Avoid& to dodge. Hold a direction to dodge toward that direction.",
          TextMapId = "MESSAGE_LOADING_39_PC"
        },
        MESSAGE_LOADING_39_Phone = {
          ContentEN = "Tap the Dodge button to perform a dodge. Hold a direction to dodge toward that direction.",
          TextMapId = "MESSAGE_LOADING_39_Phone"
        },
        MESSAGE_LOADING_3_PC = {
          ContentEN = "&Attack& when sliding to perform Sliding Attack",
          TextMapId = "MESSAGE_LOADING_3_PC"
        },
        MESSAGE_LOADING_3_Phone = {
          ContentEN = "Hold the Jump button and swipe left to execute a Sliding Attack.",
          TextMapId = "MESSAGE_LOADING_3_Phone"
        },
        MESSAGE_LOADING_401_PC = {
          ContentEN = "The historic capital of Huaxu, with a history stretching back more than a thousand years to the founding of the nation. Crowning the city's highest point is the Hall of Adjudication, an imposing edifice that symbolises the authority of the Nine Chapters of Dafeng.",
          TextMapId = "MESSAGE_LOADING_401_PC"
        },
        MESSAGE_LOADING_402_PC = {
          ContentEN = "A traditional Huaxu festival held once every four years, its origins dating back to the earliest days of the Nine Chapters of Dafeng. During the Rite, the people of Huaxu gather at the Hall of Adjudication under the guidance of the Rite Envoy to offer incense to Lord Argent, praying for lasting peace and prosperity throughout the realm.",
          TextMapId = "MESSAGE_LOADING_402_PC"
        },
        MESSAGE_LOADING_403_PC = {
          ContentEN = "A renowned apothecary in Haojing. Legend has it that its founder came from House Fu, a branch of the Zhuyou clan famed for the healing art known as the Art of Ephemerality. She chose to leave that tradition behind, however, and devote herself instead to herbal medicine, giving rise to what would become Zesheng Pharmacy.",
          TextMapId = "MESSAGE_LOADING_403_PC"
        },
        MESSAGE_LOADING_404_PC = {
          ContentEN = "A major competition held during the Grand Incense Rite. Its purpose is to select the Rite Envoy, who will ascend to the summit of the Hall of Adjudication and preside over the ceremonial rites.",
          TextMapId = "MESSAGE_LOADING_404_PC"
        },
        MESSAGE_LOADING_405_PC = {
          ContentEN = "As the Nine Chapters of Dafeng grew increasingly rigid, many injustices went unanswered. In response, a band of outlaws emerged, defying the law by force and dispensing justice in their own way. They are known as the Drifters.",
          TextMapId = "MESSAGE_LOADING_405_PC"
        },
        MESSAGE_LOADING_406_PC = {
          ContentEN = "One of the Three Ministries of Huaxu. It oversees the country's economy, trade networks, and tax administration.",
          TextMapId = "MESSAGE_LOADING_406_PC"
        },
        MESSAGE_LOADING_407_PC = {
          ContentEN = "An ancient artefact jointly forged by Yang and Ju when the Nine Chapters of Dafeng were founded, meant to preserve the balance between heart and principle. The Jade of Equilibrium was divided into two halves, one held by the Xuanheng Sect and the other by the Jishu Sect. The Jishu Sect's half, however, vanished after the Battle of Shuli.",
          TextMapId = "MESSAGE_LOADING_407_PC"
        },
        MESSAGE_LOADING_408_PC = {
          ContentEN = "Huaxu once passed through an age when various sects contended for supremacy. Many unorthodox sects from that era survive to this day, keeping their distance from the outside world. The Wuqiongzang Sect is among them, known for its mastery of divination and esoteric calculation. Its practitioners are said to glimpse possible futures through hexagrams and, through certain specialised techniques, even influence the human mind.",
          TextMapId = "MESSAGE_LOADING_408_PC"
        },
        MESSAGE_LOADING_409_PC = {
          ContentEN = "A device developed by the Drifters to conceal their base from the Nine Chapters of Dafeng.",
          TextMapId = "MESSAGE_LOADING_409_PC"
        },
        MESSAGE_LOADING_40_PC = {
          ContentEN = "Use dyes to change colours for character skins and weapons.",
          TextMapId = "MESSAGE_LOADING_40_PC"
        },
        MESSAGE_LOADING_410_PC = {
          ContentEN = "The Port of Parting Stars takes its name from an old proverb: \"When the parting stars meet, merchants flock in.\" It is the largest harbour in Haojing and the region's primary centre of trade, with merchant vessels coming and going in an endless stream.",
          TextMapId = "MESSAGE_LOADING_410_PC"
        },
        MESSAGE_LOADING_411_PC = {
          ContentEN = "An institution under the Ministry of Rites, staffed primarily by members of the Xuanheng Sect. It serves as Haojing's official authority on incense supply, incense preparation, and the rites and protocols governing incense offerings.",
          TextMapId = "MESSAGE_LOADING_411_PC"
        },
        MESSAGE_LOADING_412_PC = {
          ContentEN = "An institution under the Ministry of Works, composed largely of members of the Jishu Sect. It is responsible for the construction of Haojing's infrastructure and the maintenance of its public facilities.",
          TextMapId = "MESSAGE_LOADING_412_PC"
        },
        MESSAGE_LOADING_413_PC = {
          ContentEN = "Elite enforcers charged with guarding the Hall of Adjudication and the heart of the Nine Chapters of Dafeng. The Sentinels of Juntian wield power far beyond that of ordinary Magistrates of Yingtian, sustained by the Nine Chapters themselves.",
          TextMapId = "MESSAGE_LOADING_413_PC"
        },
        MESSAGE_LOADING_414_PC = {
          ContentEN = "One of the most ancient rites, handed down since time immemorial. Those who enter into a Covenant of Souls share both life and power.",
          TextMapId = "MESSAGE_LOADING_414_PC"
        },
        MESSAGE_LOADING_415_PC = {
          ContentEN = "A Wishen of unknown origin. Mischievous and unpredictable, it comes and goes without warning, living by a creed of absolute freedom.",
          TextMapId = "MESSAGE_LOADING_415_PC"
        },
        MESSAGE_LOADING_416_PC = {
          ContentEN = "Xiaoyao will sometimes possess nearby objects and alter their appearance. Look carefully and find which one it has possessed.",
          TextMapId = "MESSAGE_LOADING_416_PC"
        },
        MESSAGE_LOADING_417_PC = {
          ContentEN = "When Xiaoyao flees, it may leave behind a Wishen's Path that lets you travel quickly to other locations.",
          TextMapId = "MESSAGE_LOADING_417_PC"
        },
        MESSAGE_LOADING_418_PC = {
          ContentEN = "When Xiaoyao flees, it may leave behind a trail. Follow it to track it down.",
          TextMapId = "MESSAGE_LOADING_418_PC"
        },
        MESSAGE_LOADING_419 = {
          ContentEN = "The noble angel takes up the sword of judgement. Sinners shall be condemned. The innocent shall be absolved.",
          TextMapId = "MESSAGE_LOADING_419"
        },
        MESSAGE_LOADING_41_PC = {
          ContentEN = "Equip various accessories for your characters to create your own unique style!",
          TextMapId = "MESSAGE_LOADING_41_PC"
        },
        MESSAGE_LOADING_420 = {
          ContentEN = "The waves soak the hem of her white tulle dress. Upon them rides her whisper: \"Only death shall part us.\"",
          TextMapId = "MESSAGE_LOADING_420"
        },
        MESSAGE_LOADING_421 = {
          ContentEN = "Wings wrought by will, now borne upon the wind.",
          TextMapId = "MESSAGE_LOADING_421"
        },
        MESSAGE_LOADING_422 = {
          ContentEN = "With a single thought, all heights fall beneath you.",
          TextMapId = "MESSAGE_LOADING_422"
        },
        MESSAGE_LOADING_423 = {
          ContentEN = "I stand atop the peaks.",
          TextMapId = "MESSAGE_LOADING_423"
        },
        MESSAGE_LOADING_424 = {
          ContentEN = "Midsummer night, beneath a sky of stars, a forest where violets and butterfly wings waltzed in delicate steps. A sight she had never seen.",
          TextMapId = "MESSAGE_LOADING_424"
        },
        MESSAGE_LOADING_425 = {
          ContentEN = "Tides to wash away the dust, waves to still the heart.",
          TextMapId = "MESSAGE_LOADING_425"
        },
        MESSAGE_LOADING_426 = {
          ContentEN = "A jewel shining on the northern rails of the Empire. The station's dome is the first thing people see — grand, magnificent, and the first impression it leaves on all who arrive.",
          TextMapId = "MESSAGE_LOADING_426"
        },
        MESSAGE_LOADING_427 = {
          ContentEN = "A place where crowds flow and cross paths. Passengers from all walks gather here, board their carriages, and after brief encounters, depart toward new futures.",
          TextMapId = "MESSAGE_LOADING_427"
        },
        MESSAGE_LOADING_428 = {
          ContentEN = "An ironworks attached to Bloomfield Station, located beneath it. Hundreds of workers toil here, crafting train parts and storing the Phoxichor that powers the trains — sustaining everything that keeps the world above running.",
          TextMapId = "MESSAGE_LOADING_428"
        },
        MESSAGE_LOADING_429 = {
          ContentEN = "An ironworks attached to Bloomfield Station, located beneath it. Hundreds of workers toil here, crafting train parts and storing the Phoxichor that powers the trains — sustaining everything that keeps the world above running.",
          TextMapId = "MESSAGE_LOADING_429"
        },
        MESSAGE_LOADING_42_PC = {
          ContentEN = "Visit the Lunosmith to forge weapons and other items.",
          TextMapId = "MESSAGE_LOADING_42_PC"
        },
        MESSAGE_LOADING_430 = {
          ContentEN = "The personal train of Sibylle Mason, leader of the 13th Legion. Its exterior is solemn and imposing. Since the 13th Legion has no fixed base, this train can appear anywhere — hence the rumour among train enthusiasts: catching a glimpse of it brings good luck.",
          TextMapId = "MESSAGE_LOADING_430"
        },
        MESSAGE_LOADING_431 = {
          ContentEN = "A valley outside Flodia Bloomfield Station, left unnamed by anyone. Only the roaring trains that race past each day bear witness to its existence.",
          TextMapId = "MESSAGE_LOADING_431"
        },
        MESSAGE_LOADING_432 = {
          ContentEN = "One day, we will all return here...",
          TextMapId = "MESSAGE_LOADING_432"
        },
        MESSAGE_LOADING_433 = {
          ContentEN = "A mountainous area in southern Cocytus. Further south lies the Great Hyperborean Plain.",
          TextMapId = "MESSAGE_LOADING_433"
        },
        MESSAGE_LOADING_434 = {
          ContentEN = "The busiest tavern in Icelake, run by its owner, Camilla. The Asphodel welcomes all manner of patrons — from inner-city nobles to drifters from the slums. In a way, it may be the most disorderly yet most peaceful place in the entire city.",
          TextMapId = "MESSAGE_LOADING_434"
        },
        MESSAGE_LOADING_43_PC = {
          ContentEN = "While exploring the world, you may come across <H>Geniemons</>. Use <H>Treats</> to become friends with them. Geniemons can empower your team in battle through Geniemon Support.",
          TextMapId = "MESSAGE_LOADING_43_PC"
        },
        MESSAGE_LOADING_44_PC = {
          ContentEN = "Landing a large catch may trigger a <H>Fish for Bigger Fish</> chance! Use your current catch as bait and cast again — you might land an even rarer prize.",
          TextMapId = "MESSAGE_LOADING_44_PC"
        },
        MESSAGE_LOADING_45_PC = {
          ContentEN = "Completing Special Side Quests may unlock some new system functions.",
          TextMapId = "MESSAGE_LOADING_45_PC"
        },
        MESSAGE_LOADING_46_PC = {
          ContentEN = "Visit <Highlight>Sojourns of the Pages of Time</> to view stories from different stages of a character's life.",
          TextMapId = "MESSAGE_LOADING_46_PC"
        },
        MESSAGE_LOADING_47_PC = {
          ContentEN = "Reflect on one or more clues to uncover new leads.",
          TextMapId = "MESSAGE_LOADING_47_PC"
        },
        MESSAGE_LOADING_48_PC = {
          ContentEN = "From time to time, dynamic quests will occur throughout the world. Your involvement may alter their outcomes.",
          TextMapId = "MESSAGE_LOADING_48_PC"
        },
        MESSAGE_LOADING_49_PC = {
          ContentEN = "Lunoeggy's shop offers a wide selection of valuable items. Complete Lunoeggy's Impression Checks to earn generous rewards.",
          TextMapId = "MESSAGE_LOADING_49_PC"
        },
        MESSAGE_LOADING_4_PC = {
          ContentEN = "Raising an alarm will attract more enemies",
          TextMapId = "MESSAGE_LOADING_4_PC"
        },
        MESSAGE_LOADING_50_PC = {
          ContentEN = "You can summon Combat Partners to fight at your side during world exploration, commissions and Nocturnal Echoes.",
          TextMapId = "MESSAGE_LOADING_50_PC"
        },
        MESSAGE_LOADING_51_PC = {
          ContentEN = "Paniemon — the cleverest of all Geniemons! Their traces can be found all over. Follow them, and you just might stumble upon something delightful.",
          TextMapId = "MESSAGE_LOADING_51_PC"
        },
        MESSAGE_LOADING_5_PC = {
          ContentEN = "If you get stuck while playing the game, go to \"Reset Location\" in \"Settings\" to get free.",
          TextMapId = "MESSAGE_LOADING_5_PC"
        },
        MESSAGE_LOADING_6_PC = {
          ContentEN = "Attacking mechas can also deal damage to enemies.",
          TextMapId = "MESSAGE_LOADING_6_PC"
        },
        MESSAGE_LOADING_7_PC = {
          ContentEN = "Filthoids are violent creatures widely spread on the Atlasia Continent. Many of them are highly aggressive.",
          TextMapId = "MESSAGE_LOADING_7_PC"
        },
        MESSAGE_LOADING_8_PC = {
          ContentEN = "The Hyperborean Empire is located in the northwest of the Atlasia Continent, with formidable military and highly-advanced Phoxichor technology.",
          TextMapId = "MESSAGE_LOADING_8_PC"
        },
        MESSAGE_LOADING_9_PC = {
          ContentEN = "Phoxene is the most common mineral on the Atlasia Continent and also the foundation of Phoxichor technology.",
          TextMapId = "MESSAGE_LOADING_9_PC"
        },
