        Message_Guide_ModLevelUp_1 = {
          ContentEN = "Enhancing the <H>level of Demon Wedges</> can further empower Daimons and weapons.",
          TextMapId = "Message_Guide_ModLevelUp_1"
        },
        Message_Guide_ModLevelUp_4 = {
          ContentEN = "Select a Demon Wedge",
          TextMapId = "Message_Guide_ModLevelUp_4"
        },
        Message_Guide_ModLevelUp_4_Pad = {
          ContentEN = "Press to select a Demon Wedge",
          TextMapId = "Message_Guide_ModLevelUp_4_Pad"
        },
        Message_Guide_ModLevelUp_5 = {
          ContentEN = "Select \"Upgrade Demon Wedge\"",
          TextMapId = "Message_Guide_ModLevelUp_5"
        },
        Message_Guide_ModLevelUp_5_Pad = {
          ContentEN = "Press to select \"Upgrade Demon Wedge\"",
          TextMapId = "Message_Guide_ModLevelUp_5_Pad"
        },
        Message_Guide_ModLevelUp_6 = {
          ContentEN = "Upgrading Demon Wedges <H>significantly boosts your combat powers</>.",
          TextMapId = "Message_Guide_ModLevelUp_6"
        },
        Message_Guide_ModLevelUp_7 = {
          ContentEN = "Upgrading a Demon Wedge <H>increases its required Tolerance</>. Please make sure the whole required Tolerance <H>do not</> exceed the <H>Tolerance cap</> after the Demon Wedge is upgraded.",
          TextMapId = "Message_Guide_ModLevelUp_7"
        },
        Message_Guide_ModTendency_1 = {
          ContentEN = "A character's innate Track can be adjusted using <H>Track-Shift Modules</>.",
          TextMapId = "Message_Guide_ModTendency_1"
        },
        Message_Guide_ModTendency_10 = {
          ContentEN = "If you possess a powerful Demon Wedge but are troubled by an <H>incompatible Track</>, consider <H>adjusting the slot's Track</>.",
          TextMapId = "Message_Guide_ModTendency_10"
        },
        Message_Guide_ModTendency_11 = {
          ContentEN = "When a character's slot Track <H>aligns with</> a Demon Wedge's Track, the <H>Tolerance</> required for equipping this Demon Wedge is <H>reduced</>.",
          TextMapId = "Message_Guide_ModTendency_11"
        },
        Message_Guide_ModTendency_4 = {
          ContentEN = "Select the Demon Wedge slot",
          TextMapId = "Message_Guide_ModTendency_4"
        },
        Message_Guide_ModTendency_4_Pad = {
          ContentEN = "Press to select a Demon Wedge Slot",
          TextMapId = "Message_Guide_ModTendency_4_Pad"
        },
        Message_Guide_ModTendency_5 = {
          ContentEN = "Select \"Adjust Slot Track\"",
          TextMapId = "Message_Guide_ModTendency_5"
        },
        Message_Guide_ModTendency_5_Pad = {
          ContentEN = "Press to select \"Adjust Slot Track\"",
          TextMapId = "Message_Guide_ModTendency_5_Pad"
        },
        Message_Guide_ModTendency_6 = {
          ContentEN = "You can use <H>Track-Shift Modules</> to add, modify, or eliminate the innate <H>Track</> of a character's Demon Wedge slot.",
          TextMapId = "Message_Guide_ModTendency_6"
        },
        Message_Guide_ModTendency_7 = {
          ContentEN = "Frustrated by the limited Tolerance cap preventing more Demon Wedge configurations? Try keeping an eye on <H>Track</>!",
          TextMapId = "Message_Guide_ModTendency_7"
        },
        Message_Guide_ModTendency_8 = {
          ContentEN = "Every character or weapon bears intrinsic traits, leading to varied <H>Tracks</> for their <H>Demon Wedge slots</>.",
          TextMapId = "Message_Guide_ModTendency_8"
        },
        Message_Guide_ModTendency_9 = {
          ContentEN = "For a more effective use of <H>Demon Wedges</>, some are specifically crafted with a <H>Track</> tailored to certain individuals.",
          TextMapId = "Message_Guide_ModTendency_9"
        },
        Message_Guide_Mod_1 = {
          ContentEN = "<H>Demon Wedges</>, crafted by the Spathatoi of Hyperborea, are portable components that significantly enhance the power of Daimons and weapons once equipped.",
          TextMapId = "Message_Guide_Mod_1"
        },
        Message_Guide_Mod_10 = {
          ContentEN = "Select a Demon Wedge to check its effects",
          TextMapId = "Message_Guide_Mod_10"
        },
        Message_Guide_Mod_11 = {
          ContentEN = "Consume <H>Coins</> and <H>Carmine Globules</> to <H>upgrade</> Demon Wedges and greatly enhance their powers. However, upgrading Demon Wedges will also increase the burden they put on the bearer, potentially exceeding the Tolerance cap for equipping.",
          TextMapId = "Message_Guide_Mod_11"
        },
        Message_Guide_Mod_12 = {
          ContentEN = "Here you can quickly toggle between characters and weapons to adjust their Demon Wedges as needed.",
          TextMapId = "Message_Guide_Mod_12"
        },
        Message_Guide_Mod_13 = {
          ContentEN = "A Character Demon Wedge can be used by multiple characters. Similarly, the same Weapon Demon Wedge can be used on multiple weapons.",
          TextMapId = "Message_Guide_Mod_13"
        },
        Message_Guide_Mod_14 = {
          ContentEN = "<H>Upgrade</> your characters and weapons to increase their Tolerance caps.",
          TextMapId = "Message_Guide_Mod_14"
        },
        Message_Guide_Mod_15 = {
          ContentEN = "Click here to auto-equip Demon Wedges",
          TextMapId = "Message_Guide_Mod_15"
        },
        Message_Guide_Mod_16 = {
          ContentEN = "Click Confirm to complete Demon Wedge auto-assembly",
          TextMapId = "Message_Guide_Mod_16"
        },
        Message_Guide_Mod_16_Pad = {
          ContentEN = "Tap Confirm to complete Demon Wedge auto-assembly",
          TextMapId = "Message_Guide_Mod_16_Pad"
        },
        Message_Guide_Mod_2 = {
          ContentEN = "Select \"Demon Wedges\" to set up",
          TextMapId = "Message_Guide_Mod_2"
        },
        Message_Guide_Mod_2_Pad = {
          ContentEN = "Press to select a Demon Wedge to equip",
          TextMapId = "Message_Guide_Mod_2_Pad"
        },
        Message_Guide_Mod_3 = {
          ContentEN = "Demon Wedges come in two types: <H>Character Demon Wedges</> and <H>Weapon Demon Wedges</>, and they are not interchangeable.",
          TextMapId = "Message_Guide_Mod_3"
        },
        Message_Guide_Mod_4 = {
          ContentEN = "Demon Wedges provide various enhancement effects; they need to be <H>equipped in slots</> to take effect.",
          TextMapId = "Message_Guide_Mod_4"
        },
        Message_Guide_Mod_5 = {
          ContentEN = "<H>Ascend characters</> to unlock more slots",
          TextMapId = "Message_Guide_Mod_5"
        },
        Message_Guide_Mod_6 = {
          ContentEN = "Demon Wedges contain massive powers, thus imposing a certain strain on the bearer.",
          TextMapId = "Message_Guide_Mod_6"
        },
        Message_Guide_Mod_7 = {
          ContentEN = "The <H>top left corner</> indicates the <H>required Tolerance</> of this Demon Wedge.",
          TextMapId = "Message_Guide_Mod_7"
        },
        Message_Guide_Mod_8 = {
          ContentEN = "When Tolerance hasn't reached the cap, you can drag a Demon Wedge into an empty slot to equip it.",
          TextMapId = "Message_Guide_Mod_8"
        },
        Message_Guide_Mod_9 = {
          ContentEN = "<H>Tolerance</> refers to the capacity of characters and weapons to bear Demon Wedges. The number below represents the Tolerance cap of a character or a weapon.",
          TextMapId = "Message_Guide_Mod_9"
        },
        Message_Guide_OnlineAreaPre_1 = {
          ContentEN = "Complete \"Black Iron and White Flower\" of the Chapter Noctoyager to unlock co-op. Meet other players from across time in dedicated co-op areas.",
          TextMapId = "Message_Guide_OnlineAreaPre_1"
        },
        Message_Guide_OnlineAreaPre_2 = {
          ContentEN = "Some areas become co-op areas after unlocking the feature. Entering these areas automatically enables co-op mode. Leaving them disables it.",
          TextMapId = "Message_Guide_OnlineAreaPre_2"
        },
        Message_Guide_OnlineAreaPre_3 = {
          ContentEN = "You can toggle Auto-Join on or off in Settings.",
          TextMapId = "Message_Guide_OnlineAreaPre_3"
        },
        Message_Guide_OnlineArea_1 = {
          ContentEN = "Some areas are Co-op Areas, where you may encounter players from different timelines.",
