        Message_Guide_PetTraits_5 = {
          ContentEN = "Geniemon are either <H>Active</> or <H>Inactive</>. Active Geniemons have Potential slots, which unlock as their star level increases.",
          TextMapId = "Message_Guide_PetTraits_5"
