        MonsterRushEvent_Wuyou_DungeonDes01 = {
          ContentEN = [[
A mysterious, sword-bearing Wishen appears from nowhere, blocking your path. Perhaps sensing your potential, they offer to teach you a move or two.
"Watch closely. I'll only show you once."]],
          TextMapId = "MonsterRushEvent_Wuyou_DungeonDes01"
        },
        MonsterRushEvent_Wuyou_DungeonDes02 = {
          ContentEN = "Sunlight dapples through the leaves. A breeze stirs your hair. As though recalling a long-lost afternoon, the little Wishen lets out a drawn-out yawn.\n...Wait — do Wishen even yawn?",
          TextMapId = "MonsterRushEvent_Wuyou_DungeonDes02"
        },
        MonsterRushEvent_Wuyou_DungeonDes03 = {
          ContentEN = "The diligent swordsman and the lazy shepherd — their bickering goes on and on. Here's hoping they don't decide to gang up on you, a lone traveller swept up in their cheerful squabble.",
          TextMapId = "MonsterRushEvent_Wuyou_DungeonDes03"
        },
        MonsterRushEvent_Wuyou_DungeonDes04 = {
          ContentEN = [[
One talisman... two... three... You watch as the Wishen draws slip after slip from behind their back, like a stage magician fanning endless cards from their sleeve.
"Not this one... nor that... Where's my Thunder-Wielding Talisman!?"]],
          TextMapId = "MonsterRushEvent_Wuyou_DungeonDes04"
        },
        MonsterRushEvent_Wuyou_DungeonDes05 = {
          ContentEN = "Unhurried, a Wishen places their straw hat in your hands and asks you to keep it safe.\nThe next instant, you think you see a suited figure rise from their shadow, axe in hand, bellowing — \"Who else wants some!?\"",
          TextMapId = "MonsterRushEvent_Wuyou_DungeonDes05"
        },
        MonsterRushEvent_Wuyou_DungeonDes06 = {
          ContentEN = [[
They say Wishen are born of unfinished business. You glance at the companion drifting quietly by your side.
What wish, you wonder, keeps them tethered to this world?]],
          TextMapId = "MonsterRushEvent_Wuyou_DungeonDes06"
        },
        MonsterRushEvent_Wuyou_DungeonDes07 = {
          ContentEN = "If fading away means finally letting go, then sorrowful partings have no place in the Wishen's world.\nColoured in the hues of the soul, these whimsical spirits gather here — and tomorrow, as ever, will brim with noise and wonder.",
          TextMapId = "MonsterRushEvent_Wuyou_DungeonDes07"
        },
        MonsterRushEvent_Wuyou_DungeonName01 = {
          ContentEN = "The Nameless Swordsman's Lesson",
          TextMapId = "MonsterRushEvent_Wuyou_DungeonName01"
        },
        MonsterRushEvent_Wuyou_DungeonName02 = {
          ContentEN = "The Drowsy Shepherd's Yawn",
          TextMapId = "MonsterRushEvent_Wuyou_DungeonName02"
        },
        MonsterRushEvent_Wuyou_DungeonName03 = {
          ContentEN = "An Entertaining Farce",
          TextMapId = "MonsterRushEvent_Wuyou_DungeonName03"
        },
        MonsterRushEvent_Wuyou_DungeonName04 = {
          ContentEN = "Endless Talismans up Their Sleeve",
          TextMapId = "MonsterRushEvent_Wuyou_DungeonName04"
        },
        MonsterRushEvent_Wuyou_DungeonName05 = {
          ContentEN = "The Leisurely Maniac",
          TextMapId = "MonsterRushEvent_Wuyou_DungeonName05"
        },
        MonsterRushEvent_Wuyou_DungeonName06 = {
          ContentEN = "Trial of Lingering Wishes",
          TextMapId = "MonsterRushEvent_Wuyou_DungeonName06"
        },
        MonsterRushEvent_Wuyou_DungeonName07 = {
          ContentEN = "A Tomorrow Unburdened",
          TextMapId = "MonsterRushEvent_Wuyou_DungeonName07"
        },
        MonsterRushEvent_Wuyou_PetDesc_1 = {
          ContentEN = "A Wishen who wields destructive talismans with ease — though the real mystery is where they're pulling them from.",
          TextMapId = "MonsterRushEvent_Wuyou_PetDesc_1"
        },
        MonsterRushEvent_Wuyou_PetDesc_2 = {
          ContentEN = "He seems calm, composed — but cross him, and the consequences may far exceed your expectations.",
          TextMapId = "MonsterRushEvent_Wuyou_PetDesc_2"
        },
        MonsterRushEvent_Wuyou_PetDesc_3 = {
          ContentEN = "A master of sword-flight, their blades drift and whirl with effortless grace — the perfect backdrop for a photo, if they'd let you borrow it.",
          TextMapId = "MonsterRushEvent_Wuyou_PetDesc_3"
        },
        MonsterRushEvent_Wuyou_PetDesc_4 = {
          ContentEN = "They always drift with a light, unhurried grace — and if you're feeling down, a gentle pat from them might just lift your spirits.",
          TextMapId = "MonsterRushEvent_Wuyou_PetDesc_4"
        },
        MonsterRushEvent_Wuyou_PetName_1 = {
          ContentEN = "Talisman-Wielding Wishen",
