        PhantomTalk_1103_Chest = {
          ContentEN = "Not all surprises hide behind the curtain. Some step right into the light.",
          TextMapId = "PhantomTalk_1103_Chest"
        },
        PhantomTalk_1104_Chest = {
          ContentEN = "There may be treasure here. Go on, my young friend — add it to your trove.",
          TextMapId = "PhantomTalk_1104_Chest"
        },
        PhantomTalk_1501_Chest = {
          ContentEN = "A chest? Smash it, Samael—! Wait, no, no. We're not doing this today...",
          TextMapId = "PhantomTalk_1501_Chest"
        },
        PhantomTalk_1502_Chest = {
          ContentEN = "A keepsake... perhaps left behind by a soul drifted to the Misty Sea.",
          TextMapId = "PhantomTalk_1502_Chest"
        },
        PhantomTalk_1503_Chest = {
          ContentEN = "Be a shame to leave this treasure buried in the dirt. Go on — take it.",
          TextMapId = "PhantomTalk_1503_Chest"
        },
        PhantomTalk_1504_Chest = {
          ContentEN = "What's inside the chest? Treasure? Or just another chest?",
          TextMapId = "PhantomTalk_1504_Chest"
        },
        PhantomTalk_160101_Chest = {
          ContentEN = "Well, what a pleasant surprise.",
          TextMapId = "PhantomTalk_160101_Chest"
        },
        PhantomTalk_1601_Chest = {
          ContentEN = "Well, what a pleasant surprise.",
          TextMapId = "PhantomTalk_1601_Chest"
        },
        PhantomTalk_1801_Chest = {
          ContentEN = "Fina's friends say... they smell the King's treasure!",
          TextMapId = "PhantomTalk_1801_Chest"
        },
        PhantomTalk_2101_Chest = {
          ContentEN = "Romance thrives on surprises... and here's one now.",
          TextMapId = "PhantomTalk_2101_Chest"
        },
        PhantomTalk_2301_Chest = {
          ContentEN = "Ooh, found something shiny! Heehee — wanna guess what's inside?",
          TextMapId = "PhantomTalk_2301_Chest"
        },
        PhantomTalk_2401_Chest = {
          ContentEN = "Unexpected fortune in the wilds... Could be enough to buy a dose or two of healing.",
          TextMapId = "PhantomTalk_2401_Chest"
        },
        PhantomTalk_3101_Chest = {
          ContentEN = "Well, that's a surprise. Maybe luck's finally turning.",
          TextMapId = "PhantomTalk_3101_Chest"
        },
        PhantomTalk_3102_Chest = {
          ContentEN = "Like I said — clean-up comes with the occasional surprise.",
          TextMapId = "PhantomTalk_3102_Chest"
        },
        PhantomTalk_3103_Chest = {
          ContentEN = "Um... Oliver says there's something sh—shiny nearby.",
          TextMapId = "PhantomTalk_3103_Chest"
        },
        PhantomTalk_3201_Chest = {
          ContentEN = "No one's claimed it? Then go ahead — it's not against justice to keep it.",
          TextMapId = "PhantomTalk_3201_Chest"
        },
        PhantomTalk_3202_Chest = {
          ContentEN = "Luck is another means of accumulating wealth. Go on — there's no shame in accepting it.",
          TextMapId = "PhantomTalk_3202_Chest"
        },
        PhantomTalk_3301_Chest = {
          ContentEN = "I smell treasure! Feels like a good haul today!",
          TextMapId = "PhantomTalk_3301_Chest"
        },
        PhantomTalk_4101_Chest = {
          ContentEN = "Perimeter clear. Recovered some abandoned supplies.",
          TextMapId = "PhantomTalk_4101_Chest"
        },
        PhantomTalk_4102_Chest = {
          ContentEN = "Earth below, fire above — gold, born of toil. The signs did not deceive.",
          TextMapId = "PhantomTalk_4102_Chest"
        },
        PhantomTalk_4201_Chest = {
          ContentEN = "Such worldly things are of no use to me. They're yours.",
          TextMapId = "PhantomTalk_4201_Chest"
        },
        PhantomTalk_4202_Chest = {
          ContentEN = "Treasure? Nice. Think they'll let me trade it for a day off?",
          TextMapId = "PhantomTalk_4202_Chest"
        },
        PhantomTalk_4301_Chest = {
          ContentEN = "Treasure, just lying around? Hmph. I've no interest in prey that doesn't resist.",
          TextMapId = "PhantomTalk_4301_Chest"
        },
        PhantomTalk_5101_Chest = {
          ContentEN = "You found something, Filbert? Wait—this isn't food! Spit it out!",
          TextMapId = "PhantomTalk_5101_Chest"
        },
        PhantomTalk_5102_Chest = {
          ContentEN = "Look what I found! Let's split it 50-50, as always.",
          TextMapId = "PhantomTalk_5102_Chest"
        },
        PhantomTalk_5301_Chest = {
          ContentEN = "Do you think... this little box might be holding someone's memories?",
          TextMapId = "PhantomTalk_5301_Chest"
        },
        PhantomTalk_5401_Chest = {
          ContentEN = "Found some supplies. Let's restock before we head out again.",
          TextMapId = "PhantomTalk_5401_Chest"
        },
        PhotoEvent_Day1_1 = {
          ContentEN = "Where We Grew Up",
          TextMapId = "PhotoEvent_Day1_1"
        },
        PhotoEvent_Day1_2 = {
          ContentEN = "The home where Berenica and I once lived. Beneath its narrow eaves, we spent more than a decade side by side. One day, I'll return here with her.",
          TextMapId = "PhotoEvent_Day1_2"
        },
        PhotoEvent_Day2_1 = {
          ContentEN = "The First Breeze",
          TextMapId = "PhotoEvent_Day2_1"
        },
        PhotoEvent_Day2_2 = {
          ContentEN = "The place where I first met Psyche. In this cold city, she was the first person to show me real kindness.",
          TextMapId = "PhotoEvent_Day2_2"
        },
        PhotoEvent_Day3_1 = {
          ContentEN = "Bloom Through the Ice",
          TextMapId = "PhotoEvent_Day3_1"
        },
        PhotoEvent_Day3_2 = {
          ContentEN = "The place where I lost Psyche. Though fate was cruel, she chose to burn brightly without regret. I'll keep our promise and go on seeing the world for the both of us.",
          TextMapId = "PhotoEvent_Day3_2"
        },
        PhotoEvent_Day4_1 = {
          ContentEN = "An Unlit Stage",
          TextMapId = "PhotoEvent_Day4_1"
        },
        PhotoEvent_Day4_2 = {
          ContentEN = "The hideout of Phantasio and Blues. That \"dream\" buried in the mire, yet still gleaming... was it a precious hope, or a delusion that led to ruin?",
          TextMapId = "PhotoEvent_Day4_2"
        },
        PhotoEvent_Day5_1 = {
          ContentEN = "A Grand Finale",
          TextMapId = "PhotoEvent_Day5_1"
        },
        PhotoEvent_Day5_2 = {
          ContentEN = "Here, I once witnessed a tragic yet beautiful final performance. Upon that stage, the lone performer gave everything he had — his passion, his life — to give his audience one perfect final act.",
          TextMapId = "PhotoEvent_Day5_2"
        },
        PhotoEvent_Day6_1 = {
          ContentEN = "Weavers of Stars",
          TextMapId = "PhotoEvent_Day6_1"
        },
        PhotoEvent_Day6_2 = {
          ContentEN = "A landmark in Mistwharf, and home to the largest chamber of commerce in the area. It was here that I accepted Zhiliu's commission and set out on my journey through Huaxu.",
          TextMapId = "PhotoEvent_Day6_2"
        },
        PhotoEvent_Day7_1 = {
          ContentEN = "A Wager Against Heaven",
          TextMapId = "PhotoEvent_Day7_1"
        },
        PhotoEvent_Day7_2 = {
          ContentEN = "The dwelling of Taihao, one of Huaxu's gods. It was here that Zhiliu revealed to me the perilous plan for which she had staked everything. And when the sealed god finally awoke, Huaxu at last stepped into a new era.",
          TextMapId = "PhotoEvent_Day7_2"
        },
