        READSERIES_DESC_1039 = {
          ContentEN = "Retrieved from among countless folders within the cabinet, these files contain photographs and meticulous daily records of each child who once lived at the Hypnos' House.",
          TextMapId = "READSERIES_DESC_1039"
        },
        READ_DESC_2000001 = {
          ContentEN = "The statue's base is marked with time-worn inscriptions, the faded text hinting at a hymn of praise to a deity.",
          TextMapId = "READ_DESC_2000001"
        },
        READ_DESC_2000002 = {
          ContentEN = "A yellowed and somewhat damaged book about alchemy filled with annotations. ",
          TextMapId = "READ_DESC_2000002"
        },
        READ_DESC_2000003 = {
          ContentEN = "An abandoned diary written with elegant handwriting but in a state of disrepair. Some parts are difficult to discern. ",
          TextMapId = "READ_DESC_2000003"
        },
        READ_DESC_2000004 = {
          ContentEN = "An abandoned diary written with elegant handwriting but in a state of disrepair. Some parts are difficult to discern. ",
          TextMapId = "READ_DESC_2000004"
        },
        READ_DESC_2000005 = {
          ContentEN = "An abandoned diary written with elegant handwriting but in a state of disrepair. Some parts are difficult to discern. ",
          TextMapId = "READ_DESC_2000005"
        },
        READ_DESC_2000006 = {
          ContentEN = "A fragmented recording capturing the last exchange between Psyche and Henrik.",
          TextMapId = "READ_DESC_2000006"
        },
        READ_DESC_2000007 = {
          ContentEN = "A venerable medical tome detailing the causes, symptoms, and treatments of myriad diseases. Although many treatment entries remain unfilled, its cover boldly declares, \"No disease is beyond human conquest\" — a promise destined to be fulfilled by future generations of healers and scholars.",
          TextMapId = "READ_DESC_2000007"
        },
        READ_DESC_2000008 = {
          ContentEN = "An old, much-thumbed tome with exotic binding. Its pages are fragile, as if a mere touch could cause them to fall apart. Upon closer inspection, it appears to be a text on pharmacology.",
          TextMapId = "READ_DESC_2000008"
        },
        READ_DESC_2000009 = {
          ContentEN = "A luxurious letter addressed to Henrik Ethelred, found in a drawer.",
          TextMapId = "READ_DESC_2000009"
        },
        READ_DESC_2000010 = {
          ContentEN = "An unposted letter, gathering dust atop the desk for reasons unknown.",
          TextMapId = "READ_DESC_2000010"
        },
        READ_DESC_2000011 = {
          ContentEN = "The latter half of this familial letter is smudged with water stains, rendering it illegible. The dusty page and the presence of the Hypnos' House eloquently speak of Henrik's choice at the time.",
          TextMapId = "READ_DESC_2000011"
        },
        READ_DESC_2000012 = {
          ContentEN = "A serial novel with a sloppy title, set against the backdrop of the decades-old war between Hyperborea and Elysium, centring on the adventures of a Hyperborean boy. It's a favourite among the Empire's youth.",
          TextMapId = "READ_DESC_2000012"
        },
        READ_DESC_2000013 = {
          ContentEN = "The diary of a traveller long exposed to the elements. Its pages mostly obscured by stains and smudges, only the most recent entries remain legible.",
          TextMapId = "READ_DESC_2000013"
        },
        READ_DESC_2000014 = {
          ContentEN = "Theo's comprehensive field notes that cover everything — the environment, plants, animals, and humans.",
          TextMapId = "READ_DESC_2000014"
        },
        READ_DESC_2000015 = {
          ContentEN = "Theo's comprehensive field notes that cover everything — the environment, plants, animals, and humans.",
          TextMapId = "READ_DESC_2000015"
        },
        READ_DESC_2000016 = {
          ContentEN = "Theo's comprehensive field notes that cover everything — the environment, plants, animals, and humans.",
          TextMapId = "READ_DESC_2000016"
        },
        READ_DESC_2000017 = {
          ContentEN = "A worn letter from Annie to her mother, frayed from time spent in a pocket but still readable.",
          TextMapId = "READ_DESC_2000017"
        },
        READ_DESC_2000018 = {
          ContentEN = "A journal unearthed at Glevum Pit, seemingly left behind in haste. Its pages reveal the author's profound remorse and some murky, possibly fabricated, secrets.",
          TextMapId = "READ_DESC_2000018"
        },
        READ_DESC_2000019 = {
          ContentEN = "A forty-year-old journal discovered on a secluded trail in the deepest reaches of Glevum Pit. The hasty writing reveals the simple yet intense desires of a young man.",
          TextMapId = "READ_DESC_2000019"
        },
        READ_DESC_2000020 = {
          ContentEN = "A rubbing of words deeply etched into a wall with fierce emotion. The carver's anger behind each letter feels almost alive.",
          TextMapId = "READ_DESC_2000020"
        },
        READ_DESC_2000021 = {
          ContentEN = "A rubbing of faintly legible text found in the crevices of a sewer wall, seemingly related to a question posed by someone living there.",
          TextMapId = "READ_DESC_2000021"
        },
        READ_DESC_2000022 = {
          ContentEN = "A rubbing of faintly legible text found in the crevices of a sewer wall, seemingly related to a question posed by someone living there.",
          TextMapId = "READ_DESC_2000022"
        },
        READ_DESC_2000023 = {
          ContentEN = "An extravagantly worded flyer. Had you not witnessed the abandoned pit's sorry state for yourself, it might have fooled you for a moment. By taking this flyer, you spare someone from falling victim to a scam.\nAs for the bait in the box — consider it a reward for your good deed and take it with pride.",
          TextMapId = "READ_DESC_2000023"
        },
        READ_DESC_2000024 = {
          ContentEN = "A crumpled letter, seemingly soaked before. The envelope bears no address, only the recipient's name.",
          TextMapId = "READ_DESC_2000024"
        },
        READ_DESC_2000025 = {
          ContentEN = [[
The pages have yellowed with age yet remain undamaged. Someone must've kept it with care.
The cover features a portrait of a grey-haired woman, a pristine white flower blooming in her left eye.
The back cover bears the emblem of The Forsakens and the inscription: "May freedom guide our way."]],
          TextMapId = "READ_DESC_2000025"
        },
        READ_DESC_2000026 = {
          ContentEN = "A rejected application, dated a year and a half ago.",
          TextMapId = "READ_DESC_2000026"
        },
        READ_DESC_2000027 = {
          ContentEN = "A conversation carried out via passed notes. The worn paper suggests this exchange took place some time ago.",
          TextMapId = "READ_DESC_2000027"
        },
        READ_DESC_2000028 = {
          ContentEN = "The content of this journal suggests a certain laxity in the discipline within The Forsakens.",
          TextMapId = "READ_DESC_2000028"
        },
        READ_DESC_2000029 = {
          ContentEN = "A rejected application, dated two years ago.",
          TextMapId = "READ_DESC_2000029"
        },
        READ_DESC_2000030 = {
          ContentEN = "The only holiday the soldiers stationed at the fortress are allowed to celebrate.",
          TextMapId = "READ_DESC_2000030"
        },
        READ_DESC_2000031 = {
          ContentEN = "A crisp new evacuation notice that starkly deviates from the empire's usual formatting.",
          TextMapId = "READ_DESC_2000031"
        },
        READ_DESC_2000032 = {
          ContentEN = [[
Combat logs from the simulation console at Lonza Fortress. They meticulously detail the Imperial soldiers' performances in simulated battles, with candid assessments and suggestions for each squad.
The narrative shifts abruptly in the last entries, suggesting they were authored by someone from The Forsakens rather than the Legion.]],
          TextMapId = "READ_DESC_2000032"
        },
        READ_DESC_2000033 = {
          ContentEN = [[
An informal register of military dogs maintained by an Imperial dog handler, carefully hidden deep inside a chariot's storage compartment.
Water damage has blurred the last few entries.]],
          TextMapId = "READ_DESC_2000033"
        },
        READ_DESC_2000034 = {
          ContentEN = [[
An emergency medical log stripped of formalities. It succinctly details the condition of casualties and the emergency treatments administered.
The handwriting on the page listing remaining medical supplies grows increasingly frantic as supplies dwindle, clearly mirroring the writer's escalating anxiety.]],
          TextMapId = "READ_DESC_2000034"
        },
        READ_DESC_2000035 = {
          ContentEN = "Transcripts of a discussion within The Forsakens about a new recruit who joined after the occupation of the fortress.",
          TextMapId = "READ_DESC_2000035"
        },
        READ_DESC_2000036 = {
          ContentEN = "A lost journal that belongs to someone from The Forsakens. According to the entries, the owner might be a healer.",
          TextMapId = "READ_DESC_2000036"
        },
        READ_DESC_2000037 = {
          ContentEN = "A neatly written letter that lies open on the desk, already read. It is addressed to Henrik Ethelred.",
          TextMapId = "READ_DESC_2000037"
        },
        READ_DESC_2000038 = {
          ContentEN = "A disordered heap of overdue notices scattered across the desk, all urging Henrik to settle his debts. It's evident that Hypnos' House has been under financial strain for some time.",
          TextMapId = "READ_DESC_2000038"
        },
        READ_DESC_2000039 = {
          ContentEN = "A stack of torn-off medicine labels, each marked \"Sedative.\" On the back of one, a message has been furiously scrawled.",
          TextMapId = "READ_DESC_2000039"
        },
        READ_DESC_2000040 = {
          ContentEN = "A scrap of paper with a short poem scrawled across it.",
          TextMapId = "READ_DESC_2000040"
        },
        READ_DESC_2000041 = {
          ContentEN = "A folder unearthed from the file cabinets. It bears Psyche's photo and details her time at the Hypnos' House.",
          TextMapId = "READ_DESC_2000041"
        }
      }
    end
  },
  {
    MinKey = "READ_DESC_2000042",
    MaxKey = "READ_NAME_20605",
    Loader = function()
      return {
        READ_DESC_2000042 = {
          ContentEN = "A folder unearthed from the file cabinets. It bears Elisa's photo and details her time at the Hypnos' House.",
          TextMapId = "READ_DESC_2000042"
        },
        READ_DESC_2000043 = {
          ContentEN = "A folder unearthed from the file cabinets. It bears Hunt's photo and details his time at the Hypnos' House.",
          TextMapId = "READ_DESC_2000043"
        },
        READ_DESC_2000044 = {
          ContentEN = [[
A collection of urban legends originally published in a now-defunct tabloid. In an empire ruled by alchemy and brute force, such tales weren't even worthy of dinner-table mockery.
Among its stories are "The Driverless Bus One Must Never Board After Ten" and "There Are No Pure Black Cats in Icelake." The tale presented here follows a man who believes humanity is nothing more than a colony of ants bred in captivity.]],
          TextMapId = "READ_DESC_2000044"
        },
        READ_DESC_2000045 = {
          ContentEN = "A sheet of parchment bearing the crest of the Forsakens. It appears to have been hastily balled up and tossed into the sewers. Across the bottom edge runs a single line in cramped script: \"May vengeance guide our path forward.\"",
          TextMapId = "READ_DESC_2000045"
        },
        READ_DESC_2000046 = {
          ContentEN = "A detailed log maintained by the backstage crew, documenting prop management at the Galea Theatre over the past two weeks.",
          TextMapId = "READ_DESC_2000046"
        },
        READ_DESC_2000047 = {
          ContentEN = "A medal forged entirely of pure gold. According to the accompanying commendation letter, this honour is reserved for soldiers whose contributions to the Empire are deemed exceptional beyond measure.",
          TextMapId = "READ_DESC_2000047"
        },
        READ_DESC_2000048 = {
          ContentEN = "Yellowed with age and buried beneath a heap of old clutter, this newspaper recounts a tragedy that took place in Icelake years ago.",
          TextMapId = "READ_DESC_2000048"
        },
        READ_DESC_2000049 = {
          ContentEN = "A handwritten record transcribed by Rhythm, describing a brawl that broke out mid-performance at the Galea Theatre two years ago.",
          TextMapId = "READ_DESC_2000049"
        },
        READ_DESC_2000050 = {
          ContentEN = "Judging by the tone, this journal likely belonged to Blues Fischer. Page after page is filled with memories from his everyday life with his sister — not a single corner left unused.",
          TextMapId = "READ_DESC_2000050"
        },
        READ_DESC_2000052 = {
          ContentEN = "A small notebook recovered from the sewers, its pages stiff with filth and dried blood. Most entries are now illegible.",
          TextMapId = "READ_DESC_2000052"
        },
        READ_DESC_2000053 = {
          ContentEN = "(These loose pages were found scattered in the theatre's corners, penned in Parsifal's hand. From the wear on the pages, it appears to be a script he studied often — perhaps hoping to one day take the stage himself.)\n\nOn the north-western cape beyond the reach of the Elysian Church, there once stood a duchy called Yashnia, a slender strip of land facing the Hyperborean Empire across the sea. A crossroads of trade and diplomacy, Yashnia balanced precariously between the Church and the Empire — until the Church annexed it more than three centuries ago.\nThough small in size, the duchy endured for generations. Its dukes clung to power through a history steeped in blood: palace intrigue, aulic murders, and political assassinations. In the centuries since, wandering bards have mined Yashnia's crimson legacy for their dramas and ballads. Even the Empire — despite its official ban on the dramatisation of royal assassinations — permits such plays to be performed, viewing them as a fitting indictment of the Church's bloody past. Among these works, Momiji: A Chronicle of Rebellion remains one of the most beloved, praised for its sweeping music, elaborate choreography, and stirring depictions of battle.",
          TextMapId = "READ_DESC_2000053"
        },
        READ_DESC_2000057 = {
          ContentEN = "A hymn sung at the Silvercandle Carnival, recounting its legendary origin: Soranus, younger brother to Dis Ⅰ, first emperor of Hyperborea, was struck down by the Charon. Yet after conquest was won, Dis Ⅰ chose not vengeance but peace, and held a great feast.\n From that feast is said to descend the Silvercandle Carnival as it is known today.",
          TextMapId = "READ_DESC_2000057"
        },
        READ_DESC_2000067 = {
          ContentEN = "A hand-scrawled flyer, its jagged script so fierce you can almost hear it shouting. Line by line it denounces the Silvercandle Hymn, proclaiming the truth turned on its head.",
          TextMapId = "READ_DESC_2000067"
        },
        READ_DESC_2000068 = {
          ContentEN = "The Asphodel's drinks menu — every glass, full-bodied and fragrant. One sip, and you'll be back for more.",
          TextMapId = "READ_DESC_2000068"
        },
        READ_DESC_2000069 = {
          ContentEN = "Rumours of the Forsakens' upper echelons — their credibility uncertain, but entertaining enough for a light read.",
          TextMapId = "READ_DESC_2000069"
        },
        READ_DESC_2000070 = {
          ContentEN = "The following is drawn from the writings of Comnena, a scholar of Aethyrie. Her histories are notoriously abstruse, diverging in places from the official records of the Hyperborean Empire — and thus seldom seen beyond the shelves of collectors. Indeed, such tomes are more often purchased as ornament than for study; a single set may languish five years before leaving a bookseller's hand.",
          TextMapId = "READ_DESC_2000070"
        },
        READ_DESC_2000072 = {
          ContentEN = "A survivor's early account of the Scourge of Zhuyin, told by a farmer from the mountain hamlets around Mistwharf.",
          TextMapId = "READ_DESC_2000072"
        },
        READ_DESC_2000073 = {
          ContentEN = "A tattered, heavily scribbled-over volume. Its author seems to have recorded countless case studies meant to teach readers how to seize the upper hand in argument... yet now it lies abandoned, cast aside by someone.",
          TextMapId = "READ_DESC_2000073"
        },
        READ_DESC_2000074 = {
          ContentEN = "Seems to be a chant praising Jishu Sect, though the lyrics are a jumble and hardly make sense. You can almost hear someone bellowing it wildly off-key in your head.",
          TextMapId = "READ_DESC_2000074"
        },
        READ_DESC_2000075 = {
          ContentEN = "A lazily titled serial novel. It follows a youth named Zhao Hao, who is chosen as the High Chancellor of Loongyuan. Wildly popular among Huaxu's young readers.",
          TextMapId = "READ_DESC_2000075"
        },
        READ_DESC_2000076 = {
          ContentEN = "An ink landscape of Huaxu, richly mounted and crowded with seals. Beside the artist's signature runs a single couplet — and on closer inspection, several of its characters appear just slightly amiss.",
          TextMapId = "READ_DESC_2000076"
        },
        READ_DESC_2000077 = {
          ContentEN = "These fantastical tales are said to have been told by an old man called Uncle Feng. They proved so entertaining that later generations gathered them into a single book. Though some adults find certain passages a touch unsettling, the collection is still printed across Huaxu and remains dearly loved by children.",
          TextMapId = "READ_DESC_2000077"
        },
        READ_DESC_2000078 = {
          ContentEN = "A notebook left by an unknown hand near Zhuyin Altar, its ink already blurred in places. It records in detail the ordeal its author faced here. None can know in what despair he set down these final words.",
          TextMapId = "READ_DESC_2000078"
        },
        READ_DESC_2000079 = {
          ContentEN = "A one-page list, likely jotted down in passing between cargo loading and unloading.",
          TextMapId = "READ_DESC_2000079"
        },
        READ_DESC_2000080 = {
          ContentEN = "The handwriting is chaotic, full of hurried crossings-out and smudges. You can almost feel the writer's agitation through the page. On the flyleaf, there is but a single character: \"Feng.\"",
          TextMapId = "READ_DESC_2000080"
        },
        READ_DESC_2000081 = {
          ContentEN = "A cultural study by a foreign scholar examining Huaxu's distinctive understanding of life and death.",
          TextMapId = "READ_DESC_2000081"
        },
        READ_DESC_2000082 = {
          ContentEN = "An unofficial overview of characters commonly used in Huaxu baby names in recent years, along with brief notes on their meanings. The sources are murky and the accuracy debatable — best approached as light reading, or simply for amusement.",
          TextMapId = "READ_DESC_2000082"
        },
        READ_DESC_2000083 = {
          ContentEN = "A contract dated to Year X of Dafeng, recording a loan taken by the merchant She Yuqing from Li Laoqian. The format is proper and the terms clearly stated — though one \"0\" in the multiplier has been written in a markedly smaller hand, small enough to elude even the sharpest eyes.",
          TextMapId = "READ_DESC_2000083"
        },
        READ_DESC_2000084 = {
          ContentEN = "Compiled by officials of Xuanheng Sect, this manual sets out the proper procedures for the incense-offering rite at the Argent Loong Temple.",
          TextMapId = "READ_DESC_2000084"
        },
        READ_DESC_2000085 = {
          ContentEN = "One volume from Luoxiang's Case Notes. As a community mediator, Luoxiang applies her understanding of the Nine Chapters of Dafeng to everyday disputes, collecting her experiences into this series. Down-to-earth and practical, it has unexpectedly become a popular household read.",
          TextMapId = "READ_DESC_2000085"
        },
        READ_DESC_2000086 = {
          ContentEN = "This piece is part of Xu Xingke's Footsteps collection. Commissioned by Huaxu's local council, the renowned travel writer records his reflections on the many regions of his homeland.",
          TextMapId = "READ_DESC_2000086"
        },
        READ_DESC_2000087 = {
          ContentEN = "Penned by the Starweavers themselves, this chronicle records the lives of their members in biographical form. As years pass and generations come and go, the task is taken up anew by each successor.",
          TextMapId = "READ_DESC_2000087"
        },
        READ_DESC_2000088 = {
          ContentEN = "A compiled record of project proposals submitted by members of the Greenwich Archaeological Society, each annotated with handwritten directives from Mr Qiu.",
          TextMapId = "READ_DESC_2000088"
        },
        READ_DESC_2000089 = {
          ContentEN = "A pocket notebook Lunocarp keeps close at all times — now in its seventh volume. Inside are bursts of inspiration, scribbled down whenever they strike, whether in a sudden spark or after long deliberation. And in these newest pages, the influence of her latest muse is unmistakable: Snow the \"Demon King\", a traveller from far-off Hyperborea.",
          TextMapId = "READ_DESC_2000089"
        },
        READ_DESC_2000090 = {
          ContentEN = "A brief formal directive issued by EverSpring.",
          TextMapId = "READ_DESC_2000090"
        },
        READ_DESC_2000091 = {
          ContentEN = "A letter addressed to the leader of a Huaxu trade caravan, apparently written by one of his former students.",
          TextMapId = "READ_DESC_2000091"
        },
        READ_DESC_2000092 = {
          ContentEN = "A memoir in Mr Qiu's own voice, chronicling how he shaped the black market into its present form.",
          TextMapId = "READ_DESC_2000092"
        },
        READ_DESC_2000096 = {
          ContentEN = "A journal left behind in Glevum Pit. The tone suggests it might belong to a scholar.",
          TextMapId = "READ_DESC_2000096"
        },
        READ_DESC_2000097 = {
          ContentEN = "A journal left behind in Glevum Pit, stained dark red. The handwriting matches the earlier journal found. The latter part is extremely messy, as if it was scribbled in frantic haste.",
          TextMapId = "READ_DESC_2000097"
        },
        READ_DESC_2000098 = {
          ContentEN = "A handwritten note, its bold and forceful strokes carrying the unmistakable severity of an older hand.",
          TextMapId = "READ_DESC_2000098"
        },
        READ_DESC_2000099 = {
          ContentEN = "A treatise that appears to set down the rites governing Huaxu's Grand Incense Rite. It enumerates the sacrificial observances of antiquity in meticulous detail and concludes with marginal notes left by an unidentified hand.",
          TextMapId = "READ_DESC_2000099"
        },
        READ_DESC_2000100 = {
          ContentEN = "A set of notes left by a foreign scholar investigating the origins of Huaxu's Grand Incense Rite. The date of composition is unknown. Many of the author's conjectures lack corroborating records or material evidence, and most of the text is not recognised as credible by modern historians.",
          TextMapId = "READ_DESC_2000100"
        },
        READ_DESC_2000101 = {
          ContentEN = "A tale of Yin Qing, a poet of ancient Huaxu, drawn from Bygone Fragments, an essay collection by the later author Cang Xian. In it, a young traveller known only as Feng — his family name now lost to history — drifts into Haojing and discovers a green leaf inscribed with a poem drifting along a waterway beside the Yin residence — a small happenstance that binds their fates.\n\npreserves a number of literary anecdotes from roughly five centuries past, steeped in the flavour of legend. Its reliability as a historical source remains open to question, yet its value as literature is widely acknowledged.",
          TextMapId = "READ_DESC_2000101"
        },
        READ_DESC_2000102 = {
          ContentEN = "An excerpt from Xu Xingke's Footsteps Across Huaxu, an officially commissioned travelogue. In it, Xu sets down his impressions of his homeland — its regions, its people, and the ideas they awaken.",
          TextMapId = "READ_DESC_2000102"
        },
        READ_DESC_2000103 = {
          ContentEN = [[
Huaxu Trends tracks what's trending across Huaxu: new places to eat and drink, clothing and everyday essentials, and lifestyles arriving from overseas and taking hold at home.
Each year, the Haojing Special drops a month before the Grand Incense Rite, spotlighting the capital's latest go-to spots for food, leisure, and nightlife.]],
          TextMapId = "READ_DESC_2000103"
        },
        READ_DESC_2000104 = {
          ContentEN = [[
A short piece praising the Nine Chapters of Dafeng, written in Huaxu's distinctive panegyric style.
From the wording and the marginal note appended below, the author appears to be a student still learning the craft of writing.]],
          TextMapId = "READ_DESC_2000104"
        },
        READ_DESC_2000105 = {
          ContentEN = "A celebrated Huaxu classic, reputedly written by a master of Xuanheng Sect. The work runs to seventeen volumes, with additions made by later generations. The excerpt below is drawn from the book's preface.",
          TextMapId = "READ_DESC_2000105"
        },
        READ_DESC_2000106 = {
          ContentEN = "A folk opera script popular among Huaxu's commoners. It follows a young couple from first meeting to marriage, only for petty quarrels and everyday slights to sour things afterwards. Said to be adapted from a real case in Haojing, though this cannot be verified. Excerpt follows.",
          TextMapId = "READ_DESC_2000106"
        },
        READ_DESC_2000107 = {
          ContentEN = [[
A young artisan's personal notes, loosely recording a few ways to make scented sachets.
It isn't a proper how-to, and the steps aren't laid out in full. Best enjoyed as a casual read.]],
          TextMapId = "READ_DESC_2000107"
        },
        READ_DESC_2000108 = {
          ContentEN = "A substantial volume detailing the Ministry of Works' most recent public projects.",
          TextMapId = "READ_DESC_2000108"
        },
        READ_DESC_2000109 = {
          ContentEN = "A record of Master Zhuxi's sayings, written down by his students. His views shifted with age, yet his words were preserved throughout his life, from his earliest years to his last. Excerpt follows.",
          TextMapId = "READ_DESC_2000109"
        },
        READ_DESC_2000110 = {
          ContentEN = [[
Most fresh faces in Outer Peaks get told the same thing on their first day: "Done with your errands? Go take a look at the training yard."
It was originally set up so the Drifters could spar and hone their craft, but over time, it has picked up a few... additional uses.]],
          TextMapId = "READ_DESC_2000110"
        },
        READ_DESC_2000111 = {
          ContentEN = "A workshop logbook where Outer Peaks' artisans jot down their wild ideas and odd contraptions. In the name of \"learning from one another\", Uncle Tang later insisted on adding a comment board so everyone could leave their thoughts underneath.",
          TextMapId = "READ_DESC_2000111"
        },
        READ_DESC_2000112 = {
          ContentEN = "An anonymous miscellany from Huaxu, offering a detailed account of the rules and procedures of the Incense Trial.",
          TextMapId = "READ_DESC_2000112"
        },
        READ_DESC_2000113 = {
          ContentEN = "A tongue-in-cheek essay that claims to explain how to become High Chancellor of Loongyuan. So exaggerated and irreverent that it's hard to tell where fact ends and invention begins.",
          TextMapId = "READ_DESC_2000113"
        },
        READ_DESC_2000114 = {
          ContentEN = "A daily paper printed by the Hall of Craft and sold on the streets of Haojing. Mostly local happenings and the occasional public notice. Truth be told, it has never had many readers.",
          TextMapId = "READ_DESC_2000114"
        },
        READ_DESC_2000115 = {
          ContentEN = "A daily paper printed by the Hall of Craft and sold on the streets of Haojing. Mostly local happenings and the occasional public notice. Truth be told, it has never had many readers.",
          TextMapId = "READ_DESC_2000115"
        },
        READ_DESC_2000116 = {
          ContentEN = "A book set down by a man of letters surnamed Shen. Its authenticity cannot be verified, but it remains an entertaining read. Much of the text has been lost to time. This is Part Ⅱ.",
          TextMapId = "READ_DESC_2000116"
        },
        READ_DESC_2000118 = {
          ContentEN = "A printed poster found in the underground ironworks beneath Bloomfield Station. It appears to have been ripped down from wherever it was originally posted and tossed aside. Whoever removed it was clearly furious about its contents; when unfolded, even the corners are flecked with something that looks suspiciously like spit...",
          TextMapId = "READ_DESC_2000118"
        },
        READ_DESC_2000119 = {
          ContentEN = "A factory recruitment poster displayed at the station entrance. Its claims are emphatic, its tone fervent — enough to stir the blood of any young reader. Strangely, someone has scrawled a smiley face across it... perhaps in wholehearted approval of its message.",
          TextMapId = "READ_DESC_2000119"
        },
        READ_DESC_2000120 = {
          ContentEN = "A plain sheet of white paper. The writing is crooked and uneven, the lines slanting across the page with no proper order. Punctuation appears only here and there, wherever the writer happened to remember it. Wrong words and misspellings appear throughout. You can still make out what it says, but as a will, it contains no instructions worth carrying out — only a rambling account of a life that seems to have left nothing behind.",
          TextMapId = "READ_DESC_2000120"
        },
        READ_DESC_2000121 = {
          ContentEN = "A shared document circulated among members of the Steamwhistle Salon, containing a series of thoroughly absurd rules of conduct. The first few pages are neatly written and clearly structured, setting out the Salon's existing rules and internal systems. Between the lines and across the margins, handwritten notes have been crammed into every spare inch — fervent, almost fanatical declarations of devotion to their beloved Stationmaster.",
          TextMapId = "READ_DESC_2000121"
        },
        READ_DESC_2000122 = {
          ContentEN = "An activity report concerning Eisenbahn, with precise records of times, locations, and observed activities. Written in a detached, clinical tone, it records his movements and routines in exhaustive detail — as if the author were a shadow trailing a few steps behind him.\nIts complete lack of personal feeling stands in stark contrast to the usual fervour of the Steamwhistle Salon, giving the document an oddly suspicious quality.",
          TextMapId = "READ_DESC_2000122"
        },
        READ_DESC_2000123 = {
          ContentEN = "A soft-bound ledger containing no ordinary income or expenditure records. Instead, it serves as the Steamwhistle Salon's main channel for exchanging and trading merchandise related to their beloved idol, Stationmaster Eisenbahn.\nTo those who worship Eisenbahn with near-fanatical devotion, the ledger is more precious than their own lives — a \"Sacred Ledger\" not to be defiled.",
          TextMapId = "READ_DESC_2000123"
        },
        READ_DESC_2000124 = {
          ContentEN = "A serial novel with a sloppy title, set against the backdrop of the decades-old war between Hyperborea and Elysium, centring on the adventures of a Hyperborean boy. Published as a companion title to The Invincible Legion Chief, it is a favourite among the Empire's youth.",
          TextMapId = "READ_DESC_2000124"
        },
        READ_DESC_2000125 = {
          ContentEN = "A ledger apparently left in the station's left-luggage office by Handy, who was later executed on Eisenbahn's orders. Packed with figures and complex entries, it is enough to make your head spin at a glance. What remains unclear is why it was enough to cost Handy his life.",
          TextMapId = "READ_DESC_2000125"
        },
        READ_DESC_2000126 = {
          ContentEN = "A report alarming enough to give officials across the Empire a collective headache.",
          TextMapId = "READ_DESC_2000126"
        },
        READ_DESC_20600 = {
          ContentEN = "A collection of enigmatic pages discovered by chance. Some are delicate scrolls of fine parchment; others, freshly printed sheets with ink still crisp and dark. A few are no more than torn scraps from half-used notebooks. Whether neatly penned or barely legible, they all share one thing in common — each contains a hint pointing to the whereabouts of a hidden treasure.",
          TextMapId = "READ_DESC_20600"
        },
        READ_FUNCTION_20600 = {
          ContentEN = "Lost Sheet",
          TextMapId = "READ_FUNCTION_20600"
        },
