        RESOURCE_DESC_122 = {
          ContentEN = "A recurring Phoxene delivery arranged through Lunotress. Grants a daily supply for the duration of the subscription.",
          TextMapId = "RESOURCE_DESC_122"
        },
        RESOURCE_DESC_123 = {
          ContentEN = "A neatly bound Hardcover Edition compiling once-scattered verses.",
          TextMapId = "RESOURCE_DESC_123"
        },
        RESOURCE_DESC_124 = {
          ContentEN = "A finely bound Collector's Edition compiling once-scattered verses.",
          TextMapId = "RESOURCE_DESC_124"
        },
        RESOURCE_DESC_125 = {
          ContentEN = "Redeemable for one Geniemon of your choice from the Lore Compilation reward pool. A testament to your journey, and a token of gratitude.",
          TextMapId = "RESOURCE_DESC_125"
        },
        RESOURCE_DESC_19000 = {
          ContentEN = "Where countless threads of the heart entwine, a Soulprint takes form — Tapestry.",
          TextMapId = "RESOURCE_DESC_19000"
        },
        RESOURCE_DESC_19001 = {
          ContentEN = "Where threads of the heart entwine, a Soulprint takes form — Joy.",
          TextMapId = "RESOURCE_DESC_19001"
        },
        RESOURCE_DESC_19002 = {
          ContentEN = "Where threads of the heart entwine, a Soulprint takes form — Sorrow.",
          TextMapId = "RESOURCE_DESC_19002"
        },
        RESOURCE_DESC_19003 = {
          ContentEN = "Where threads of the heart entwine, a Soulprint takes form — Fear.",
          TextMapId = "RESOURCE_DESC_19003"
        },
        RESOURCE_DESC_19004 = {
          ContentEN = "Where threads of the heart entwine, a Soulprint takes form — Anger.",
          TextMapId = "RESOURCE_DESC_19004"
