        RESOURCE_DESC_19007 = {
          ContentEN = "Where threads of the heart entwine, a Soulprint takes form — Uncertainty.",
          TextMapId = "RESOURCE_DESC_19007"
        },
        RESOURCE_DESC_19008 = {
          ContentEN = "Where threads of the heart entwine, a Soulprint takes form — Longing.",
          TextMapId = "RESOURCE_DESC_19008"
        },
        RESOURCE_DESC_200 = {
          ContentEN = "A highly valuable ornate statue specially designed for holding Crystallo.",
          TextMapId = "RESOURCE_DESC_200"
        },
        RESOURCE_DESC_20001 = {
          ContentEN = "Keratin grown from the skin of Filthoids, forming their hardest armor. Processed with special techniques, it can be used for protection in weapons and armor.",
          TextMapId = "RESOURCE_DESC_20001"
        },
        RESOURCE_DESC_20002 = {
          ContentEN = "A shattered Sal Volatile bottle with deep scratches and bullet holes. Its contents leaked out but the glass bottle can be recycled.",
          TextMapId = "RESOURCE_DESC_20002"
        },
        RESOURCE_DESC_20003 = {
          ContentEN = "Cleansing Water used by the Elysian Church devotees to cleanse their hands before ceremonies, usually kept in blessed containers inside temples.",
          TextMapId = "RESOURCE_DESC_20003"
        },
        RESOURCE_DESC_20004 = {
          ContentEN = "Carried by Hyperborean soldiers, engraved with their name, rank, legion, and enlistment date. If a soldier falls in battle, their legion uses the name plate to identify them, and it is sent back to their hometown as a mark of honour.",
          TextMapId = "RESOURCE_DESC_20004"
        },
        RESOURCE_DESC_20005 = {
          ContentEN = "Natural stone powder, commonly used as a consumable in alchemy and construction. The type of ore varies in colour due to geographical differences, making it a primary material for paint pigments.",
          TextMapId = "RESOURCE_DESC_20005"
        },
        RESOURCE_DESC_20006 = {
          ContentEN = "Parchment scrolls carried by Elysian knights, inscribed with blessings and prayers. Knights draw strength from these blessings in battle.",
          TextMapId = "RESOURCE_DESC_20006"
        },
        RESOURCE_DESC_20007 = {
          ContentEN = [[
A roll of cable with a Hyperborean mark, collected in a somewhat brutal way. 
Be careful of electric shocks before the sparks die out.]],
          TextMapId = "RESOURCE_DESC_20007"
        },
        RESOURCE_DESC_20008 = {
          ContentEN = "Solid crystals harvested from rare Filthoids. Commonly used for intricate research into the biology of these enigmatic creatures.",
          TextMapId = "RESOURCE_DESC_20008"
        },
        RESOURCE_DESC_20009 = {
          ContentEN = [[
Common wild plants. The flowers are usually muti-petaled, bright red, and glossy. They are hardy, drought-resistant, and adaptable, hence widespread across the continent. 
They are said to be the tears Father Ask shed for the deceased Mother Embla during his journey to find her in Charon's mythology.]],
          TextMapId = "RESOURCE_DESC_20009"
        },
        RESOURCE_DESC_2001 = {
          ContentEN = "It's the testament to your journey through thick and thin, the echoes of your laughter and tears, and the essence of your hard-earned wisdom — remember? You are neither frail nor alone.",
          TextMapId = "RESOURCE_DESC_2001"
        },
        RESOURCE_DESC_20010 = {
          ContentEN = [[
A creeping plant commonly found in shaded areas, highly flexible with intertwined fibers. After processing, they are used in various applications, and they are durable and resistant to wear. 
Said to be the inspiration for cable design.]],
          TextMapId = "RESOURCE_DESC_20010"
        },
        RESOURCE_DESC_20011 = {
          ContentEN = "A thick grease extracted from Filthoids. Its viscosity often correlates with the Filthoid's strength.",
          TextMapId = "RESOURCE_DESC_20011"
        },
        RESOURCE_DESC_20012 = {
          ContentEN = "Produced from the Elysian Church. Their knight's standard attire has a fine chainmail made of numerous delicate chains. The clanking of the chainmail is the best declaration of battle as the knights march.",
          TextMapId = "RESOURCE_DESC_20012"
        },
        RESOURCE_DESC_20013 = {
          ContentEN = "A currency unique to the Lunos, often given as a thank-you gift by those seeking help.",
          TextMapId = "RESOURCE_DESC_20013"
        },
        RESOURCE_DESC_20014 = {
          ContentEN = "Snowswift is a bird native to cold regions, commonly seen around Icelake. Known for their blistering speed in flight, these elusive creatures are rarely spotted by the naked eye, except during snowfalls when they perch quietly on branches or nestle in their nests. Historically, their tough feathers were prized for crafting traditional quills. Today, however, only a handful of traditionalists and those less fortunate continue to use these economical, albeit less durable, feather pens.",
          TextMapId = "RESOURCE_DESC_20014"
        },
        RESOURCE_DESC_20015 = {
          ContentEN = "A replaceable metal armor from the Hyperborean Empire on soldiers' standard uniforms, usually fitted at joints, with excellent shock resistance, and has been mass-produced. Two spare armors are now standard for a Hyperborean assault soldier.",
          TextMapId = "RESOURCE_DESC_20015"
        },
        RESOURCE_DESC_20016 = {
          ContentEN = "Produced from the Elysian Church, a shield-shaped ornament worn by the Elysian Church soldiers. It's believed to be imbued with divine blessings, symbolizing the will to protect the church.",
          TextMapId = "RESOURCE_DESC_20016"
        },
        RESOURCE_DESC_20017 = {
          ContentEN = "Produced from Hyperborea. Ensuring the legion's mobility has always been a key subject to the Aeolipile. Vehicle armor, serving as an external accessory, withstands extreme weather and allows the vehicle to hold up longer under gunfire. It can be quickly removed for full-speed advance.",
          TextMapId = "RESOURCE_DESC_20017"
        },
        RESOURCE_DESC_20018 = {
          ContentEN = [[
The Statue of the Goddess of Fate built by the Elysian Church, now too damaged to discern its original form, but still exuding elegance among its ruins. 
Over time, new sprouts grow here. Under the decoration of vitality, myths never seem to fade.]],
          TextMapId = "RESOURCE_DESC_20018"
        },
        RESOURCE_DESC_20019 = {
          ContentEN = "A concentrated combustion aid developed by the Alchemy Academy. A pungent, colourless liquid dyed red to denote danger. Used only in military or industrial settings. A few spoonfuls can send a fireplace's flames roaring up the chimney, and that's definitely an unwanted spectacle.",
          TextMapId = "RESOURCE_DESC_20019"
        },
        RESOURCE_DESC_2002 = {
          ContentEN = "Verses inspired from the stories of your adventure. Once all have been found, a new ballad shall emerge.\nTranscribed and adapted by Lirico, these lines ride the wind and falling leaves, echoing through the skies of Atlasia — sung by bards, shaped by your every step.",
          TextMapId = "RESOURCE_DESC_2002"
        },
        RESOURCE_DESC_20020 = {
          ContentEN = "A common industrial material. A viscous white latex-like liquid that maintains a balance in temperature. Given the unpredictability of terrain and climate on adventures, carrying a few cans is wise. The manufacturer recently introduced fruit and floral scents, so consumers are hereby warned to beware of accidental ingestion.",
          TextMapId = "RESOURCE_DESC_20020"
        },
        RESOURCE_DESC_20021 = {
          ContentEN = "Candles used in church ceremonies, accompanied by devoutly crafted candlesticks. Though their burn time is brief, their light suffices to illuminate the face of divine.",
          TextMapId = "RESOURCE_DESC_20021"
        },
        RESOURCE_DESC_20022 = {
          ContentEN = [[
One of the alchemical products of the Hyperborean Empire. A liquid metal that seems like it could flow through your fingers at any moment. Made using a complex purification process. It's usually employed in the military industry.
If you can't handle their melting point, it is recommended not to heat them recklessly.]],
          TextMapId = "RESOURCE_DESC_20022"
        },
        RESOURCE_DESC_20023 = {
          ContentEN = "A special product from the other side of the desert. It can be crafted into exquisite decorations or used to strengthen components. The final quality depends on how much real sand gets mixed in during transportation—since it is hard to distinguish between the two, deal with trusted merchants if necessary.",
          TextMapId = "RESOURCE_DESC_20023"
        },
        RESOURCE_DESC_20024 = {
          ContentEN = [[
A tentacle obtained from Filthoids, must be cleaned of mucus before use. They are very tough and have strong adhesive properties, sometimes used as fixation devices. 

These walking materials are everywhere, but not many can make them lie still on the chopping board.]],
          TextMapId = "RESOURCE_DESC_20024"
        },
        RESOURCE_DESC_20025 = {
          ContentEN = "A precision instrument made by the Hyperborean Empire, still intact despite being covered in scratches and pry marks.",
          TextMapId = "RESOURCE_DESC_20025"
        },
        RESOURCE_DESC_20026 = {
          ContentEN = [[
A book with intricate decorations, appears to be a valuable collection of poems, but is actually a codebook for deciphering internal legion radio communications. 
Unfortunately, the inner pages are damaged, leaving only some irrelevant secret codes that can't really be used to decrypt telegrams.]],
          TextMapId = "RESOURCE_DESC_20026"
        },
        RESOURCE_DESC_20027 = {
          ContentEN = "Produced from the Elysian Church, a honey-like oily liquid that increases the sharpness of cold weapons and also maintains firearms. Almost every soldier of the assembly carries a few bottles with them, and during breaks, they can be seen carefully applying the potion to their weapons and silently reciting prayers for repelling enemies.",
          TextMapId = "RESOURCE_DESC_20027"
        },
        RESOURCE_DESC_20028 = {
          ContentEN = "Produced from the Hyperborean Empire, a type of modified bullet that can explode. Equipped with a variety of interchangeable heads for different functional needs, experts can use different bullet characteristics to explode exactly where they want.",
          TextMapId = "RESOURCE_DESC_20028"
        },
        RESOURCE_DESC_20029 = {
          ContentEN = "A widely used auxiliary bracket equipped with various clasps for a stable structure, allowing craftsmen to fix weapons on it for adjustment.",
          TextMapId = "RESOURCE_DESC_20029"
        },
        RESOURCE_DESC_2003 = {
          ContentEN = "Earned by completing daily tasks. Use it to claim your daily reward.\nFrom grand quests to the simplest errands, each mark brings you closer to your goal — proof that no effort goes unnoticed.",
          TextMapId = "RESOURCE_DESC_2003"
        },
        RESOURCE_DESC_20030 = {
          ContentEN = "A specialized spraying device for equipment, used to uniformly apply rust-proofing agents to extend the durability of equipment, and increase the performance of some weapons. Mixing it up with serum injectors can have severe consequences, so it must be used with caution.",
          TextMapId = "RESOURCE_DESC_20030"
        },
        RESOURCE_DESC_20031 = {
          ContentEN = "A polymer made from the concentrated tissues of Filthoids, resembling a tumor and surrounded by some tentacles, supposedly. The methods of producing and using Filthoid polymers apparently originated from the Spathatoi.",
          TextMapId = "RESOURCE_DESC_20031"
        },
        RESOURCE_DESC_20032 = {
          ContentEN = "A cold liquid collected from the north, stored in special containers. Even at room temperature, ice crystals form on the surface of the container. This notion, often found in poetry, is now used as a coolant.",
          TextMapId = "RESOURCE_DESC_20032"
        },
        RESOURCE_DESC_20033 = {
          ContentEN = [[
A sigil for cancelling summons.
The companionship might be fleeting, yet the friendship endures. Perhaps the next reunion is merely a heartbeat away.]],
          TextMapId = "RESOURCE_DESC_20033"
        },
        RESOURCE_DESC_2004 = {
          ContentEN = "Verses inspired from the stories of your adventure. Once all have been found, a new ballad shall emerge.\nTranscribed and adapted by Lirico, these lines ride the wind and falling leaves, echoing through the skies of Atlasia — sung by bards, shaped by your every step.",
          TextMapId = "RESOURCE_DESC_2004"
        },
        RESOURCE_DESC_2005 = {
          ContentEN = "Points earned from [Returnee Quests]. Used to claim milestone rewards.",
          TextMapId = "RESOURCE_DESC_2005"
        },
        RESOURCE_DESC_2007 = {
          ContentEN = "A book about the use of weapons, it looks very thick, and this accumulation will turn into your strength.",
          TextMapId = "RESOURCE_DESC_2007"
        },
        RESOURCE_DESC_201 = {
          ContentEN = "Produced from the Hyperborean Empire, a precision instrument very similar to a toolbox. When its gears start to move, the Demon Wedge placed inside will be modified to better suit the user's state. Because it acts directly on the user, this style has higher precision, and after use, it can further enhance the user's abilities.",
          TextMapId = "RESOURCE_DESC_201"
        },
        RESOURCE_DESC_2011 = {
          ContentEN = "A single sheet of music, recording heroic epics passed among minstrels, filled with many handwritten annotations and modifications. To fully express their views, poets didn't hesitate to use tiny writing to exchange and debate in every blank space on the paper, where numerous perspectives are established and then overturned, making reading the entire piece a thrilling experience.",
          TextMapId = "RESOURCE_DESC_2011"
        },
        RESOURCE_DESC_2015 = {
          ContentEN = "\"You're kind of a big deal at The Asphodel these days. Those drunks won't stop spinning tales about you — most of it's made up.\"",
          TextMapId = "RESOURCE_DESC_2015"
        },
        RESOURCE_DESC_2016 = {
          ContentEN = "\"So you're the hotshot the Starweavers have been talking about out on the road.\"",
          TextMapId = "RESOURCE_DESC_2016"
        },
        RESOURCE_DESC_202 = {
          ContentEN = "Produced from the Hyperborean Empire, a precision instrument very similar to a toolbox. When its gears start to move, the Demon Wedge placed inside will be modified to better suit the user's state. This style has good detection capabilities for various types of weapons, and its use can further increase the weapon's abilities.",
          TextMapId = "RESOURCE_DESC_202"
        },
        RESOURCE_DESC_203 = {
          ContentEN = "Everything is destined to burn, to be devoured and reduced to ashes, ultimately sinking into the abyss.",
          TextMapId = "RESOURCE_DESC_203"
        },
        RESOURCE_DESC_204 = {
          ContentEN = "A tonic developed by the Alchemy Academy to enhance stamina. Commonly issued as part of standard military supplies.",
          TextMapId = "RESOURCE_DESC_204"
        },
        RESOURCE_DESC_205 = {
          ContentEN = "A shard of a sacred relic recovered from the Abyss across countless cycles of revival. It appears to bear a blessing beyond mortal ken.",
          TextMapId = "RESOURCE_DESC_205"
        },
        RESOURCE_DESC_20500 = {
          ContentEN = "A little key that someone left behind. It can be used to open a locked chest.",
          TextMapId = "RESOURCE_DESC_20500"
        },
        RESOURCE_DESC_20510 = {
          ContentEN = "Judging from its texture, it seems to be a fragment coming from the Statue of the Goddess of Fate in Arcane Ruins of Purgatorio Island. Maybe something good would happen once it's used to fix the statue.",
          TextMapId = "RESOURCE_DESC_20510"
        },
        RESOURCE_DESC_20511 = {
          ContentEN = "Primitive ores scattered in the wild; might be somewhat valuable with some forging.",
          TextMapId = "RESOURCE_DESC_20511"
        },
        RESOURCE_DESC_20512 = {
          ContentEN = "A silver coin without owner. It's hard to find its owner.",
          TextMapId = "RESOURCE_DESC_20512"
        },
        RESOURCE_DESC_20513 = {
          ContentEN = "Though not precious in the eyes of the refining market, these clear and sparkling ores hold the heart's true value, which can become the first piece of jewelry given to a beloved one.",
          TextMapId = "RESOURCE_DESC_20513"
        },
        RESOURCE_DESC_20514 = {
          ContentEN = "An old shield. It was discarded for no reason.",
          TextMapId = "RESOURCE_DESC_20514"
        },
        RESOURCE_DESC_20515 = {
          ContentEN = "A long lost medal. Its former owner once used it to exchange current coins.",
          TextMapId = "RESOURCE_DESC_20515"
        },
        RESOURCE_DESC_20516 = {
          ContentEN = "When it comes to waste items, the first things that always come to mind are empty bottles and cans. Collecting a small amount and selling them can help people maintain basic food and clothing, but that's all it can do.",
          TextMapId = "RESOURCE_DESC_20516"
        },
        RESOURCE_DESC_20517 = {
          ContentEN = "It can be used to make simple tools or for heating, the most basic things for survival in the wilderness.",
          TextMapId = "RESOURCE_DESC_20517"
        },
        RESOURCE_DESC_20518 = {
          ContentEN = "A gemstone that has rested on the hand of a goddess statue on Purgatorio Island for a very long time. If it could speak, it would surely have many stories to tell, but it is, in fact, just a radiant and splendid gem.",
          TextMapId = "RESOURCE_DESC_20518"
        },
        RESOURCE_DESC_206 = {
          ContentEN = [[
Increases commission rewards by 100%.
As your team, The Noctoyagers, rise to prominence among the Phoxhunters, more and more commissions come your way. While this entails heavier responsibilities, it also leads to greater rewards.]],
          TextMapId = "RESOURCE_DESC_206"
        },
        RESOURCE_DESC_207 = {
          ContentEN = [[
Increases commission rewards by 200%.
As your team, The Noctoyagers, rise to prominence among the Phoxhunters, more and more commissions come your way. While this entails heavier responsibilities, it also leads to greater rewards.]],
          TextMapId = "RESOURCE_DESC_207"
        },
        RESOURCE_DESC_208 = {
          ContentEN = [[
Increases commission rewards by 800%.
As your team, The Noctoyagers, rise to prominence among the Phoxhunters, more and more commissions come your way. While this entails heavier responsibilities, it also leads to greater rewards.]],
          TextMapId = "RESOURCE_DESC_208"
        },
        RESOURCE_DESC_209 = {
          ContentEN = [[
Increases commission rewards by 2000%.
As your team, The Noctoyagers, rise to prominence among the Phoxhunters, more and more commissions come your way. While this entails heavier responsibilities, it also leads to greater rewards.]],
          TextMapId = "RESOURCE_DESC_209"
        },
        RESOURCE_DESC_210 = {
          ContentEN = "A coin stamped with the emblem of a fish — treasured by anglers far and wide. The more you collect, the higher you climb in the fishing ranks. Trade them in for better gear and prove yourself the slickest fish hunter out there.",
          TextMapId = "RESOURCE_DESC_210"
        },
        RESOURCE_DESC_211 = {
          ContentEN = "For Phoxhunters, gathering whispers and weaving clues are part of the craft. With persistent cultivation and accumulation, a steady stream of commissions will soon follow.",
          TextMapId = "RESOURCE_DESC_211"
        },
        RESOURCE_DESC_214 = {
          ContentEN = "Etched with stage-light and heartbeat, it keeps the show's afterglow. Redeemable for various items.",
          TextMapId = "RESOURCE_DESC_214"
        },
        RESOURCE_DESC_215 = {
          ContentEN = "Spun from a tangle of paths, this thread bears silent witness to your every step. All that is uncertain, all that faltered, all left unresolved... shall one day find its answer along Her silken weave.",
          TextMapId = "RESOURCE_DESC_215"
        },
        RESOURCE_DESC_216 = {
          ContentEN = "Challenging commissions and extraordinary adventures have shaped the Phoxhunters' legend — a tale carried through every street and alley.",
          TextMapId = "RESOURCE_DESC_216"
        },
        RESOURCE_DESC_217 = {
          ContentEN = "Unlocks the Apex Rankings challenge in the \"Phoxhunter Summit\" event",
          TextMapId = "RESOURCE_DESC_217"
        },
        RESOURCE_DESC_218 = {
          ContentEN = "Used to redeem items in the Apex Shop of the \"Phoxhunter Summit\" event",
          TextMapId = "RESOURCE_DESC_218"
        },
        RESOURCE_DESC_219 = {
          ContentEN = "Used to redeem for items at Master Gongshang's Gifts during Great Chaos of Mechapuppets.",
          TextMapId = "RESOURCE_DESC_219"
        },
        RESOURCE_DESC_221 = {
          ContentEN = [[
A commemorative coin that gleams like starlight. Exchange it for various rewards.
Dress to impress and shine like a star.]],
          TextMapId = "RESOURCE_DESC_221"
        },
        RESOURCE_DESC_222 = {
          ContentEN = "A commemorative keepsake from the theatre, inscribed with the legends and emotions of every stage. Can be exchanged for special rewards.",
          TextMapId = "RESOURCE_DESC_222"
        },
        RESOURCE_DESC_29001 = {
          ContentEN = "Tokens said to lie scattered across Purgatorio Island. They stand as proof of courage, wisdom, and patience — virtues forged through the trials of adventure. Gather enough and present them to the Lunoxplorer in Icelake's town square to earn valuable rewards.",
          TextMapId = "RESOURCE_DESC_29001"
        },
        RESOURCE_DESC_29002 = {
          ContentEN = "Tokens said to lie scattered across Icelake. They stand as proof of courage, wisdom, and patience — virtues forged through the trials of adventure. Gather enough and present them to the Lunoxplorer in Icelake's town square to earn valuable rewards.",
          TextMapId = "RESOURCE_DESC_29002"
        },
        RESOURCE_DESC_29003 = {
          ContentEN = "Tokens said to lie scattered across Lonza Fortress. They stand as proof of courage, wisdom, and patience — virtues forged through the trials of adventure. Gather enough and present them to the Lunoxplorer in Icelake's town square to earn valuable rewards.",
          TextMapId = "RESOURCE_DESC_29003"
        },
        RESOURCE_DESC_29004 = {
          ContentEN = "Tokens said to lie scattered across Mistwharf — proof of courage, wisdom, and patience, each forged through trials of adventure. Gather enough, and present them to the Lunoxplorer in Haze Market to earn valuable rewards.",
          TextMapId = "RESOURCE_DESC_29004"
        },
        RESOURCE_DESC_29005 = {
          ContentEN = "Glowing runes that hover in the air throughout Huaxu, believed to manifest when Taixu is awakened by incense. They can be collected using the Mechanical Nexus.",
          TextMapId = "RESOURCE_DESC_29005"
        },
        RESOURCE_DESC_29006 = {
          ContentEN = "Tokens said to lie scattered across Haojing — proof of courage, wisdom, and patience, each forged through trials of adventure. Gather enough, and present them to the Lunoxplorer in Haojing to earn valuable rewards.",
          TextMapId = "RESOURCE_DESC_29006"
        },
        RESOURCE_DESC_3000001 = {
          ContentEN = "A box of paper stars crafted from expired tickets. It's said that a certain number of these can bless one's wishes and dreams, though this seems not to be the case.",
          TextMapId = "RESOURCE_DESC_3000001"
        },
        RESOURCE_DESC_3000002 = {
          ContentEN = "A piece of worn clothing, hiding a palm-sized diary within its thin lining. The name \"Alice\" is legible on the cover, but most entries are lost to stains, with only recent scribbles faintly recognisable.",
          TextMapId = "RESOURCE_DESC_3000002"
        },
        RESOURCE_DESC_3000003 = {
          ContentEN = "A worn adventure novel depicting the protagonist and his lean horse conquering a castle to find treasure.",
          TextMapId = "RESOURCE_DESC_3000003"
        },
        RESOURCE_DESC_3000004 = {
          ContentEN = "A wire sculpture of Berenica in profile, skillfully capturing her defining features.",
          TextMapId = "RESOURCE_DESC_3000004"
        },
        RESOURCE_DESC_3000005 = {
          ContentEN = "A standard-issue medical kit used by the Legion. It contains the essentials for treating minor battlefield injuries, but offers little help for more severe trauma.",
          TextMapId = "RESOURCE_DESC_3000005"
        },
        RESOURCE_DESC_3000006 = {
          ContentEN = "A cherished keepsake Avar always carries, showing him with his daughter Daphne as a child. Though yellowed with age, their bright smiles remain unmistakable.",
          TextMapId = "RESOURCE_DESC_3000006"
        },
        RESOURCE_DESC_3000007 = {
          ContentEN = "Once a cherished keepsake Avar carried with him, featuring a blissful moment of him with his daughter Daphne as a child. Now, their bright smiles are smeared by dark, dried bloodstains.",
          TextMapId = "RESOURCE_DESC_3000007"
        },
        RESOURCE_DESC_3000008 = {
          ContentEN = "A flower given to you by Psyche, with the warmth of her touch still lingering on the stem.",
          TextMapId = "RESOURCE_DESC_3000008"
        },
        RESOURCE_DESC_3000009 = {
          ContentEN = "A seemingly simple prescription that conceals a dangerous secret — seditious text hidden on the back. If ever discovered by Imperial eyes, it could spell disaster.",
          TextMapId = "RESOURCE_DESC_3000009"
        },
        RESOURCE_DESC_3000010 = {
          ContentEN = "An abstract portrait gifted to you by Faye, who insists it's your likeness. The interplay of red and white might vaguely suggest a human form, gender indistinguishable, but if Faye sees you in it, then so be it. Perhaps the aesthetic sensibilities of Inner City denizens are an acquired taste.",
          TextMapId = "RESOURCE_DESC_3000010"
        },
        RESOURCE_DESC_3000011 = {
          ContentEN = "An intricately crafted key, oddly familiar yet unplaceable. Its origin remains elusive, but perhaps one day, at the right moment, it will unlock a long-buried secret.",
          TextMapId = "RESOURCE_DESC_3000011"
        },
        RESOURCE_DESC_3000018 = {
          ContentEN = "White pigment, suitable for oil painting.",
          TextMapId = "RESOURCE_DESC_3000018"
        },
        RESOURCE_DESC_3000019 = {
          ContentEN = "Painkiller stored in a safe.",
          TextMapId = "RESOURCE_DESC_3000019"
        },
        RESOURCE_DESC_3000020 = {
          ContentEN = "A stack crew work pass.",
          TextMapId = "RESOURCE_DESC_3000020"
        },
        RESOURCE_DESC_3000021 = {
          ContentEN = "A pile of cheques, each worth five gold coins.",
          TextMapId = "RESOURCE_DESC_3000021"
        },
        RESOURCE_DESC_3000022 = {
          ContentEN = "Surgical haemostat.",
          TextMapId = "RESOURCE_DESC_3000022"
        },
        RESOURCE_DESC_3000023 = {
          ContentEN = "A squat metal flask.",
          TextMapId = "RESOURCE_DESC_3000023"
        },
        RESOURCE_DESC_3000024 = {
          ContentEN = "Smuggled cotton coats with half the cotton already hollowed out.",
          TextMapId = "RESOURCE_DESC_3000024"
        },
        RESOURCE_DESC_3000025 = {
          ContentEN = "A potion commonly used by alchemists, with a pungent, acidic smell.",
          TextMapId = "RESOURCE_DESC_3000025"
        },
        RESOURCE_DESC_30001 = {
          ContentEN = "Gelatinous substance for crafting Track-Shift Modules. With a pure, water-soluble composition that deactivates at high temperatures, it demands exacting storage conditions. Its utility makes it worth carrying though.",
          TextMapId = "RESOURCE_DESC_30001"
        },
        RESOURCE_DESC_30002 = {
          ContentEN = "Material for crafting Weapon Track-Shift Modules. These specially treated magnets respond to diverse metal components at unique frequencies, allowing seasoned users to discern the most subtle irregularities in weaponry through their vibrations.",
          TextMapId = "RESOURCE_DESC_30002"
        },
        RESOURCE_DESC_3001 = {
          ContentEN = [[
Used for re-rolling following a failed Impression Check.
Human interactions are invariably fraught with difficulties. Face them head-on and try again.]],
          TextMapId = "RESOURCE_DESC_3001"
        },
        RESOURCE_DESC_3002 = {
          ContentEN = [[
A treat favoured by Geniemons, can be used to feed them.
True to its name, if these creatures could speak, they would surely exclaim, "Yum!"]],
          TextMapId = "RESOURCE_DESC_3002"
        },
        RESOURCE_DESC_3003 = {
          ContentEN = [[
A treat most-favoured by Geniemons, can be used to feed them.
True to its name, if these creatures could speak, they would surely exclaim, "Yum-yum!"]],
          TextMapId = "RESOURCE_DESC_3003"
        },
        RESOURCE_DESC_3004 = {
          ContentEN = [[
A nourishing treat favoured by Geniemons. Grants 100 EXP when used to upgrade these helpful companions.
True to its name, if Geniemons could talk, they'd definitely exclaim: "Yum!"]],
          TextMapId = "RESOURCE_DESC_3004"
        },
        RESOURCE_DESC_3005 = {
          ContentEN = [[
A nourishing treat favoured by Geniemons. Grants 300 EXP when used to upgrade these helpful companions.
True to its name, if Geniemons could talk, they'd definitely exclaim: "Yum-yum!"]],
          TextMapId = "RESOURCE_DESC_3005"
        },
        RESOURCE_DESC_3006 = {
          ContentEN = [[
A nourishing treat favoured by Geniemons. Grants 1000 EXP when used to upgrade these helpful companions.
True to its name, if Geniemons could talk, they'd definitely exclaim: "Yum-yum-yum!"]],
          TextMapId = "RESOURCE_DESC_3006"
        },
        RESOURCE_DESC_3007 = {
          ContentEN = "A creamy beverage favoured by Geniemons — ideal ascending them.\nTrue to its name, if Geniemons could talk, they'd definitely exclaim: \"Yum-yum!\"",
          TextMapId = "RESOURCE_DESC_3007"
        },
        RESOURCE_DESC_3008 = {
          ContentEN = [[
A beloved snack among Geniemons. Feed one this treat, and it'll twist into an Eldritch Geniemon.
So tasty, it's literally transformative.]],
          TextMapId = "RESOURCE_DESC_3008"
        },
        RESOURCE_DESC_301 = {
          ContentEN = "This item lets you ride mounts and fly within Icelake.",
          TextMapId = "RESOURCE_DESC_301"
        },
        RESOURCE_DESC_3010 = {
          ContentEN = "Boosts a character's Benefit Impression in Icelake",
          TextMapId = "RESOURCE_DESC_3010"
        },
        RESOURCE_DESC_30101 = {
          ContentEN = "A dye made by blending various raw materials, capable of producing hues akin to those of the waters of Lamenting Lake.",
          TextMapId = "RESOURCE_DESC_30101"
        },
        RESOURCE_DESC_30102 = {
          ContentEN = "A dye made by blending various raw materials, capable of producing hues akin to those of sea salt.",
          TextMapId = "RESOURCE_DESC_30102"
        },
        RESOURCE_DESC_30103 = {
          ContentEN = "A dye made by blending various raw materials, capable of producing hues akin to those of timber.",
