          TextMapId = "RESOURCE_DESC_30108"
        },
        RESOURCE_DESC_30109 = {
          ContentEN = "A dye made by blending various raw materials, capable of producing hues akin to those of a thunderstorm on the horizon.",
          TextMapId = "RESOURCE_DESC_30109"
        },
        RESOURCE_DESC_3011 = {
          ContentEN = "Boosts a character's Morality Impression in Icelake",
          TextMapId = "RESOURCE_DESC_3011"
        },
        RESOURCE_DESC_30110 = {
          ContentEN = "A dye made by blending various raw materials, capable of producing hues as mesmerizing as the galaxy.",
          TextMapId = "RESOURCE_DESC_30110"
        },
        RESOURCE_DESC_30111 = {
          ContentEN = "A dye made by blending various raw materials, capable of producing hues reminiscent of wheat fields.",
          TextMapId = "RESOURCE_DESC_30111"
        },
        RESOURCE_DESC_30112 = {
          ContentEN = "A blended dye crafted from myriad ingredients, capable of producing the colour of any Standard Dye.",
