        RESOURCE_DESC_41046 = {
          ContentEN = "Doooo you wanna spin?",
          TextMapId = "RESOURCE_DESC_41046"
        },
        RESOURCE_DESC_41047 = {
          ContentEN = "Sharing is a joy in its own right — one that feels like a luxury.",
          TextMapId = "RESOURCE_DESC_41047"
        },
        RESOURCE_DESC_41048 = {
          ContentEN = "Please, have mercy...! ○|￣|_",
          TextMapId = "RESOURCE_DESC_41048"
        },
        RESOURCE_DESC_41049 = {
          ContentEN = "Party time!",
          TextMapId = "RESOURCE_DESC_41049"
        },
        RESOURCE_DESC_41050 = {
          ContentEN = "For you, the DNA keeps spinning.",
          TextMapId = "RESOURCE_DESC_41050"
        },
        RESOURCE_DESC_41051 = {
          ContentEN = "With a single thought, all heights fall beneath you.",
          TextMapId = "RESOURCE_DESC_41051"
        },
        RESOURCE_DESC_41052 = {
          ContentEN = "An everyday gesture — take a moment to rest.",
          TextMapId = "RESOURCE_DESC_41052"
        },
