        RESOURCE_DESC_41063 = {
          ContentEN = "Prayer earns no absolution. Only destruction offers redemption.",
          TextMapId = "RESOURCE_DESC_41063"
        },
        RESOURCE_DESC_42001 = {
          ContentEN = "Found within the Labyrinth of Yanyin, this finely crafted square construct was made using techniques long lost to the Jishu Sect. Its energy core emits a beam of light capable of activating other Jishu constructs.",
          TextMapId = "RESOURCE_DESC_42001"
        },
        RESOURCE_DESC_42002 = {
          ContentEN = "An intricately designed square construct built using techniques long lost to the Jishu Sect. Its power core generates a powerful suction capable of clearing the Gritblight caused by the Scourge of Zhuyin.",
          TextMapId = "RESOURCE_DESC_42002"
        },
        RESOURCE_DESC_49989 = {
          ContentEN = [[
Pitch-black wings cleave the night, bearing a lone figure towards a far shore untouched by moonlight.
No Reputation Perk is required to pilot this mount.]],
          TextMapId = "RESOURCE_DESC_49989"
        },
        RESOURCE_DESC_49990 = {
          ContentEN = [[
Night draws its veil across heaven and earth. Hoarse whistles echo beneath it.
No Reputation Perk is required to pilot this mount.]],
          TextMapId = "RESOURCE_DESC_49990"
        },
        RESOURCE_DESC_49991 = {
          ContentEN = "I heard cries of loyalty, and saw the stars set ablaze.",
          TextMapId = "RESOURCE_DESC_49991"
        },
        RESOURCE_DESC_49995 = {
          ContentEN = "I ride the wind upon my sword.",
          TextMapId = "RESOURCE_DESC_49995"
        },
        RESOURCE_DESC_49996 = {
          ContentEN = "Oink oink? Oink oink. Oink oink!",
          TextMapId = "RESOURCE_DESC_49996"
        },
        RESOURCE_DESC_49997 = {
          ContentEN = "All those moments will be lost in time, like tears in rain.",
          TextMapId = "RESOURCE_DESC_49997"
        },
        RESOURCE_DESC_49998 = {
          ContentEN = "A mechanised aerial craft built by Master Gongshang, modelled after Lord Argent. There's only one in all Huaxu, kept as a prized showpiece in Gongshang's workshop. Thankfully, he only built one. If replicas of Taihao ever filled the skies, the Ministry of Rites would come knocking in outrage. Yet Master Gongshang remains unmoved, set on mass-producing it all the same. Good luck to him.\nFly Speed ＋50%. No Reputation Perk is required to pilot this mount.",
          TextMapId = "RESOURCE_DESC_49998"
        },
        RESOURCE_DESC_49999 = {
          ContentEN = "A mechanical mount developed by Master Gongshang, lifelike enough to pass for a real Sable Bi'an. Ride it through Mistwharf, and you are sure to turn a few heads.",
          TextMapId = "RESOURCE_DESC_49999"
        },
        RESOURCE_DESC_5000000 = {
          ContentEN = "Used to enhance Demon Wedges with high rarity",
          TextMapId = "RESOURCE_DESC_5000000"
        },
        RESOURCE_DESC_5011010 = {
          ContentEN = "A key commercial species across Atlasia, this fish can be found in every sea. It forms vast schools in the open ocean and migrates to coastal shallows with the turning of the seasons, year after year.",
          TextMapId = "RESOURCE_DESC_5011010"
        },
        RESOURCE_DESC_5011020 = {
          ContentEN = "A brilliantly coloured fish found in crystal-clear waters, easily recognised by the vivid spines along its back. Skittish by nature — when fishing, patience serves better than speed.",
          TextMapId = "RESOURCE_DESC_5011020"
        },
        RESOURCE_DESC_5011030 = {
          ContentEN = "A slender marine fish that swims upright, its scales gleaming like liquid silver in motion — true to its name. Unfortunately, it perishes quickly once removed from the water, and due to the high cost of transport, it is seldom seen on inland tables.",
          TextMapId = "RESOURCE_DESC_5011030"
        },
        RESOURCE_DESC_5012010 = {
          ContentEN = "Named for the long barbels near its mouth, this freshwater species dwells in muddy beds thick with waterweed. It only surfaces after sundown to feed and can live for decades — if it avoids the hook.",
          TextMapId = "RESOURCE_DESC_5012010"
        },
        RESOURCE_DESC_5012020 = {
          ContentEN = "Densely covered in pearl-like spots, this fish can grow up to two metres long. The young are gentle by nature and rarely stray far from their parents' tailfins.",
          TextMapId = "RESOURCE_DESC_5012020"
        },
        RESOURCE_DESC_5012030 = {
          ContentEN = "Found throughout freshwater bodies, the Shellgnarl is one of the few ingredients beloved by nearly every community on the continent. Preparation methods vary by region — some even throw grand summer festivals featuring it as the star dish.",
          TextMapId = "RESOURCE_DESC_5012030"
        },
        RESOURCE_DESC_5013010 = {
          ContentEN = "With its sharp fangs and perpetually scowling face, this fish looks far more dangerous than it actually is. The largest one ever recorded measured just 5 centimetres. It doesn't hunt in packs, and its bite is harmless — at most leaving a faint, circular scar.",
          TextMapId = "RESOURCE_DESC_5013010"
        },
        RESOURCE_DESC_5013020 = {
          ContentEN = "A near-motionless fish that spends most of its life lying sideways in the silt. With its mouth perpetually agape, it waits for plankton and small fish to drift in. Once it bites, it chews for hours without so much as a twitch — a habit that gave it its name.",
          TextMapId = "RESOURCE_DESC_5013020"
        },
        RESOURCE_DESC_5013030 = {
          ContentEN = "A bizarre creature that looks like a crab crossed with a spider. It scuttles up walls like the latter and haunts the depths like the former. While there are many ways to catch one, angling remains by far the safest.",
          TextMapId = "RESOURCE_DESC_5013030"
        },
        RESOURCE_DESC_5021010 = {
          ContentEN = "A tiny jellyfish found only in the waters around Purgatorio Island, known for its bioluminescence. Though inedible, its glow lights the waves on moonless nights — bobbing like a star set adrift, guiding fishermen home.",
          TextMapId = "RESOURCE_DESC_5021010"
        },
        RESOURCE_DESC_5021020 = {
          ContentEN = "One of the primary catches for villagers on Purgatorio Island, prized for its tender, flavourful flesh — the result of a life spent in constant motion, ceaselessly chasing the ebb and flow of the tides.",
          TextMapId = "RESOURCE_DESC_5021020"
        },
        RESOURCE_DESC_5021030 = {
          ContentEN = "Native to Purgatorio Island, this species can glide across the water's surface. On clear days, you might spot them leaping into the air like birds — their vibrant wings shimmering in the sun.",
          TextMapId = "RESOURCE_DESC_5021030"
        },
        RESOURCE_DESC_5021040 = {
          ContentEN = "The most beloved aquatic creature on Purgatorio Island, with no recorded counterpart elsewhere. Plainly inedible, these fairy-like beings bring a spark of delight to islanders living far from the outside world, easing the monotony of their isolated days.",
          TextMapId = "RESOURCE_DESC_5021040"
        },
        RESOURCE_DESC_5021050 = {
          ContentEN = "A rare and exceptionally beautiful fish, its fins shimmer like the gleaming boughs of a Heaventree. On Purgatorio Island, it is revered as a gift from the divine — and when caught, it is often returned to the sea in quiet reverence.",
          TextMapId = "RESOURCE_DESC_5021050"
        },
        RESOURCE_DESC_5022010 = {
          ContentEN = "A speciality of the Huaxu Waters, often dubbed the \"bat of the sea\" by locals. It typically dwells near the seabed, surfacing only to feed. Its back is studded with pearlescent bumps — a texture prized for wrapping the hilts of fine weapons.",
          TextMapId = "RESOURCE_DESC_5022010"
        },
        RESOURCE_DESC_5022020 = {
          ContentEN = "A crab that makes its home inside abandoned clockwork parts. Though biologically little different from ordinary hermit crabs, the collapse of the Jishu Sect left behind scattered mechanical relics — now repurposed by these creatures as shelters across the seas.",
          TextMapId = "RESOURCE_DESC_5022020"
        },
        RESOURCE_DESC_5022030 = {
          ContentEN = "A fiercely aggressive species prized for its tender, flavourful meat — a familiar sight on dining tables across Huaxu. Despite its hideous appearance, the bioluminescent lure atop its head lends it a strangely delicate beauty.",
          TextMapId = "RESOURCE_DESC_5022030"
        },
        RESOURCE_DESC_5022040 = {
          ContentEN = "A mysterious aquatic lifeform recorded in ancient texts, said to spit venomous sand at the shadows of passers-by, afflicting them with strange illnesses.",
          TextMapId = "RESOURCE_DESC_5022040"
        },
        RESOURCE_DESC_5022050 = {
          ContentEN = "Named after the once-popular twin-bun hairstyle of Huaxu, this swift and ferocious predator is an opportunistic feeder, known for tearing through nets with ease — a true challenge for even seasoned fishers.",
          TextMapId = "RESOURCE_DESC_5022050"
        },
        RESOURCE_DESC_5023010 = {
          ContentEN = "A fish bearing a striking resemblance to Phoxene, with an uncanny texture that feels almost indistinguishable from the real thing. No two look quite the same — but they all share one unfortunate trait: flesh as tough as stone. It's rarely eaten except in times of true desperation.",
          TextMapId = "RESOURCE_DESC_5023010"
        },
        RESOURCE_DESC_5023020 = {
          ContentEN = "A brilliantly coloured fish that glides through the water like a wisp of silk. Its translucent fins ripple around it like trailing veils, and every motion flows with effortless poise — graceful as the fabled Lady of the Lake, wandering her liquid realm in quiet command.",
          TextMapId = "RESOURCE_DESC_5023020"
        },
        RESOURCE_DESC_5023030 = {
          ContentEN = "One of the staple food fish in Icelake, easily recognised by the single horn atop its head. Large, tender, and low in bones, it suits sashimi, grilling, frying, or baking — a truly versatile catch for any dish.",
          TextMapId = "RESOURCE_DESC_5023030"
        },
        RESOURCE_DESC_5023040 = {
          ContentEN = "A rare, cold-hardy fish found only in Icelake. With a tough, ridged carapace and no dorsal or ventral fins, it is easy to grip, much like the wooden clubs once used to pound laundry clean.",
          TextMapId = "RESOURCE_DESC_5023040"
        },
        RESOURCE_DESC_5023050 = {
          ContentEN = "A species unique to the waters of Icelake. Jagged, ice-like spines line its back, glowing faintly in the dark. On clear days, a streak of pale light beneath the surface often signals the silent passing of a Gleamspine.",
          TextMapId = "RESOURCE_DESC_5023050"
        },
        RESOURCE_DESC_5024010 = {
          ContentEN = "A vibrant, frilled fish prized for its looks. The fuller the fins, the brighter the colours, the higher the price. Fiercely territorial toward its own kind, each must be housed alone.",
          TextMapId = "RESOURCE_DESC_5024010"
        },
        RESOURCE_DESC_5024020 = {
          ContentEN = "A small squid named after Shouxing, the god of longevity in Huaxu myth. Though diminutive, its tentacles allow it to spring through the air with startling force. In Huaxu, it is a cherished symbol of long life — on elders' birthdays, desserts shaped in its likeness are a must-have at the celebration.",
          TextMapId = "RESOURCE_DESC_5024020"
        },
        RESOURCE_DESC_5024030 = {
          ContentEN = "Covered in fine barbs, this fish puffs into a spiny sphere when threatened, inflating itself with air or water. Despite being dangerously toxic and notoriously difficult to prepare, it remains a sought-after delicacy in Huaxu.",
          TextMapId = "RESOURCE_DESC_5024030"
        },
        RESOURCE_DESC_5024040 = {
          ContentEN = "A brightly coloured fish native to Huaxu, known for its pouch-like belly and bottom-dwelling habits. Though modest in size, it's prized for its tender, boneless meat — a favourite at many local restaurants.",
          TextMapId = "RESOURCE_DESC_5024040"
        },
        RESOURCE_DESC_5024050 = {
          ContentEN = "A rare Huaxu fish that can grow up to four metres long. With a pointed snout and four pairs of ventral fins, it bears symmetrical markings and shimmering scales reminiscent of the Argent Dragon.\nThough not protected under the Nine Chapters of Dafeng, the Waterwyrm is rarely hunted. Its likeness to the Argent Dragon stirs reverence across Huaxu — and few would risk sacrilege by putting it on a dinner table.",
          TextMapId = "RESOURCE_DESC_5024050"
        },
        RESOURCE_DESC_5025010 = {
          ContentEN = "A whiskered, long-tailed fish that favours cracks and corners, and is hardy enough to thrive even in stagnant or polluted waters. Unlike real rats, it doesn't gnaw on clothing or steal food — which is why children in the slums often keep them as low-maintenance pets.",
          TextMapId = "RESOURCE_DESC_5025010"
        },
        RESOURCE_DESC_5025020 = {
          ContentEN = "A smooth-skinned, scaleless creature with a tubular mouth lined with rows of sharp teeth — no upper or lower jaw. It burrows in sewer sludge and latches onto anything that gets too close... and once it does, it never lets go. Among sewer workers, it's considered the nastiest creature you can run into down there.",
          TextMapId = "RESOURCE_DESC_5025020"
        },
        RESOURCE_DESC_5025030 = {
          ContentEN = "A fully transparent fish with fine, delicate bones. Nearly impossible to spot with the naked eye, its flesh is gelatinous and inedible — though researchers believe it may be refined into a rare, highly specialised gel.",
          TextMapId = "RESOURCE_DESC_5025030"
        },
        RESOURCE_DESC_5025040 = {
          ContentEN = "A bizarre, limbed fish that lurks in the mud and occasionally emits blood-curdling cries. Its resemblance to the Filthoid is uncanny — though whether this is mere coincidence or something more remains unknown.",
          TextMapId = "RESOURCE_DESC_5025040"
        },
        RESOURCE_DESC_5025050 = {
          ContentEN = "A brownish fish with six twitching fins along its sides. Its jerky movements ripple through the water — unsettling to watch, but alarmingly fast. Two antenna-like feelers jut from its head, often the first sign it's lurking nearby. Ruthless and persistent, it's even been known to pursue prey onto dry land.",
          TextMapId = "RESOURCE_DESC_5025050"
        },
        RESOURCE_DESC_5026010 = {
          ContentEN = "A fish species native to Huaxu, notable for its unusual appearance: a rounded stonemill-like shape, with both eyes sitting on one side of the body. Early records claim it must merge with a perfect mirror-twin in order to swim — a tale local fishermen dismiss outright as fiction.",
          TextMapId = "RESOURCE_DESC_5026010"
        },
        RESOURCE_DESC_5026020 = {
          ContentEN = "A pretty little sea crab named for the way its paddling legs fan out like orchid petals. It is common in the waters of Huaxu and delicious simply blanched. Known to nip many a curious finger — both lovable and infuriating, and all the more memorable for it.",
          TextMapId = "RESOURCE_DESC_5026020"
        },
        RESOURCE_DESC_5026030 = {
          ContentEN = "A perfectly standard starfish.\n Decent enough as decoration, though nowhere near as pretty as a pearl.\n Passable as food, but there's not much to it, so few people bother.\n As a catch, it's better than nothing, but nothing to boast about.\n In short, it's a starfish — nothing more to say, really.",
          TextMapId = "RESOURCE_DESC_5026030"
        },
        RESOURCE_DESC_5026040 = {
          ContentEN = "A vivid scarlet creature from the sea, shrimp-like in form but distinct from true shrimp, and about the length of a firecracker. Feisty by nature, it flares up at the smallest provocation, which is how it got its name. It is usually deep-fried, then stir-fried with a spiced salt and pepper mix for a fragrant, mouth-watering finish. Best enjoyed in the first month of the lunar year, shared with family as firecrackers crackle outside — spot on!",
          TextMapId = "RESOURCE_DESC_5026040"
        },
        RESOURCE_DESC_5026050 = {
          ContentEN = "A fierce, blue-green giant of a fish, named for how it evokes the ancient Huaxu tales of the Kun — the legendary great fish said to devour all things. Among Huaxu's fishers, having one's thigh pierced by a fast-charging Azurewave Kun is considered one of the nastiest curses you can throw at someone.",
          TextMapId = "RESOURCE_DESC_5026050"
        },
        RESOURCE_DESC_5027010 = {
          ContentEN = "A river fish famed for its delicate flavour, shaped much like a small blade. Legend tells of an assassin who once hid a dagger among a dish of plain-boiled edgefin, drawing it only when his unsuspecting foe was lost in the delight of the coming meal. The tale, at least, proves two things: edgefin really do resemble blades — and they taste exceptionally good.",
          TextMapId = "RESOURCE_DESC_5027010"
        },
        RESOURCE_DESC_5027020 = {
          ContentEN = "A fierce-tempered river fish that favours live prey, so aggressive it can be landed even on an unbaited hook. At its plumpest when peach blossoms fill the spring air, it is traditionally scored and steamed, then topped with light soy sauce and hot oil — the most elaborate way Huaxu households receive honoured guests.",
          TextMapId = "RESOURCE_DESC_5027020"
        },
        RESOURCE_DESC_5027030 = {
          ContentEN = "A long-prized food fish, though scarce in supply. Its most renowned preparation is a rich fish stew. With the first autumn breeze, Starweavers far from home inevitably long for its taste.",
          TextMapId = "RESOURCE_DESC_5027030"
        },
        RESOURCE_DESC_5027040 = {
          ContentEN = "An ornamental species with a saddle-shaped dorsal fin. Juveniles are pale grey, while adults develop a range of vivid colours. Unfussy about water conditions and easy to keep.",
          TextMapId = "RESOURCE_DESC_5027040"
        },
        RESOURCE_DESC_5027050 = {
          ContentEN = "The largest freshwater fish in Huaxu, fully golden and exceedingly rare. Long taken as a symbol of emperors — though with no emperors left in Huaxu, the word now brings this giant fish to mind far sooner than any ruler of ages past.",
          TextMapId = "RESOURCE_DESC_5027050"
        },
        RESOURCE_DESC_5028010 = {
          ContentEN = "A slender, brightly coloured bottom-dweller that excels at ambush. Its large eyes glow softly at night, likely to lure unwary small fish close. To a fisherman peering into the dark water, they can look like pairs of blue-glowing eyes lurking on the riverbed.",
          TextMapId = "RESOURCE_DESC_5028010"
        },
        RESOURCE_DESC_5028020 = {
          ContentEN = "A small fish often seen in pairs, nimble enough to leap and able to crawl briefly on land. It lives across coastal shallows and riverbanks, digging small dens and keeping its partner wet by splashing water over it. This behaviour made it a symbol of mutual devotion in old texts, and in recent years its quirky appearance has made it rather popular.",
          TextMapId = "RESOURCE_DESC_5028020"
        },
        RESOURCE_DESC_5028030 = {
          ContentEN = "A fish that dwells in lightless environments. Its body is milky, pale, and translucent with a pearly sheen, and its eyes have completely degenerated. As rare as hen's teeth.",
          TextMapId = "RESOURCE_DESC_5028030"
        },
        RESOURCE_DESC_5028040 = {
          ContentEN = "A species that inhabits dark, damp places, with extremely rough skin and a back that changes colour with the seasons. It is long valued as a traditional medicinal ingredient  — though many find its appearance decidedly unattractive.",
          TextMapId = "RESOURCE_DESC_5028040"
        },
        RESOURCE_DESC_5028050 = {
          ContentEN = "A denizen of the dim and dank, with large pectoral fins tipped with spines. Its bright coloration and swimming motion give it a moth-like appearance. Highly poisonous, its fins were once fashioned into weapons during the ancient era.",
          TextMapId = "RESOURCE_DESC_5028050"
        },
        RESOURCE_DESC_5029010 = {
          ContentEN = "A species found in the brackish waters where Huaxu's rivers meet the sea. Its flanks are mottled with pale, star-like markings that shimmer faintly in low light. When hooked after dusk, its scales catch the light with a star-like sheen, as though a fragment of a constellation has been lifted from the water.",
          TextMapId = "RESOURCE_DESC_5029010"
        },
        RESOURCE_DESC_5029020 = {
          ContentEN = "A small marine catfish that can pass for an eel at first glance, until the barbels at its mouth give it away. Aggressive and quick to pick fights despite its size, it's also highly social, gathering in schools that spend much of the day jostling and jabbing at one another with their hardened, venomous barbs.",
          TextMapId = "RESOURCE_DESC_5029020"
        },
        RESOURCE_DESC_5029030 = {
          ContentEN = "A seahorse variety whose body resembles a raw gemstone. It is prized for display and medicinal use rather than for consumption.",
          TextMapId = "RESOURCE_DESC_5029030"
        },
        RESOURCE_DESC_5029040 = {
          ContentEN = "A slender marine fish found along Huaxu's coast. Soft-fleshed and nutrient-rich, it is commonly used as bait or as feed for larger fish. Its melancholy gaze makes it look as if it already knows how its story ends.",
          TextMapId = "RESOURCE_DESC_5029040"
        },
        RESOURCE_DESC_5029050 = {
          ContentEN = "Found along Huaxu's coast, most often in deeper waters. Despite living in the depths, the Dawnscale gleams with a bright, uniform golden sheen, as though a sliver of dawn has been caught beneath the sea. Smaller specimens fetch little, but prices climb steeply with size, earning it the local nickname \"gold in the water\".",
          TextMapId = "RESOURCE_DESC_5029050"
        },
        RESOURCE_DESC_5030010 = {
          ContentEN = "One of the best-known crabs from the waters of Haojing, prized for its size and rich flavour. It's also high in protein and minerals. Best enjoyed when the autumn winds set in: steamed, then dipped in vinegar with thin shreds of ginger. A seasonal favourite across Huaxu.",
          TextMapId = "RESOURCE_DESC_5030010"
        },
        RESOURCE_DESC_5030020 = {
          ContentEN = "A small wild freshwater fish found in abundance across Huaxu, remarkably hardy and highly adaptable. Its flesh is delicate but riddled with fine bones, making it better suited to soups and broths than to frying or grilling. When it surfaces to gulp air, it often lets out a frog-like croak, hence its name.",
          TextMapId = "RESOURCE_DESC_5030020"
        },
        RESOURCE_DESC_5030030 = {
          ContentEN = "A curious fish that bears a lotus-leaf-like growth atop its head, making it exceptionally hard to spot among floating leaves. Even veteran fishermen struggle to tell, at a glance, which leaves are real and which are Lotusleaf in disguise.",
          TextMapId = "RESOURCE_DESC_5030030"
        },
        RESOURCE_DESC_5030040 = {
          ContentEN = "Native to Huaxu, its scales gleam like polished bronze. In ancient times, its scales were once used as currency. Some members of the Jishu Sect see it as an auspicious omen and make offerings in its honour.",
          TextMapId = "RESOURCE_DESC_5030040"
        },
        RESOURCE_DESC_5030050 = {
          ContentEN = "One of Huaxu's prized freshwater species, distinguished by its vivid red crest and aggressive temperament. When hunting, it doesn't strike immediately. Instead, it circles its prey until it becomes disoriented, then delivers a single decisive bite. In bearing, it resembles a swaggering general wearing a crimson helm.",
          TextMapId = "RESOURCE_DESC_5030050"
        },
        RESOURCE_DESC_5031010 = {
          ContentEN = "A rare scavenger fish whose diet leaves it with a lingering stench that no amount of cleaning can fully remove. In Huaxu, it's widely regarded as one of the worst-tasting fish ever to reach the table.",
          TextMapId = "RESOURCE_DESC_5031010"
        },
        RESOURCE_DESC_5031020 = {
          ContentEN = "A clam found in turbid waters, its shell often caked in silt and grime. Yet beneath the muck lies tender pink flesh that becomes unexpectedly sweet and aromatic when cooked — hence the name.",
          TextMapId = "RESOURCE_DESC_5031020"
        },
        RESOURCE_DESC_5031030 = {
          ContentEN = "A wormlike invertebrate resembling an earthworm, typically found in dark, stagnant waters. It is unusually plump and almost the colour of raw flesh. It is valued for its medicinal properties and prized by fishermen as bait.",
          TextMapId = "RESOURCE_DESC_5031030"
        },
        RESOURCE_DESC_5031040 = {
          ContentEN = "A small fish inhabiting lightless waters, notable for its disproportionately large, luminous eyes. Even in turbid currents heavy with silt and sediment, their glow cuts through the murk.",
          TextMapId = "RESOURCE_DESC_5031040"
        },
        RESOURCE_DESC_5031050 = {
          ContentEN = "A freshwater predator native to Huaxu's turbid waters. It buries itself in the silt and lies in wait for prey to draw near, then bursts from the mud and strikes in a single explosive motion. In parts of Huaxu, it ranks among the region's apex predators.",
          TextMapId = "RESOURCE_DESC_5031050"
        },
        RESOURCE_DESC_5032010 = {
          ContentEN = "A familiar food fish found all across Atlasia. Hardy and highly adaptable, it is often jokingly called \"the weed of the waterways.\"",
          TextMapId = "RESOURCE_DESC_5032010"
        },
        RESOURCE_DESC_5032020 = {
          ContentEN = "A freshwater fish found near Bloomfield Station. Whether by instinct or from years of mimicking passing trains, Tootfish can produce a clear \"toot-toot\" through their long, tube-like mouths. When travellers pass through their territory, the lake answers in rippling waves of \"toot-toot.\"",
          TextMapId = "RESOURCE_DESC_5032020"
        },
        RESOURCE_DESC_5032030 = {
          ContentEN = "A freshwater fish commonly found in Cocytus. It keeps its head tilted proudly skyward at all times — even after being cooked and served at the dinner table, as though something among the stars were calling to it.",
          TextMapId = "RESOURCE_DESC_5032030"
        },
        RESOURCE_DESC_5032040 = {
          ContentEN = "A pufferfish subspecies found in Cocytus. Much less aggressive than its relatives, it simply inflates and rolls away at high speed when threatened.",
          TextMapId = "RESOURCE_DESC_5032040"
        },
        RESOURCE_DESC_5032050 = {
          ContentEN = "A fast-growing migratory fish of enormous size, named for its metallic sheen. In sharp contrast to its imposing appearance, Ironhead Salmon has exceptionally soft, tender flesh that melts in the mouth like butter. Rich, juicy, and deeply flavourful, it is a common sight at banquets held by Icelake's elite.",
          TextMapId = "RESOURCE_DESC_5032050"
        },
        RESOURCE_DESC_5110100 = {
          ContentEN = "A fishing rod crafted by Lunosmith, featuring a surface monitor styled after Cinder, her trusty little assistant. When a fish bites, Cinder lights up to signal it — though according to customer feedback, some folks got so mesmerised watching it glow, they ended up going home with an empty bucket.",
          TextMapId = "RESOURCE_DESC_5110100"
        },
        RESOURCE_DESC_5110200 = {
          ContentEN = "A fishing rod crafted by Lunosmith, featuring a surface monitor styled after Cinder, her trusty little assistant. When a fish bites, Cinder lights up to signal it — though according to customer feedback, some folks got so mesmerised watching it glow, they ended up going home with an empty bucket.",
          TextMapId = "RESOURCE_DESC_5110200"
        },
        RESOURCE_DESC_5110300 = {
          ContentEN = "A fishing rod crafted by Lunosmith, featuring a surface monitor styled after Cinder, her trusty little assistant. When a fish bites, Cinder lights up to signal it — though according to customer feedback, some folks got so mesmerised watching it glow, they ended up going home with an empty bucket.",
          TextMapId = "RESOURCE_DESC_5110300"
        },
        RESOURCE_DESC_5110400 = {
          ContentEN = "A fishing rod crafted by Lunosmith, featuring a surface monitor styled after Cinder, her trusty little assistant. When a fish bites, Cinder lights up to signal it — though according to customer feedback, some folks got so mesmerised watching it glow, they ended up going home with an empty bucket.",
          TextMapId = "RESOURCE_DESC_5110400"
        },
        RESOURCE_DESC_5110500 = {
          ContentEN = "A fishing rod crafted by Lunosmith, featuring a surface monitor styled after Cinder, her trusty little assistant. When a fish bites, Cinder lights up to signal it — though according to customer feedback, some folks got so mesmerised watching it glow, they ended up going home with an empty bucket.",
          TextMapId = "RESOURCE_DESC_5110500"
        },
        RESOURCE_DESC_5110601 = {
          ContentEN = "Huaxu legends tell of a master angler whose true name has long been forgotten. People simply call him Old Angler Jiang. They say he could cast an empty line and still land a fish, every time.\nEveryone knows tricks like that are wishful thinking — but commissioning a Jishu artisan to recreate his rod is easy enough.",
          TextMapId = "RESOURCE_DESC_5110601"
        },
        RESOURCE_DESC_5110602 = {
          ContentEN = "Huaxu legends tell of a master angler whose true name has long been forgotten. People simply call him Old Angler Jiang. They say he could cast an empty line and still land a fish, every time.\nEveryone knows tricks like that are wishful thinking — but commissioning a Jishu artisan to recreate his rod is easy enough.",
          TextMapId = "RESOURCE_DESC_5110602"
        },
        RESOURCE_DESC_5210100 = {
          ContentEN = "A standard lure meant to attract a fish's attention — whether it actually helps you catch anything... is another matter entirely.",
          TextMapId = "RESOURCE_DESC_5210100"
        },
        RESOURCE_DESC_5210200 = {
          ContentEN = "A special lure that shortens bite time. Maybe it's the way it wriggles — irresistible to most underwater dwellers.",
          TextMapId = "RESOURCE_DESC_5210200"
        },
        RESOURCE_DESC_5210300 = {
          ContentEN = "A formulated bait that boosts your odds of luring fish variants. To a creature with eccentric tastes, maybe a glinting hunk of scrap can pass for fine cuisine.",
          TextMapId = "RESOURCE_DESC_5210300"
        },
        RESOURCE_DESC_5210400 = {
          ContentEN = "A deceptively plain-looking lure, crafted from top-grade ingredients. Even the pickiest of fish keep pecking until the very last crumb is gone.",
          TextMapId = "RESOURCE_DESC_5210400"
        },
        RESOURCE_DESC_6000001 = {
          ContentEN = "A trade voucher issued by EverSpring, Zhiliu's guild.",
          TextMapId = "RESOURCE_DESC_6000001"
        },
        RESOURCE_DESC_6000002 = {
          ContentEN = [[
Transform!
Can be equipped and used in your Tactical Backpack]],
          TextMapId = "RESOURCE_DESC_6000002"
        },
        RESOURCE_DESC_6000004 = {
          ContentEN = [[
A set of scoring tokens prepared by the Grand Incense Rite for use in the trials. Before Huaxu's prohibition on fighting, competitions were divided into civil and martial categories, each with its own tokens for tallying points. Though martial force was later forbidden throughout the realm, the scoring system endured; only the distinction between Civil and Martial Tokens was set aside.
 
 Now, under the new format, Martial Tokens have been reinstated. A competitor's final score is calculated from the combined total of Civil and Martial Tokens.]],
          TextMapId = "RESOURCE_DESC_6000004"
        },
        RESOURCE_DESC_6000005 = {
          ContentEN = "Since its launch, the Incense Proving has drawn widespread attention across Huaxu, with its star contestants earning particular acclaim. To inspire more young talents amid the changes sweeping Huaxu, the organisers have invited these standout competitors to take part in an even more demanding Invitational, and issued invitations to them accordingly.",
          TextMapId = "RESOURCE_DESC_6000005"
        },
        RESOURCE_DESC_6100001 = {
          ContentEN = "A tool crafted by Master Gongshang to upgrade mechapuppets.",
          TextMapId = "RESOURCE_DESC_6100001"
        },
        RESOURCE_DESC_6100101 = {
          ContentEN = "Mechapuppets crafted by Master Gongshang, inspired by units from various factions.",
          TextMapId = "RESOURCE_DESC_6100101"
        },
        RESOURCE_DESC_6100122 = {
          ContentEN = "Used to increase your rank",
          TextMapId = "RESOURCE_DESC_6100122"
        },
        RESOURCE_DESC_99 = {
          ContentEN = "A crystal harvested from a Heaventree — one of the most widely used minerals across Atlasia.\nIt emits a gentle glow, reminiscent of a full moon's radiance.",
          TextMapId = "RESOURCE_DESC_99"
        },
        RESOURCE_DESC_ATTRITEMRARE = {
          ContentEN = [[
A crystal aglow with shifting colours. Within its facets, one may glimpse the splendour of all Atlasia, suffused with the power of every element. 
Obtained through Abyss Expedition. Can be used as smelting material for Calamity Weapons.]],
          TextMapId = "RESOURCE_DESC_ATTRITEMRARE"
        },
        RESOURCE_DESC_ATTRITEM_Dark = {
          ContentEN = "A crystal infused with Umbro magic. Obtained through Abyss Expedition. Can be used as smelting material for Calamity Weapons.",
          TextMapId = "RESOURCE_DESC_ATTRITEM_Dark"
        },
        RESOURCE_DESC_ATTRITEM_Fire = {
          ContentEN = "A crystal infused with Pyro magic. Obtained through Abyss Expedition. Can be used as smelting material for Calamity Weapons.",
          TextMapId = "RESOURCE_DESC_ATTRITEM_Fire"
        }
      }
    end
  },
