        },
        TextMap_AnswerDetail_100003 = {
          ContentEN = "The stage‑curtain scrap points to the Galea Theatre, and the assailant's eerie operatic humming reinforces the link. The theatre merits a thorough search.",
          TextMapId = "TextMap_AnswerDetail_100003"
        },
        TextMap_AnswerDetail_100004 = {
          ContentEN = "The assailant fled southwest — and the only facility in that direction with significant Phoxichor stores is the local factory. It merits a thorough search.",
          TextMapId = "TextMap_AnswerDetail_100004"
        },
        TextMap_AnswerDetail_100005 = {
          ContentEN = "The assailant's hideout was decorated with stage props, and during the attack, they hummed an operatic tune. These clues suggest they may be an opera enthusiast. The melody itself might hold the key to their identity.",
          TextMapId = "TextMap_AnswerDetail_100005"
        },
        TextMap_AnswerDetail_100101 = {
          ContentEN = "Based on the moon's position at the time of the incident, the attack is estimated to have taken place between 4 and 5 in the morning.",
          TextMapId = "TextMap_AnswerDetail_100101"
        },
        TextMap_AnswerDetail_100201 = {
          ContentEN = "The freshly broken vane probably snapped when the assailant landed on the roof. Together with other clues, it may provide more information.",
          TextMapId = "TextMap_AnswerDetail_100201"
        },
        TextMap_AnswerDetail_100202 = {
          ContentEN = "The vane's base is bent toward the southwest. Together with other clues, it may provide more information.",
          TextMapId = "TextMap_AnswerDetail_100202"
        },
        TextMap_AnswerDetail_100203 = {
          ContentEN = "The break pattern of the vane and its base align perfectly, indicating it was dislodged during the assailant's rooftop escape.\nThe assembled vane points southwest — confirming the direction of flight.",
          TextMapId = "TextMap_AnswerDetail_100203"
        },
        TextMap_AnswerDetail_100301 = {
          ContentEN = "That night, the assailant hummed an operatic tune in a rasping voice. Could they be a singer, or simply a music lover?",
          TextMapId = "TextMap_AnswerDetail_100301"
        }
      }
    end
  },
  {
    MinKey = "TextMap_AnswerDetail_100302",
    MaxKey = "TitleFrame_10004",
    Loader = function()
      return {
        TextMap_AnswerDetail_100302 = {
          ContentEN = "A scrap of velvet stage curtain was found at the crime scene — identical to the kind used at the Galea Theatre. Could this point to the theatre's involvement? More evidence is needed to confirm the link.",
          TextMapId = "TextMap_AnswerDetail_100302"
        },
        TextMap_AnswerDetail_100303 = {
          ContentEN = "The stage‑curtain scrap points to the Galea Theatre, and the assailant's operatic humming reinforces the link. The theatre merits a thorough search.",
          TextMapId = "TextMap_AnswerDetail_100303"
        },
        TextMap_AnswerDetail_100401 = {
          ContentEN = "The assailant fled southwest — an area dense with homes, schools, and a factory. Rhythm's investigation has stalled, as the area is too broad without further leads. More clues are needed to narrow the search.",
          TextMapId = "TextMap_AnswerDetail_100401"
        },
        TextMap_AnswerDetail_100402 = {
          ContentEN = "Phoxichor traces were discovered in the snow near the crime scene. However, no leaks have been reported from nearby facilities. Better consult Rhythm about the details of the case to gather more clues.",
          TextMapId = "TextMap_AnswerDetail_100402"
        },
        TextMap_AnswerDetail_100403 = {
          ContentEN = "You recall a pungent scent clinging to the assailant — clear evidence of heavy Phoxichor contamination. Very few sites in Icelake could account for such levels. Cross-reference with other clues to narrow it down.",
          TextMapId = "TextMap_AnswerDetail_100403"
        },
        TextMap_AnswerDetail_100404 = {
          ContentEN = "The assailant fled southwest — and the only facility in that direction with significant Phoxichor stores is the local factory. Could it be their hideout? It merits a thorough search.",
          TextMapId = "TextMap_AnswerDetail_100404"
        },
        TextMap_AnswerDetail_100501 = {
          ContentEN = "In the sewers, you found velvet curtains and mannequins posed like actors mid-performance. Whoever staged this scene possibly sees themselves as part of a performance. Cross-reference with other clues — it may reveal who they truly are.",
          TextMapId = "TextMap_AnswerDetail_100501"
        },
        TextMap_AnswerDetail_100502 = {
          ContentEN = "That night, the assailant hummed an operatic tune in a rasping voice. Could they be a singer, or simply a music lover?",
          TextMapId = "TextMap_AnswerDetail_100502"
        },
        TextMap_AnswerDetail_100503 = {
          ContentEN = "The assailant's hideout was decorated with stage props, and during the attack, they hummed an operatic tune. These clues suggest they may be an opera enthusiast. The melody itself might hold the key to their identity.",
          TextMapId = "TextMap_AnswerDetail_100503"
        },
        TextMap_AnswerDetail_200101 = {
          ContentEN = "Mr Buck only drinks juice and milk at The Asphodel. He has no tolerance for alcohol — just one sip is enough to knock him straight out.",
          TextMapId = "TextMap_AnswerDetail_200101"
        },
        TextMap_AnswerDetail_200102 = {
          ContentEN = "Someone secretly laced Mr Buck's milk with alcohol — clearly intending to knock him out. A sticky, child-sized handprint remains visible on the jug.",
          TextMapId = "TextMap_AnswerDetail_200102"
        },
        TextMap_AnswerDetail_200103 = {
          ContentEN = "A trail of small footprints leads from the street to Mr Buck's windowsill — clear signs that a child broke in and did something inside.",
          TextMapId = "TextMap_AnswerDetail_200103"
        },
        TextMap_AnswerDetail_200104 = {
          ContentEN = "A few pieces of popcorn lie scattered near the footprints — likely stuck to the intruder and shaken loose as they climbed in through the window.",
          TextMapId = "TextMap_AnswerDetail_200104"
        },
        TextMap_AnswerDetail_200105 = {
          ContentEN = "A shivering Charon boy hawking beer, popcorn, opera tickets, and posters near the Galea Theatre's ticket booth.",
          TextMapId = "TextMap_AnswerDetail_200105"
        },
        TextMap_AnswerDetail_200106 = {
          ContentEN = "One particular child, knowing Buck couldn't handle alcohol, slipped into his home and laced his milk — just enough to knock him out. That's why Buck has been falling asleep unusually early.",
          TextMapId = "TextMap_AnswerDetail_200106"
        },
        TextMap_AnswerDetail_200107 = {
          ContentEN = "A drunk man slumped next to the bin, reeking of alcohol. He doesn't match the profile of a child, nor does he seem the type to give his drink away.",
          TextMapId = "TextMap_AnswerDetail_200107"
        },
        TextMap_AnswerDetail_200108 = {
          ContentEN = [[
A little girl who keeps pestering her strict father for popcorn.
While she fits the profile of a child, it's clear the popcorn beneath Buck's window didn't come from her.]],
          TextMapId = "TextMap_AnswerDetail_200108"
        },
        TextMap_AnswerDetail_200201 = {
          ContentEN = "Sixteen years ago, Donat's friend Sig orchestrated a kidnapping. The victim, Enola, died unexpectedly during the incident. Sig was sentenced to death.",
          TextMapId = "TextMap_AnswerDetail_200201"
        },
        TextMap_AnswerDetail_200202 = {
          ContentEN = "Once a Phoxhunter serving in the Escort, Giselle resigned sixteen years ago after a case verdict brought her into conflict with her superior.",
          TextMapId = "TextMap_AnswerDetail_200202"
        },
        TextMap_AnswerDetail_200203 = {
          ContentEN = "Violet, Sig's sister, left Icelake sixteen years ago. Now, it seems she has returned — a violet ribbon was found on Sig's grave, almost certainly left by her.",
          TextMapId = "TextMap_AnswerDetail_200203"
        },
        TextMap_AnswerDetail_200204 = {
          ContentEN = "In every performance, Violetta wears a violet ribbon — a keepsake, she says, from a dear friend. It's become her signature.",
          TextMapId = "TextMap_AnswerDetail_200204"
        },
        TextMap_AnswerDetail_200205 = {
          ContentEN = "Rosalind, daughter of Earl Magnus, has gone missing — presumed kidnapped. Her parents had recently hired her a vocal coach.",
          TextMapId = "TextMap_AnswerDetail_200205"
        },
        TextMap_AnswerDetail_200206 = {
          ContentEN = "One of Violetta's students has been kidnapped. The ransom letter makes cryptic reference to events from sixteen years ago.",
          TextMapId = "TextMap_AnswerDetail_200206"
        },
        TextMap_AnswerDetail_200207 = {
          ContentEN = "Sixteen years ago, Giselle was part of the team investigating the kidnapping case. The verdict disturbed her so profoundly, she chose to resign from the Escort.",
          TextMapId = "TextMap_AnswerDetail_200207"
        },
        TextMap_AnswerDetail_200208 = {
          ContentEN = "The violet ribbons are identical in both hue and style. Combined with their near-matching names, it's clear that Violetta and Violet share a close connection.",
          TextMapId = "TextMap_AnswerDetail_200208"
        },
        TextMap_AnswerDetail_200209 = {
          ContentEN = "It's highly likely that Violetta's missing student is Rosalind, daughter of Earl Magnus. The ransom letter's nod to events from sixteen years ago hints at a deeper connection to Violetta herself.",
          TextMapId = "TextMap_AnswerDetail_200209"
        },
        TextMap_AnswerDetail_200210 = {
          ContentEN = "Rosalind's abduction is clearly linked to the kidnapping case from sixteen years past — and Violetta knows exactly what happened back then.",
          TextMapId = "TextMap_AnswerDetail_200210"
        },
        TextMap_AnswerDetail_200211 = {
          ContentEN = "The old case concealed truths Violetta had long known. Giselle staged the recent \"kidnapping\" of her student to force those truths into the open.",
          TextMapId = "TextMap_AnswerDetail_200211"
        },
        TextMap_AnswerDetail_200301 = {
          ContentEN = "A cluster of Skylilies rests on the windowsill, their petals still damp with morning dew — someone must have placed them there recently.",
          TextMapId = "TextMap_AnswerDetail_200301"
        },
        TextMap_AnswerDetail_200302 = {
          ContentEN = "This quiet corner of EverSpring remains untouched. No footprints but Lingling's... nothing out of place at all.",
          TextMapId = "TextMap_AnswerDetail_200302"
        },
        TextMap_AnswerDetail_200303 = {
          ContentEN = "Found near the doorway, the album is filled with family snapshots. In one, a younger Lingling holds a bunch of Skylilies, smiling beside Nana — right outside this very home.",
          TextMapId = "TextMap_AnswerDetail_200303"
        },
        TextMap_AnswerDetail_200304 = {
          ContentEN = "A letter explaining that Lingling's parents brought her back from Haojing to Mistwharf for work — temporarily staying in the old workers' dorm they once called home.",
          TextMapId = "TextMap_AnswerDetail_200304"
        },
        TextMap_AnswerDetail_200305 = {
          ContentEN = "Someone left behind the bouquet without leaving a single trace.",
          TextMapId = "TextMap_AnswerDetail_200305"
        },
        TextMap_AnswerDetail_200306 = {
          ContentEN = "The \"ghost\" knew this humble little house well... and cherished the album. Perhaps they were once part of this family.",
          TextMapId = "TextMap_AnswerDetail_200306"
        },
        TextMap_AnswerDetail_200307 = {
          ContentEN = "The Skylily bouquet, the photo album, the way they knew the house — everything points to the return of someone dearly missed.",
          TextMapId = "TextMap_AnswerDetail_200307"
        },
        TextMap_AnswerDetail_200401 = {
          ContentEN = "A twelve-year-old child who caught a cold after playing in the snow — could this case relate to Weisheng's wife?",
          TextMapId = "TextMap_AnswerDetail_200401"
        },
        TextMap_AnswerDetail_200402 = {
          ContentEN = "A thirty-one-year-old woman whose eyesight worsened after long nights of study — could this case relate to Weisheng's wife?",
          TextMapId = "TextMap_AnswerDetail_200402"
        },
        TextMap_AnswerDetail_200403 = {
          ContentEN = "A forty-year-old man suffering hallucinations brought on by grief for his late wife — could this case relate to Weisheng's wife?",
          TextMapId = "TextMap_AnswerDetail_200403"
        },
        TextMap_AnswerDetail_200501 = {
          ContentEN = "The autopsy indicates that the victim died from a heavy blow to the front of the torso, causing fatal internal injuries. The weapon was likely the station guards' steel gauntlets. The victim had also been tortured before death.",
          TextMapId = "TextMap_AnswerDetail_200501"
        },
        TextMap_AnswerDetail_200502 = {
          ContentEN = "The autopsy shows that the victim's teeth suggest an affluent background, yet the contents of his stomach were cheap food commonly eaten by station hands.",
          TextMapId = "TextMap_AnswerDetail_200502"
        },
        TextMap_AnswerDetail_200503 = {
          ContentEN = "The only stack cleaner to leave recently was Handy, and he quit in a hurry yesterday.",
          TextMapId = "TextMap_AnswerDetail_200503"
        },
        TextMap_AnswerDetail_200504 = {
          ContentEN = "According to his coworkers, Handy was clumsy and slow at his work, which is highly unusual for a stack cleaner.",
          TextMapId = "TextMap_AnswerDetail_200504"
        },
        TextMap_AnswerDetail_200505 = {
          ContentEN = "According to his coworkers, Handy was exceptionally knowledgeable, which is uncommon among station hands.",
          TextMapId = "TextMap_AnswerDetail_200505"
        },
        TextMap_AnswerDetail_200506 = {
          ContentEN = "According to his coworkers, Handy said yesterday that Stationmaster Eisenbahn had threatened to kill him.",
          TextMapId = "TextMap_AnswerDetail_200506"
        },
        TextMap_AnswerDetail_200507 = {
          ContentEN = "Handy's clumsiness, poor work skills, and unusual level of knowledge suggest that he was not really a station hand.",
          TextMapId = "TextMap_AnswerDetail_200507"
        },
        TextMap_AnswerDetail_200508 = {
          ContentEN = "After Eisenbahn threatened to kill him yesterday, Handy quit in a hurry and tried to flee the station.",
          TextMapId = "TextMap_AnswerDetail_200508"
        },
        TextMap_AnswerDetail_200509 = {
          ContentEN = "The autopsy suggests that the victim came from an affluent background, yet had recently been eating cheap food typical of station hands. This strongly suggests that the victim was Handy, posing as a stack cleaner.",
          TextMapId = "TextMap_AnswerDetail_200509"
        },
        TextMap_AnswerDetail_200510 = {
          ContentEN = "After being threatened, Handy tried to leave the station. His fatal wound was inflicted by station guards utterly loyal to Eisenbahn. He was probably caught by Eisenbahn's men while trying to escape.",
          TextMapId = "TextMap_AnswerDetail_200510"
        },
        TextMap_AnswerDetail_200511 = {
          ContentEN = "Handy was likely a stranger from elsewhere who came to Icelake with a specific purpose. His work as a station hand was merely a cover for gathering information. Once his objective was exposed, he tried to flee, only to be silenced by Eisenbahn.",
          TextMapId = "TextMap_AnswerDetail_200511"
        },
        TextMap_AnswerDetail_200601 = {
          ContentEN = "Based on the fragmentation of the bricks at the scene, the explosive force was not significant.",
          TextMapId = "TextMap_AnswerDetail_200601"
        },
        TextMap_AnswerDetail_200602 = {
          ContentEN = "Given the placement of the explosive, the bomb was planted inside the ticket gates, bypassing security checks.",
          TextMapId = "TextMap_AnswerDetail_200602"
        },
        TextMap_AnswerDetail_200603 = {
          ContentEN = "The explosion was more noise than substance — the culprit found the optimal placement spot.",
          TextMapId = "TextMap_AnswerDetail_200603"
        },
        TextMap_AnswerDetail_200604 = {
          ContentEN = "Only scattered bloodstains were found at the scene, suggesting no fatalities or serious injuries from the blast.",
          TextMapId = "TextMap_AnswerDetail_200604"
        },
        TextMap_AnswerDetail_200605 = {
          ContentEN = "The culprit successfully bypassed security, placed the explosive inside the ticket gates, and detonated it at a spot that amplifies the sound of the blast, indicating a deep familiarity with the station.",
          TextMapId = "TextMap_AnswerDetail_200605"
        },
        TextMap_AnswerDetail_200606 = {
          ContentEN = "The bomb was not powerful, and no one was seriously injured, suggesting the purpose of the explosion was not to harm, but to incite panic.",
          TextMapId = "TextMap_AnswerDetail_200606"
        },
        TextMap_AnswerDetail_200607 = {
          ContentEN = "The culprit, familiar with the station's layout, detonated a bomb inside the station. The goal was not to harm, but to create panic.",
          TextMapId = "TextMap_AnswerDetail_200607"
        },
