        },
        UIGuide_XiaoChuan_1 = {
          ContentEN = "A <H>canoe</> drifts on the Waters of Forgetting. When lit, it creates a safe zone centred on itself and constantly moving, helping you withstand the Rift's erosion. You may move within this zone and steadily recover HP.",
          TextMapId = "UIGuide_XiaoChuan_1"
        },
        UIGuide_XiaoYao_1 = {
          ContentEN = "Xiaoyao will sometimes possess nearby objects, altering their appearance. Use the Mechanical Nexus's scan function to identify them.",
          TextMapId = "UIGuide_XiaoYao_1"
        },
        UIGuide_XiaoYao_2 = {
          ContentEN = "Use the Mechanical Nexus to draw Xiaoyao out of these possessed objects.",
          TextMapId = "UIGuide_XiaoYao_2"
        },
        UIGuide_XiaoYao_3 = {
          ContentEN = [[
Once exposed, Xiaoyao may flee and possess another nearby object.
Follow its trail and catch it.
If you do not catch it in time, you will lose the trail and the chase will end.]],
          TextMapId = "UIGuide_XiaoYao_3"
        },
        UIGuide_XiaoYao_4 = {
          ContentEN = "When Xiaoyao flees, it may leave behind Wishen's Paths, which let you travel quickly to other locations.",
          TextMapId = "UIGuide_XiaoYao_4"
        },
        UIGuide_XingShi_1 = {
          ContentEN = "Knock on an <H>Enlightenment Stele</> to activate mechanisms of the Myriad-Snare Hunting Array and alter the structure of the area.",
          TextMapId = "UIGuide_XingShi_1"
        },
        UIGuide_XuanYong_1 = {
          ContentEN = "Basalt Sentinels housing the spirits of the forebears are scattered throughout the Taixu Mausoleum. They can be destroyed, but shattering them may incur the forebears' wrath, unleashing enemies or hidden traps.",
          TextMapId = "UIGuide_XuanYong_1"
        },
        UIGuide_YanQueFeiXing_1 = {
          ContentEN = "To access this mode, please equip [Mechanical Nexus: The Bane] in your Tactical Backpack.",
          TextMapId = "UIGuide_YanQueFeiXing_1"
        },
        UIGuide_YanQueFeiXing_2 = {
          ContentEN = "The Yanfinch's navigation system is malfunctioning. Use [Mechanical Nexus: The Bane] to guide it to its destination and recalibrate it.",
          TextMapId = "UIGuide_YanQueFeiXing_2"
        },
        UIGuide_YanQueFeiXing_3 = {
          ContentEN = "During flight, the Yanfinch may randomly drop [Component: Repair Units] from its internal storage. Strike them with [Mechanical Nexus: The Bane] to charge them and repair the Yanfinch.",
          TextMapId = "UIGuide_YanQueFeiXing_3"
        },
        UIGuide_YanQueFeiXing_4 = {
          ContentEN = "During flight, the Yanfinch may randomly drop [Battery: Acceleration Units] from its internal storage. Strike them with [Mechanical Nexus: The Bane] to boost the Yanfinch's speed.",
          TextMapId = "UIGuide_YanQueFeiXing_4"
        },
        UIGuide_YanQueFeiXing_5 = {
          ContentEN = "During flight, the Yanfinch may randomly drop [Adhesive: Faulty Unit] from its internal storage. Striking it with [Mechanical Nexus: The Bane] hinders the Yanfinch and slows it down.",
          TextMapId = "UIGuide_YanQueFeiXing_5"
        },
        UIGuide_YanQueFeiXing_6 = {
          ContentEN = "Once the Yanfinch reaches its destination, recalibration is complete and you can claim your rewards.",
          TextMapId = "UIGuide_YanQueFeiXing_6"
        },
        UIGuide_YanQue_1 = {
          ContentEN = "Yanfinches patrol along fixed routes. Be careful not to let them spot you.",
          TextMapId = "UIGuide_YanQue_1"
        },
        UIGuide_YanQue_2 = {
          ContentEN = [[
Approach a Yanfinch from behind to disable it temporarily.
Once it recovers, it will resume its patrol.]],
          TextMapId = "UIGuide_YanQue_2"
        },
        UIGuide_YanShi_1 = {
          ContentEN = "Some cave entrances are blocked by rocks.",
          TextMapId = "UIGuide_YanShi_1"
        },
        UIGuide_YanShi_2 = {
          ContentEN = "These rocks can be broken with melee or ranged weapons — melee attacks are more efficient.",
          TextMapId = "UIGuide_YanShi_2"
        },
        UIGuide_YinZong_1 = {
          ContentEN = "Xiaoyao occasionally appears throughout Huaxu. Interact with him, then search the surrounding area for his trail to earn rewards.",
          TextMapId = "UIGuide_YinZong_1"
        },
        UIGuide_YuBo_1 = {
          ContentEN = "Some censers in Haojing are still heavily affected by the Scourge of Zhuyin and cannot reconnect to the Nine Chapters of Dafeng. Assist the incense wardens of the Xuanheng Sect in purging the corruption and returning the censers to working order.",
          TextMapId = "UIGuide_YuBo_1"
        },
        UIGuide_YuBo_2 = {
          ContentEN = "Only purified censers can function normally and restore the area's ambient incense density.",
          TextMapId = "UIGuide_YuBo_2"
        },
        UIGuide_YuBo_3 = {
          ContentEN = "Some residual miasma clusters left by the Scourge of Zhuyin react to incense in the air and split into smaller clusters.",
          TextMapId = "UIGuide_YuBo_3"
        },
        UIGuide_YuBo_4 = {
          ContentEN = "Use [Mechanical Nexus] to gather the smaller clusters, causing them to overload and expand.",
          TextMapId = "UIGuide_YuBo_4"
        },
        UIGuide_YuBo_5 = {
          ContentEN = "Attack the expanded clusters to purify them.",
          TextMapId = "UIGuide_YuBo_5"
        },
        UIGuide_ZhanFeng_1 = {
          ContentEN = "Ring the <H>Aeolian Chime</> and it will respond to your wish, awakening hidden mechanisms or memories of bygone days.",
          TextMapId = "UIGuide_ZhanFeng_1"
        },
        UIGuide_ZhenLv_1 = {
          ContentEN = [[
