        UI_DUNGEON_BACKROOM = {
          ContentEN = "Cell",
          TextMapId = "UI_DUNGEON_BACKROOM"
        },
        UI_DUNGEON_CHEST_START = {
          ContentEN = "Search for the chest",
          TextMapId = "UI_DUNGEON_CHEST_START"
        },
        UI_DUNGEON_CHEST_SUCCESS = {
          ContentEN = "Chest found",
          TextMapId = "UI_DUNGEON_CHEST_SUCCESS"
        },
        UI_DUNGEON_CONTENT_CAPTURE_1 = {
          ContentEN = "\"I've got us a big job — to capture some guy. If the target resists, we can use force to have everything under control. All you have to do is catch the target, and then you can leave the rest to me. Although we don't know what the target has done, it's best not to ask too much about the client's business. 'Less asking and more doing' is always right, don't you think?\" — Wells",
          TextMapId = "UI_DUNGEON_CONTENT_CAPTURE_1"
        },
        UI_DUNGEON_CONTENT_CAPTURE_2 = {
          ContentEN = "\"I've taken on a big job. We need to capture someone, and if the target resists, we can use force. If the target tries to escape, we can continue to pursue them. Your only job is to catch the target. You can leave the rest to me. Although we don't know what the target has done, it's best not to ask too many questions about the client's business. Less asking, and more doing. Less talking, and less thinking.\" — Wells",
          TextMapId = "UI_DUNGEON_CONTENT_CAPTURE_2"
        },
        UI_DUNGEON_CONTENT_DEFENCE_1 = {
          ContentEN = "\"Most people only regard Crystallo as beautiful ornaments, and neglect the research value of their formation and luminescent properties. I heard someone found a bunch of powerful Crystallo. How can I just sit and do nothing after hearing that?! Hmm... Great research requires formidable Phoxhunters. You'll protect me well while I'm researching Crystallo, right? Right?\" — Lunoxplorer",
          TextMapId = "UI_DUNGEON_CONTENT_DEFENCE_1"
        },
        UI_DUNGEON_CONTENT_DEFENCE_2 = {
          ContentEN = "\"Most people only regard Crystallo as beautiful ornaments, and neglect the research value of their formation and luminescent properties. I heard someone found a bunch of powerful Kijings. How can I just sit and do nothing after hearing that?! Hmm... Great research requires formidable Phoxhunters. You'll protect me well while I'm researching Kijings, right? Right?\" — Lunoxplorer",
          TextMapId = "UI_DUNGEON_CONTENT_DEFENCE_2"
        },
        UI_DUNGEON_CONTENT_DEFENCE_3 = {
          ContentEN = "I heard someone found a bunch of powerful devices. How can I just sit and do nothing after hearing that?! Hmm... Great research requires formidable Phoxhunters. You'll protect me well while I'm researching these devices, right? Right?\" — Lunoxplorer",
          TextMapId = "UI_DUNGEON_CONTENT_DEFENCE_3"
        },
        UI_DUNGEON_CONTENT_EXCAVATION_1 = {
          ContentEN = "\"The weather is so nice, let's go for a walk... Oh wait, no! We can go explore outdoors together! And we can conduct research at the same time! Remember to take good care of these exploration devices. They might not be very user-friendly, but they are very expensive... After we finish exploring the terrain, I'll add your name to my research report!\" — Lunoxplorer",
          TextMapId = "UI_DUNGEON_CONTENT_EXCAVATION_1"
        },
        UI_DUNGEON_CONTENT_EXTERMINATE_1 = {
          ContentEN = "\"Life invariably finds its rightful place. If boundaries are crossed, our response is quite straightforward: terminate everyone without exception. That's all there is to it.\" — From an unnamed client",
          TextMapId = "UI_DUNGEON_CONTENT_EXTERMINATE_1"
        },
        UI_DUNGEON_CONTENT_HIJACK_1 = {
          ContentEN = "\"Have you heard about the new models rolling out here? I've got to get one of those for a closer look! Just stay by the vehicle and signal me, and I'll start it up in my own way. You might take minor damage from the car's defence system, but don't be afraid — it won't kill you. And don't worry about the ethics — I'll return it once I'm done with my research!\" — From a hardcore vehicle researcher",
          TextMapId = "UI_DUNGEON_CONTENT_HIJACK_1"
        },
        UI_DUNGEON_CONTENT_RESCUE_1 = {
          ContentEN = "\"Infiltrate into the area marked on the map, rescue the target trapped in the cell, and escort them to the designated location. Feel free to pick up any loot or take down a few enemies along the way, but bear these rules in mind: Do not inquire about the commission's purpose, the target's identity, or our next plan. Save the target, get paid, and erase this commission from your memory — for the benefit of us both.\" — From a mysterious client",
          TextMapId = "UI_DUNGEON_CONTENT_RESCUE_1"
        },
        UI_DUNGEON_CONTENT_SABOTAGEPRO_1 = {
          ContentEN = "\"Push this world too far — and one day, it will push back and destroy us. That's why I need you to dismantle those strange machines. I won't be able to hold things off forever — if you're not back in time, you're on your own.\"\n — A dangerous client",
          TextMapId = "UI_DUNGEON_CONTENT_SABOTAGEPRO_1"
        },
        UI_DUNGEON_CONTENT_SABOTAGE_1 = {
          ContentEN = "\"Lunatics of The Forsakens have concocted a bomb they call 'Finale Flare', and the consequences of it detonating go far beyond people's deaths. The rift between The Forsaken and the other factions will intensify, and the living conditions of civilians will only deteriorate further. Hence, I'm entrusting you with this commission: disable the detonator of 'Finale Flare', prevent the explosion, and if possible, teach those fanatics a lesson. Remember, time is of the essence. I have little time to remain here and personally deliver your reward.\" — An Anonymous Client",
          TextMapId = "UI_DUNGEON_CONTENT_SABOTAGE_1"
        },
        UI_DUNGEON_CONTENT_SURVIVALPRO_1 = {
          ContentEN = "\"I hear our next stop is choked with Toxic Smog... But I, the great Demon King, won't bail on our quest over something so trivial! Let's brew the Serum at the Potion Station and slice through that miasma!\" — Snow",
          TextMapId = "UI_DUNGEON_CONTENT_SURVIVALPRO_1"
        },
        UI_DUNGEON_CONTENT_SURVIVAL_1 = {
          ContentEN = "\"To traverse every patch of land and explore every inch of territory is a fundamental quality of a Demon King. So, this uncharted territory must be explored by us Noctoyagers! Although it may be dangerous, there is no need for concern. I've prepared a bunch of precious Serums for when we're travelling. In case anything happens, we'll have them to keep us alive!\" — Snow",
          TextMapId = "UI_DUNGEON_CONTENT_SURVIVAL_1"
        },
        UI_DUNGEON_CONTENT_SYNTHESISII_1 = {
          ContentEN = "\"Sportsmanship before victory\"? Rubbish! No one remembers second place! If you want prizes, hunger for glory, or trust your skills — then step up! Dive into the frenzy and feel the rush of competition!\" — Fanatical Event Host",
          TextMapId = "UI_DUNGEON_CONTENT_SYNTHESISII_1"
        },
        UI_DUNGEON_CONTENT_SYNTHESIS_1 = {
          ContentEN = "\"Sportsmanship before victory\"? Rubbish! No one remembers second place! If you want prizes, hunger for glory, or trust your skills — then step up! Dive into the frenzy and feel the rush of competition!\" — Fanatical Event Host",
          TextMapId = "UI_DUNGEON_CONTENT_SYNTHESIS_1"
        },
        UI_DUNGEON_CONTENT_SoloTreasure_1 = {
          ContentEN = "Those who had long slept without a care were jolted awake by a sudden thunderclap. They realised the storm on the horizon would bring upheaval to their ancient realm. Change first took the stage at the long-awaited Grand Incense Rite.",
          TextMapId = "UI_DUNGEON_CONTENT_SoloTreasure_1"
        },
        UI_DUNGEON_CONTENT_TESTING_1 = {
          ContentEN = "\"Get them out of here, every single one!\" demanded the frustrated client.",
          TextMapId = "UI_DUNGEON_CONTENT_TESTING_1"
        },
