        },
        UI_Skin_Des_0010 = {
          ContentEN = "The bell chimes on the year's shortest day, and wishes are entrusted to the night, to be carried on starlight toward tomorrow.",
          TextMapId = "UI_Skin_Des_0010"
        },
        UI_Skin_Des_0011 = {
          ContentEN = "Beauty unveiled, grace in its wake.",
          TextMapId = "UI_Skin_Des_0011"
        },
        UI_Skin_Des_0121 = {
          ContentEN = "Why is one of the snowmen so much bigger than the others?",
          TextMapId = "UI_Skin_Des_0121"
        },
        UI_Skin_Des_0122 = {
          ContentEN = "Between the bell's chime and turning pages, the years slip away.",
          TextMapId = "UI_Skin_Des_0122"
        },
        UI_Skin_Des_0131 = {
          ContentEN = "We drink deep on sleepless, velvet-blue nights, whistling as we race into the midnight chill.",
          TextMapId = "UI_Skin_Des_0131"
        },
        UI_Skin_Des_0141 = {
          ContentEN = "Sin needs no hothouse. It blooms in silence, deep within the human heart.",
          TextMapId = "UI_Skin_Des_0141"
        },
        UI_Skin_Des_1101 = {
          ContentEN = "Black is the colour of night — a calm, watchful veil drawn over the world. Black is the colour of shadow — a cloak that lets one remain ever near to those they hold dear. Berenica favours it.",
          TextMapId = "UI_Skin_Des_1101"
        },
        UI_Skin_Des_1102 = {
          ContentEN = "Wherever she goes, the shadow of Hyperborea hangs over her — a dark, invisible cage that never lifts.",
          TextMapId = "UI_Skin_Des_1102"
        },
        UI_Skin_Des_110201 = {
          ContentEN = "The noble angel takes up the sword of judgement. Sinners shall be condemned. The innocent shall be absolved.",
          TextMapId = "UI_Skin_Des_110201"
        },
        UI_Skin_Des_1103 = {
          ContentEN = "A shadow in motion. A fumbling actor on a stage. A tale spun by a fool.",
          TextMapId = "UI_Skin_Des_1103"
        },
        UI_Skin_Des_1104 = {
          ContentEN = "Gilded couture — bespoke, ostentatious — more than mere attire; it is a proclamation of status.",
          TextMapId = "UI_Skin_Des_1104"
        },
        UI_Skin_Des_1501 = {
          ContentEN = "The Elysian Church's doctrine is not merely stitched into fabric — it is etched upon the soul, bearing witness to a girl who time and again sheds her rage, and rises patient and resolute.",
          TextMapId = "UI_Skin_Des_1501"
        },
        UI_Skin_Des_1502 = {
          ContentEN = "Gauzy veils, spun of dusk and aurora, guide each soul across the tear-brimmed river — to the Misty Sea, where all are reborn.",
          TextMapId = "UI_Skin_Des_1502"
        },
        UI_Skin_Des_150201 = {
          ContentEN = "Though miracles have vanished from the world, there are still mortals willing to bear the weight of faith.",
          TextMapId = "UI_Skin_Des_150201"
        },
        UI_Skin_Des_1503 = {
          ContentEN = "Rain slips from flowing robes, gathers at the sword's tip, then vanishes into the world of drifting blades.",
          TextMapId = "UI_Skin_Des_1503"
        },
        UI_Skin_Des_1504 = {
          ContentEN = "Let dreams soar and pride aloft, with a pinch of cyan, a measure of wit, and a breath of dawn.",
          TextMapId = "UI_Skin_Des_1504"
        },
        UI_Skin_Des_150401 = {
          ContentEN = "Wings wrought by will, now borne upon the wind.",
          TextMapId = "UI_Skin_Des_150401"
        },
        UI_Skin_Des_1601 = {
          ContentEN = "Drifting through night and sea, in robes of white, to meet the dawn.",
          TextMapId = "UI_Skin_Des_1601"
        },
        UI_Skin_Des_1801 = {
          ContentEN = "The nightingale pins snowy plumes to her tale, letting the delicate wings carry her dreams into the clouds.",
          TextMapId = "UI_Skin_Des_1801"
        },
        UI_Skin_Des_180101 = {
          ContentEN = "Shadows adrift beneath the moonlight; the restless whispering among the pages.",
          TextMapId = "UI_Skin_Des_180101"
        },
        UI_Skin_Des_2101 = {
          ContentEN = "Jellyfish tendrils drift into the deep like a trailing hem, setting a lover's heart aquiver in the dark.",
          TextMapId = "UI_Skin_Des_2101"
        },
        UI_Skin_Des_210101 = {
          ContentEN = "The waves soak the hem of her white tulle dress. Upon them rides her whisper: \"Only death shall part us.\"",
          TextMapId = "UI_Skin_Des_210101"
        },
        UI_Skin_Des_210102 = {
          ContentEN = "A murmur of love through the silks, an eternity sealed in a fatal kiss.",
          TextMapId = "UI_Skin_Des_210102"
        },
        UI_Skin_Des_2301 = {
          ContentEN = "What writhes in the dark — conspiracy, chaos, crime? None of those. Just tentacles.",
          TextMapId = "UI_Skin_Des_2301"
        },
        UI_Skin_Des_2401 = {
          ContentEN = "Wisps of herbal fragrance drift through white sleeves, whispering of life's return to the withered.",
          TextMapId = "UI_Skin_Des_2401"
        },
        UI_Skin_Des_240101 = {
          ContentEN = "Tides to wash away the dust, waves to still the heart.",
          TextMapId = "UI_Skin_Des_240101"
        },
        UI_Skin_Des_3101 = {
          ContentEN = "Gunpowder warmth clings to the matte uniform — driven on by the pulse of fervent blood.",
          TextMapId = "UI_Skin_Des_3101"
        },
        UI_Skin_Des_310101 = {
          ContentEN = "Though miracles have vanished from the world, there are still mortals willing to bear the weight of faith.",
          TextMapId = "UI_Skin_Des_310101"
        },
        UI_Skin_Des_3102 = {
          ContentEN = "A delicate bouquet in her hands, a hidden arsenal beneath her skirt. Like the black and white of her dress, she walks the line between light and shadow, each day a quiet verse in a maid's silent devotion.",
          TextMapId = "UI_Skin_Des_3102"
        },
        UI_Skin_Des_3103 = {
          ContentEN = "Burning threads of red and white bind a madman's reveries — and stitch together a boy's innocent dream.",
          TextMapId = "UI_Skin_Des_3103"
        },
        UI_Skin_Des_3201 = {
          ContentEN = "Chains and thorns mark retribution for sin — and bind the righteous fire that burns within.",
          TextMapId = "UI_Skin_Des_3201"
        }
      }
    end
  },
  {
    MinKey = "UI_Skin_Des_3202",
    MaxKey = "UI_SpeakName_Zhongren9",
    Loader = function()
      return {
        UI_Skin_Des_3202 = {
          ContentEN = "A figure limned in luminous grace, every gesture steeped in wine and whispered dusk.",
          TextMapId = "UI_Skin_Des_3202"
        },
        UI_Skin_Des_3301 = {
          ContentEN = "A multipurpose helmet forged from a pot — sturdy armour for a scavenger girl.",
          TextMapId = "UI_Skin_Des_3301"
        },
        UI_Skin_Des_4101 = {
          ContentEN = "Star-flecked blue shimmers across her uniform — a will to protect, and a gaze lifted towards the future.",
          TextMapId = "UI_Skin_Des_4101"
        },
        UI_Skin_Des_410101 = {
          ContentEN = "Shadows adrift beneath the moonlight; the restless whispering among the pages.",
          TextMapId = "UI_Skin_Des_410101"
        },
        UI_Skin_Des_4102 = {
          ContentEN = "Sunlight spills across sumptuous brocade like molten gold — the dawn of revolution reflected in her golden eyes.",
          TextMapId = "UI_Skin_Des_4102"
        },
        UI_Skin_Des_410201 = {
          ContentEN = "Over wine and words, fates are drawn and fortunes unfold.",
          TextMapId = "UI_Skin_Des_410201"
        },
        UI_Skin_Des_4201 = {
          ContentEN = "Heaven's thunder courses through his form. Upholding Dafeng's mandate, sin finds no refuge — nor does he.",
          TextMapId = "UI_Skin_Des_4201"
        },
        UI_Skin_Des_4202 = {
          ContentEN = "A medal gleams with a genius mind above. A uniform beats the heart of an ordinary man below.",
          TextMapId = "UI_Skin_Des_4202"
        },
        UI_Skin_Des_4301 = {
          ContentEN = "She wears neither armour nor crown — yet her presence resounds with commanding dread.",
          TextMapId = "UI_Skin_Des_4301"
        },
        UI_Skin_Des_5101 = {
          ContentEN = "White plumes flutter through the streets, trailing the scent of malt and hearthfire — borne on the wind to every empty stomach.",
          TextMapId = "UI_Skin_Des_5101"
        },
        UI_Skin_Des_510101 = {
          ContentEN = "Sunshine gathered, sunshine scattered!",
          TextMapId = "UI_Skin_Des_510101"
        },
        UI_Skin_Des_5102 = {
          ContentEN = "Simple garb won't silence the crimson wails of dark alleys — but it shelters a sliver of starlight from the world's brutality.",
          TextMapId = "UI_Skin_Des_5102"
