        ZhiLiuEntrust_Lock_Time1 = {
          ContentEN = "Unlocks in {DD}d {H}h",
          TextMapId = "ZhiLiuEntrust_Lock_Time1"
        },
        ZhiLiuEntrust_Lock_Time2 = {
          ContentEN = "Unlocks in {H}h {M}m",
          TextMapId = "ZhiLiuEntrust_Lock_Time2"
        },
        ZhiLiuEntrust_Objective = {
          ContentEN = "Commission Target",
          TextMapId = "ZhiLiuEntrust_Objective"
        },
        ZhiLiuEntrust_Progress = {
          ContentEN = "Commission Progress",
          TextMapId = "ZhiLiuEntrust_Progress"
        },
        ZhiLiuEntrust_Resource = {
          ContentEN = "Shopping List",
          TextMapId = "ZhiLiuEntrust_Resource"
        },
        voice_ch_char_Aote_vo_appear = {
          ContentEN = "This is quite a delicate mission. Shall we do it together?",
          TextMapId = "voice_ch_char_Aote_vo_appear"
        },
        voice_ch_char_Aote_vo_battleidle = {
          ContentEN = "Stock expenses... transportation costs... How much was it? Darn it, I forgot again. I feel lost without my account book.",
          TextMapId = "voice_ch_char_Aote_vo_battleidle"
        },
        voice_ch_char_Aote_vo_battlestart = {
          ContentEN = "Let's finish this quickly. I have tons of chores waiting for me at home.",
          TextMapId = "voice_ch_char_Aote_vo_battlestart"
        },
        voice_ch_char_Aote_vo_be_hit_heavy_r01 = {
          ContentEN = "I only just mended my clothes!",
          TextMapId = "voice_ch_char_Aote_vo_be_hit_heavy_r01"
        },
        voice_ch_char_Aote_vo_be_hit_heavy_r02 = {
          ContentEN = "Owh!",
          TextMapId = "voice_ch_char_Aote_vo_be_hit_heavy_r02"
        },
        voice_ch_char_Aote_vo_birthday = {
          ContentEN = "Happy birthday to you! Happy birthday to you! Ah, remember how we met, both searching for birthday gifts. And now all this time later, we're celebrating another 'birthday' - and we're still here together. Isn't fate just wonderful?",
          TextMapId = "voice_ch_char_Aote_vo_birthday"
        },
        voice_ch_char_Aote_vo_companio_01 = {
          ContentEN = "Why are you here? Are you alright? How do you feel? You should get some kip. Let me know if you need anything, okay?",
          TextMapId = "voice_ch_char_Aote_vo_companio_01"
        },
        voice_ch_char_Aote_vo_companio_02_1 = {
          ContentEN = "You're the girl who's very close to {nickname}, right? I heard you've been feeling unwell. Do you want to sit down and have a rest?",
          TextMapId = "voice_ch_char_Aote_vo_companio_02_1"
        },
        voice_ch_char_Aote_vo_companio_02_2 = {
          ContentEN = "If you're hungry, thirsty, or need anything, just say the word. It's no bother — I look after my sickly sister back home all the time. A friend of {nickname}'s is a friend of mine.",
          TextMapId = "voice_ch_char_Aote_vo_companio_02_2"
        },
        voice_ch_char_Aote_vo_companio_03_1 = {
          ContentEN = "Ms Camilla! What brings you here? Not another urgent request, I hope? We've been worn out lately and could really use a breather...",
          TextMapId = "voice_ch_char_Aote_vo_companio_03_1"
        },
        voice_ch_char_Aote_vo_companio_03_2 = {
          ContentEN = "Though, if the pay is good, I'm all ears.",
          TextMapId = "voice_ch_char_Aote_vo_companio_03_2"
        },
        voice_ch_char_Aote_vo_companio_04 = {
          ContentEN = "Remember me from when I was little? You were like a sweet sister to me, and a tough dad all rolled into one... Uh, I'm not saying you're old and violent, just... thank you for making me feel I belonged back then.",
          TextMapId = "voice_ch_char_Aote_vo_companio_04"
        },
        voice_ch_char_Aote_vo_die_r01 = {
          ContentEN = "*cough*... Even the best of us fall down sometimes...",
          TextMapId = "voice_ch_char_Aote_vo_die_r01"
        },
        voice_ch_char_Aote_vo_die_r02 = {
          ContentEN = "Take care of Fina for me... please.",
          TextMapId = "voice_ch_char_Aote_vo_die_r02"
        },
        voice_ch_char_Aote_vo_fail = {
          ContentEN = "Tsk. You guys retreat. I'll follow.",
          TextMapId = "voice_ch_char_Aote_vo_fail"
        },
        voice_ch_char_Aote_vo_gain = {
          ContentEN = "We already know each other pretty well, do I really have to introduce myself? Alright, fine... I'm Outsider, from the \"Noctoyagers.\" I serve as... a guardian of this sprog-rich team, I guess?",
          TextMapId = "voice_ch_char_Aote_vo_gain"
        },
        voice_ch_char_Aote_vo_idle = {
          ContentEN = "It's nice having peace of mind and a place I can feel attached to after so many years.",
          TextMapId = "voice_ch_char_Aote_vo_idle"
        },
        voice_ch_char_Aote_vo_lvup = {
          ContentEN = "Don't spare too many thoughts on me. It's just... kinda awkward. Nah, forget it.",
          TextMapId = "voice_ch_char_Aote_vo_lvup"
        },
        voice_ch_char_Aote_vo_revive = {
          ContentEN = "No big deal. I'm covered in wounds like that.",
          TextMapId = "voice_ch_char_Aote_vo_revive"
        },
        voice_ch_char_Aote_vo_skill01_r01 = {
          ContentEN = "Small tricks, big payoffs.",
          TextMapId = "voice_ch_char_Aote_vo_skill01_r01"
        },
        voice_ch_char_Aote_vo_skill01_r02 = {
          ContentEN = "Check this out!",
          TextMapId = "voice_ch_char_Aote_vo_skill01_r02"
        },
        voice_ch_char_Aote_vo_skill02_r01 = {
          ContentEN = "Relax — it's for your own good.",
          TextMapId = "voice_ch_char_Aote_vo_skill02_r01"
        },
        voice_ch_char_Aote_vo_skill02_r02 = {
          ContentEN = "Playtime's over — Time to get serious.",
          TextMapId = "voice_ch_char_Aote_vo_skill02_r02"
        },
        voice_ch_char_Aote_vo_skill02_r03 = {
          ContentEN = "Cherish your last glimpse of the world.",
          TextMapId = "voice_ch_char_Aote_vo_skill02_r03"
        },
        voice_ch_char_Aote_vo_topic_01_1 = {
          ContentEN = "A guide? No, most folks in this trade aren't the type to stick their nose in a book. But I do have a few mottoes to share, like my personal fighting mantra: \"Two hits in the ribs, one on the head; so dead even the emperor can't pull 'em back.\"",
          TextMapId = "voice_ch_char_Aote_vo_topic_01_1"
        },
        voice_ch_char_Aote_vo_topic_01_2 = {
          ContentEN = "Don't bite off more than you can chew. In our line of work, greed is the biggest enemy — sometimes it comes from others, but more often, it comes from within.",
          TextMapId = "voice_ch_char_Aote_vo_topic_01_2"
        },
        voice_ch_char_Aote_vo_topic_02_1 = {
          ContentEN = "They're like a wildfire that's never fully extinguished, ready to flare up at any moment. For your own good, better keep your distance...",
          TextMapId = "voice_ch_char_Aote_vo_topic_02_1"
        },
        voice_ch_char_Aote_vo_topic_02_2 = {
          ContentEN = "Well... let's just say we've had our little scuffles. If you ever deal with them, make sure my name doesn't come up.",
          TextMapId = "voice_ch_char_Aote_vo_topic_02_2"
        },
        voice_ch_char_Aote_vo_topic_03_1 = {
          ContentEN = "Yeah. Can you grab that bandage over there for me? I need to keep it from Fina, or she'll make a big fuss again.",
          TextMapId = "voice_ch_char_Aote_vo_topic_03_1"
        },
        voice_ch_char_Aote_vo_topic_03_2 = {
          ContentEN = "I know, but injuries are part of the job. I'd rather she not worry so much. Cover for me if she asks, will you? I owe you one.",
          TextMapId = "voice_ch_char_Aote_vo_topic_03_2"
        },
        voice_ch_char_Aote_vo_topic_04_1 = {
          ContentEN = "Oh, would you like some? Don't mind their looks — just pop off the head, and they're crunchy like cookies, even with a hint of meaty aftertaste...",
          TextMapId = "voice_ch_char_Aote_vo_topic_04_1"
        },
        voice_ch_char_Aote_vo_topic_04_2 = {
          ContentEN = "Wha... where are you going!? This is vital survival wisdom... If you got lost in the wild with no food, these little critters could be a lifesaver.",
          TextMapId = "voice_ch_char_Aote_vo_topic_04_2"
        },
        voice_ch_char_Aote_vo_topic_05_1 = {
          ContentEN = "Wait a sec, why do you only have a few coins in your hand? Did you give away your share of the bounty again?",
          TextMapId = "voice_ch_char_Aote_vo_topic_05_1"
        },
        voice_ch_char_Aote_vo_topic_05_2 = {
          ContentEN = "But... Never mind, this is you, always looking out for others. Let me know if you're ever short on cash.",
          TextMapId = "voice_ch_char_Aote_vo_topic_05_2"
        },
        voice_ch_char_Aote_vo_topic_05_3 = {
          ContentEN = "...You're milking it, buddy.",
          TextMapId = "voice_ch_char_Aote_vo_topic_05_3"
        },
        voice_ch_char_Aote_vo_victory = {
          ContentEN = "Leave 'em all to me. I'll see if I can find any salvageable bits and bobs lying around.",
          TextMapId = "voice_ch_char_Aote_vo_victory"
        },
        voice_ch_char_Aote_vo_welcome = {
          ContentEN = "Here you are, finally! I've finished all my chores and got absolutely knackered, but I've only earned a few quid. Urgh... You know I do much for you guys.",
          TextMapId = "voice_ch_char_Aote_vo_welcome"
        },
        voice_ch_char_Baiheng01_vo_appear = {
          ContentEN = "I've prepared some vitality-boosting tonic broth. Be sure to have some before we swim — it will help keep you warm and ward off a chill.",
          TextMapId = "voice_ch_char_Baiheng01_vo_appear"
        },
        voice_ch_char_Baiheng01_vo_battlestart = {
          ContentEN = "This rare moment of leisure is far too precious. Let no trifling things steal the savor from it.",
          TextMapId = "voice_ch_char_Baiheng01_vo_battlestart"
        },
        voice_ch_char_Baiheng01_vo_gain = {
          ContentEN = "When I was little, my sister practically had to drag me out of the house before I would consent to splash in the sea with the family. If she could see me now, inviting you to walk the shore with me, I think the sight would make her quietly proud.",
          TextMapId = "voice_ch_char_Baiheng01_vo_gain"
        },
        voice_ch_char_Baiheng01_vo_skill02_r01 = {
          ContentEN = "Let the flawless flow scour the stain.",
          TextMapId = "voice_ch_char_Baiheng01_vo_skill02_r01"
        },
        voice_ch_char_Baiheng_vo_appear = {
          ContentEN = "Let me provide medicine for the battles to come.",
          TextMapId = "voice_ch_char_Baiheng_vo_appear"
        },
        voice_ch_char_Baiheng_vo_battleidle = {
          ContentEN = "How could I turn a deaf ear to such plaintive cries for aid?",
          TextMapId = "voice_ch_char_Baiheng_vo_battleidle"
        },
        voice_ch_char_Baiheng_vo_battlestart = {
          ContentEN = "I shall not let death prevail.",
          TextMapId = "voice_ch_char_Baiheng_vo_battlestart"
        },
        voice_ch_char_Baiheng_vo_be_hit_heavy_r01 = {
          ContentEN = "Foul impurities...",
          TextMapId = "voice_ch_char_Baiheng_vo_be_hit_heavy_r01"
        },
        voice_ch_char_Baiheng_vo_be_hit_r02 = {
          ContentEN = "My garments are sullied...",
          TextMapId = "voice_ch_char_Baiheng_vo_be_hit_r02"
        },
        voice_ch_char_Baiheng_vo_birthday = {
          ContentEN = "Today is your special day. In honour of this, I've prepared a humble offering — a collection of herbal remedies to ward off the minor ailments one might encounter in their travels. Whether it be a cold, a scrape, or a bruise, these will serve you well. Yet, it is my heartfelt hope that you remain so safe and well that you never have a need for them.",
          TextMapId = "voice_ch_char_Baiheng_vo_birthday"
        },
        voice_ch_char_Baiheng_vo_companio = {
          ContentEN = "Mr Chaos, you have new wounds on your body. May I offer you medical attention? *sigh* Or perhaps you'll accept this ointment then? It can prevent infections. It'll sting, mind you, although I dare say that you'll enjoy it... Be careful not to apply too much.",
          TextMapId = "voice_ch_char_Baiheng_vo_companio"
        },
        voice_ch_char_Baiheng_vo_companio_01 = {
          ContentEN = "Mr. Randy, in my humble opinion, lethargy and laxity are no less symptoms of illness. They may not trouble you now, but they sow the seeds of future ailments. Perhaps we could engage in some light sparring? A touch of exercise might do you good.",
          TextMapId = "voice_ch_char_Baiheng_vo_companio_01"
        },
        voice_ch_char_Baiheng_vo_companio_02 = {
          ContentEN = [[
While a healer may ease affliction, defying fate is beyond us. I can offer a remedy to cool the heart's heat, yet the root of your troubles lies beyond my grasp. It is best to accept and adapt to the flow of time to find your own path to solace...
 ]],
          TextMapId = "voice_ch_char_Baiheng_vo_companio_02"
        },
        voice_ch_char_Baiheng_vo_companio_03 = {
          ContentEN = "You often hear another voice speaking to you? Can others hear it too? How has your slumber been? Has something been weighing on your heart? The mind's afflictions are the most elusive to heal, even with the aid of Zhuyou techniques. But as a healer, I will spare no effort.",
          TextMapId = "voice_ch_char_Baiheng_vo_companio_03"
        },
        voice_ch_char_Baiheng_vo_die_r01 = {
          ContentEN = "Please protect... the others...",
          TextMapId = "voice_ch_char_Baiheng_vo_die_r01"
        },
        voice_ch_char_Baiheng_vo_die_r02 = {
          ContentEN = "If only... I were a better healer...",
          TextMapId = "voice_ch_char_Baiheng_vo_die_r02"
        },
        voice_ch_char_Baiheng_vo_fail = {
          ContentEN = "Fear not — here, take this to ease your pain.",
          TextMapId = "voice_ch_char_Baiheng_vo_fail"
        },
        voice_ch_char_Baiheng_vo_gain_1 = {
          ContentEN = "The road ahead is long and fraught with uncertainty... Yet, as providence has intertwined our paths, let us journey side by side, if only for a while.",
          TextMapId = "voice_ch_char_Baiheng_vo_gain_1"
        },
        voice_ch_char_Baiheng_vo_gain_2 = {
          ContentEN = "I am Fushu, a healer from Huaxu. If you are injured or unwell, please, do not conceal it from me. Though my skills may have their limits, I will do everything in my power to safeguard your well-being.",
          TextMapId = "voice_ch_char_Baiheng_vo_gain_2"
        },
        voice_ch_char_Baiheng_vo_idle = {
          ContentEN = "Sweeping up and venting in the morning, spraying strong liquor in the afternoon, and lighting incense sticks at dusk to drive away insects — that's the only way to keep a room clean.",
          TextMapId = "voice_ch_char_Baiheng_vo_idle"
        },
        voice_ch_char_Baiheng_vo_lvup = {
          ContentEN = "Maintaining a healthful regimen and regular exercise is a fundamental duty for every healer.",
          TextMapId = "voice_ch_char_Baiheng_vo_lvup"
        },
        voice_ch_char_Baiheng_vo_revive = {
          ContentEN = "Like blossoms, I bloom anew.",
          TextMapId = "voice_ch_char_Baiheng_vo_revive"
        },
        voice_ch_char_Baiheng_vo_skill01_r01 = {
          ContentEN = "Feel better soon!",
          TextMapId = "voice_ch_char_Baiheng_vo_skill01_r01"
        },
        voice_ch_char_Baiheng_vo_skill01_r02 = {
          ContentEN = "Let the healing flow!",
          TextMapId = "voice_ch_char_Baiheng_vo_skill01_r02"
        },
        voice_ch_char_Baiheng_vo_skill02_r01 = {
          ContentEN = "In silence, all is renewed.",
          TextMapId = "voice_ch_char_Baiheng_vo_skill02_r01"
        },
        voice_ch_char_Baiheng_vo_skill02_r02 = {
          ContentEN = "Like the moon waxing to its fullness.",
          TextMapId = "voice_ch_char_Baiheng_vo_skill02_r02"
        },
        voice_ch_char_Baiheng_vo_skill02_r03 = {
          ContentEN = "Breathe deeply the fragrance of healing.",
          TextMapId = "voice_ch_char_Baiheng_vo_skill02_r03"
        },
        voice_ch_char_Baiheng_vo_topic_01_1 = {
          ContentEN = "Indeed. Yet, the contents are dense and cryptic, and even the distinctions between certain remedies remain elusive to me. Perhaps I simply lack the aptitude for this craft.",
          TextMapId = "voice_ch_char_Baiheng_vo_topic_01_1"
        },
        voice_ch_char_Baiheng_vo_topic_01_2 = {
          ContentEN = "In my time... medication was not the primary means of healing. People practised a miraculous healing art called \"Zhuyou\" to ward off illness.",
          TextMapId = "voice_ch_char_Baiheng_vo_topic_01_2"
        },
        voice_ch_char_Baiheng_vo_topic_01_3 = {
          ContentEN = "While this method could bring healing and peace, it demanded the sacrifice of a healer's very life force. None of us lived to see old age — pouring out our essence unto death was the only path we knew.",
          TextMapId = "voice_ch_char_Baiheng_vo_topic_01_3"
        },
        voice_ch_char_Baiheng_vo_topic_01_4 = {
          ContentEN = "The Hall of Ephemerality may now be but a relic of time, yet the path of healing and saving lives has never lacked successors. Even under the heaviest burdens, there will always be those who press forward with unwavering resolve.",
          TextMapId = "voice_ch_char_Baiheng_vo_topic_01_4"
        },
        voice_ch_char_Baiheng_vo_topic_02_1 = {
          ContentEN = "Death is like a lamp extinguished — all traces vanish, all voices fade. That isolation, that profound stillness, consumes every glimmer of hope and possibility. If it lies within my power, I would spare any patient from falling into such an abyss.",
          TextMapId = "voice_ch_char_Baiheng_vo_topic_02_1"
        },
        voice_ch_char_Baiheng_vo_topic_02_2 = {
          ContentEN = "You're not mistaken. I... once returned from the brink of death, clawing my way back from the clutches of grave illness. Should such a trial confront me again, I cannot say with certainty that I would make the same choice.",
          TextMapId = "voice_ch_char_Baiheng_vo_topic_02_2"
        },
        voice_ch_char_Baiheng_vo_topic_03_1 = {
          ContentEN = "It's a place for healing and saving lives.",
          TextMapId = "voice_ch_char_Baiheng_vo_topic_03_1"
        },
        voice_ch_char_Baiheng_vo_topic_03_2 = {
          ContentEN = "The Hall's mission is singular — to heal, and to heal alone. If one were to speak of other aspects... every healer who trained within its walls planted an apricot tree on the first day of their practice. Yet, as time passed, storms and decay claimed many. Now, fewer than half remain.",
          TextMapId = "voice_ch_char_Baiheng_vo_topic_03_2"
        },
        voice_ch_char_Baiheng_vo_topic_03_3 = {
          ContentEN = "Waking up from a long slumber, I sought the apricot tree I once planted in my youth. Sadly, the tree had withered to barren wood, and not even this warm spring could coax new buds from its branches.",
          TextMapId = "voice_ch_char_Baiheng_vo_topic_03_3"
        },
        voice_ch_char_Baiheng_vo_topic_03_4 = {
          ContentEN = "Life rushes by, like a fleeting horse through a narrow chasm, a spark struck from flint, or a phantom wandering in a dream. How does one find their way back through such transience? The past slips further from reach, while hopes to amend it vanish like morning mist.",
          TextMapId = "voice_ch_char_Baiheng_vo_topic_03_4"
        },
        voice_ch_char_Baiheng_vo_topic_04_1 = {
          ContentEN = "I dream of a world without incurable maladies.",
          TextMapId = "voice_ch_char_Baiheng_vo_topic_04_1"
        },
        voice_ch_char_Baiheng_vo_topic_04_2 = {
          ContentEN = "It rings as but a fanciful daydream, doesn't it? Yet, even without the miracles of healing magic, the purpose of a healer remains unchanged. I must admit, coming from someone who still struggles to fully grasp medical texts, such a speech must sound absurd.",
          TextMapId = "voice_ch_char_Baiheng_vo_topic_04_2"
        },
        voice_ch_char_Baiheng_vo_topic_04_3 = {
          ContentEN = "But... I'll continue treading this path — not merely for the sake of others or the legacy of the Hall of Ephemerality, but for my own fulfilment as well.",
          TextMapId = "voice_ch_char_Baiheng_vo_topic_04_3"
        },
        voice_ch_char_Baiheng_vo_victory = {
          ContentEN = "I'll need to change my clothes back home.",
          TextMapId = "voice_ch_char_Baiheng_vo_victory"
        },
        voice_ch_char_Baiheng_vo_welcome = {
          ContentEN = "One's surroundings shape the spirit, and mindful care strengthens the body. Perhaps a walk beneath these kindly skies would do wonders for your health.",
          TextMapId = "voice_ch_char_Baiheng_vo_welcome"
        },
        voice_ch_char_Baonu_vo_appear = {
          ContentEN = "Samael, here we go!",
          TextMapId = "voice_ch_char_Baonu_vo_appear"
        },
        voice_ch_char_Baonu_vo_battleidle = {
          ContentEN = "Come out and accept your thrashing!",
          TextMapId = "voice_ch_char_Baonu_vo_battleidle"
        },
        voice_ch_char_Baonu_vo_battlestart = {
          ContentEN = "Absolution is God's domain, not mine!",
          TextMapId = "voice_ch_char_Baonu_vo_battlestart"
        },
        voice_ch_char_Baonu_vo_be_hit_heavy_r01 = {
          ContentEN = "Cowardly wretch!",
          TextMapId = "voice_ch_char_Baonu_vo_be_hit_heavy_r01"
        },
        voice_ch_char_Baonu_vo_be_hit_heavy_r02 = {
          ContentEN = "Samael!",
          TextMapId = "voice_ch_char_Baonu_vo_be_hit_heavy_r02"
        },
        voice_ch_char_Baonu_vo_birthday = {
          ContentEN = "Ahem... I chanced upon this cake shop after completing a mission, and they happened to be giving out free birthday cakes, and then I stumbled into you, the little troublemaker that always needs my protection. So, erm, you... Help me finish this leftover raspberry cake. Don't leave a single crumb!",
          TextMapId = "voice_ch_char_Baonu_vo_birthday"
        },
        voice_ch_char_Baonu_vo_companio_01 = {
          ContentEN = "Samael? Oh, it's alright. It wakes me up every morning, cheers me on during combat, and even has a dozen bedtime stories lined up for me! So, there's nothing to worry about.",
          TextMapId = "voice_ch_char_Baonu_vo_companio_01"
        },
        voice_ch_char_Baonu_vo_companio_02 = {
          ContentEN = [[
"Patience is one of the Seven Virtues. Those gifted with patience can discover hidden secrets and accomplish extraordinary... feats..."
I can't take it anymore! Don't imitate me dwarf in the name of the Nine Gods I'll cut you in half with Samel if you do that one more time!]],
          TextMapId = "voice_ch_char_Baonu_vo_companio_02"
        },
        voice_ch_char_Baonu_vo_companio_03 = {
          ContentEN = "Cream? What's wrong? That's how we Elysians take care of our weapons. You got a problem with that?",
          TextMapId = "voice_ch_char_Baonu_vo_companio_03"
        },
        voice_ch_char_Baonu_vo_companio_04 = {
          ContentEN = [[
How strange. I've never seen you vent your anger before...
Well... I, a candidate of the Seven Virtues, order you to show me your anger! No more preaching those silly virtues, doctrines, and scriptures. Let's see some real emotion for once!]],
          TextMapId = "voice_ch_char_Baonu_vo_companio_04"
        },
        voice_ch_char_Baonu_vo_die_r01 = {
          ContentEN = "I can't... befoul... Samael's name...",
          TextMapId = "voice_ch_char_Baonu_vo_die_r01"
        },
        voice_ch_char_Baonu_vo_die_r02 = {
          ContentEN = "I don't want to meet the Gods alone...",
          TextMapId = "voice_ch_char_Baonu_vo_die_r02"
        },
        voice_ch_char_Baonu_vo_fail = {
          ContentEN = "No, no, no... I'm not gonna let this get to me...",
          TextMapId = "voice_ch_char_Baonu_vo_fail"
        },
        voice_ch_char_Baonu_vo_gain = {
          ContentEN = "Behold, I am the great Miss Lisbell, candidate for the Patience of the Seven Virtues of the Elysian Church. In the name of the almighty Tower, the divine nine Gods of Elysian, the... what was it...? Ahem, forget it. Anyway, I command you to address me as \"Mistress Patience\". Do you understand?",
          TextMapId = "voice_ch_char_Baonu_vo_gain"
        },
        voice_ch_char_Baonu_vo_idle = {
          ContentEN = "Samael, it's a beautiful day outside! Isn't this the perfect weather to eat something cool? I've heard the Holy City has an amazing dessert called ice cream. It's a commoner's food, but I bet it's way tastier than anything those old farts are handing out. I'll secretly grab you some!",
          TextMapId = "voice_ch_char_Baonu_vo_idle"
        },
        voice_ch_char_Baonu_vo_lvup = {
          ContentEN = "Samael, I've become even stronger! Let's protect these weirdos together!",
          TextMapId = "voice_ch_char_Baonu_vo_lvup"
        },
        voice_ch_char_Baonu_vo_revive = {
          ContentEN = "Even Mistress Patience has her limits!",
          TextMapId = "voice_ch_char_Baonu_vo_revive"
        },
        voice_ch_char_Baonu_vo_skill01_r01 = {
          ContentEN = "Holiness!",
          TextMapId = "voice_ch_char_Baonu_vo_skill01_r01"
        },
        voice_ch_char_Baonu_vo_skill01_r02 = {
          ContentEN = "In the name of Patience!",
          TextMapId = "voice_ch_char_Baonu_vo_skill01_r02"
        },
        voice_ch_char_Baonu_vo_skill02_r01 = {
          ContentEN = "I can't take this... anymore!",
          TextMapId = "voice_ch_char_Baonu_vo_skill02_r01"
        },
        voice_ch_char_Baonu_vo_skill02_r02 = {
          ContentEN = "Samael, answer my call!",
          TextMapId = "voice_ch_char_Baonu_vo_skill02_r02"
        },
        voice_ch_char_Baonu_vo_skill02_r03 = {
          ContentEN = "Samael, grant me your \"wrath\"!",
          TextMapId = "voice_ch_char_Baonu_vo_skill02_r03"
        },
        voice_ch_char_Baonu_vo_topic_01_1 = {
          ContentEN = "Samael's not just a weapon — it's my best friend!",
          TextMapId = "voice_ch_char_Baonu_vo_topic_01_1"
        },
        voice_ch_char_Baonu_vo_topic_01_2 = {
          ContentEN = "In the Church, only those chosen by one of the Seven Relics can become one of the \"Seven Virtues.\" There were loads of strong warriors that day, but I was the only one who could pull Samael free. It chose me, so of course I've got to treat it right!",
          TextMapId = "voice_ch_char_Baonu_vo_topic_01_2"
        },
        voice_ch_char_Baonu_vo_topic_01_3 = {
          ContentEN = "...Only thing is, ever since then, it hasn't responded to me. Not once... W—Wait — that's top secret! You can't tell anyone, got it!?",
          TextMapId = "voice_ch_char_Baonu_vo_topic_01_3"
        },
        voice_ch_char_Baonu_vo_topic_01_4 = {
          ContentEN = "Huh!? It doesn't like ice cream!? Then... what about mashed potatoes? Or salad dressing!?",
          TextMapId = "voice_ch_char_Baonu_vo_topic_01_4"
        },
        voice_ch_char_Baonu_vo_topic_02_1 = {
          ContentEN = "Ugh—! Shut up! I don't want to talk about those old stick-in-the-muds! Ughhh, you've ruined my day— ...No, no, I can't get angry. Stay calm, Lisbell...",
          TextMapId = "voice_ch_char_Baonu_vo_topic_02_1"
        },
        voice_ch_char_Baonu_vo_topic_02_2 = {
          ContentEN = "Ahem! Not at all! They are absolutely wonderful. So kind and understanding. When you mess up a hymn, you just have to copy it thirty times. And if they catch you feeding cream to Samael, it's only two days locked up for solitary reflection. Really, they're the best. Absolutely lovely...",
          TextMapId = "voice_ch_char_Baonu_vo_topic_02_2"
        },
        voice_ch_char_Baonu_vo_topic_03_1 = {
          ContentEN = "Just what it says. Being patient means staying strong and stoic — putting up with anything and never, ever blowing up!",
          TextMapId = "voice_ch_char_Baonu_vo_topic_03_1"
        },
        voice_ch_char_Baonu_vo_topic_03_2 = {
          ContentEN = "Right!? But because of this title, they're always telling me to \"swallow my anger with patience.\" But it's like... like being forced to stop mid-yawn or raising your sword for a perfect strike, only to be told, \"Hey! That's not an enemy, it's a friend!\" It just makes you even more—",
          TextMapId = "voice_ch_char_Baonu_vo_topic_03_2"
        },
        voice_ch_char_Baonu_vo_topic_03_3 = {
          ContentEN = "Argh, they say anger is a grave sin. I mustn't get angry. I mustn't...",
          TextMapId = "voice_ch_char_Baonu_vo_topic_03_3"
        },
        voice_ch_char_Baonu_vo_topic_03_4 = {
          ContentEN = "Well... it comes with the job! I am Lord Patience, after all! Hehe!",
          TextMapId = "voice_ch_char_Baonu_vo_topic_03_4"
        },
        voice_ch_char_Baonu_vo_topic_04_1 = {
          ContentEN = "The \"Seven Virtues\" are the most noble, most powerful, and most drop-dead dazzling champions in all of Elysium! Naturally, they're also the most virtuous — it's in the name!",
          TextMapId = "voice_ch_char_Baonu_vo_topic_04_1"
        },
        voice_ch_char_Baonu_vo_topic_04_2 = {
          ContentEN = "What's with that look...? How dare you doubt me! I hereby sentence you to copy the Codex thirty — no, a hundred times!",
          TextMapId = "voice_ch_char_Baonu_vo_topic_04_2"
        },
        voice_ch_char_Baonu_vo_victory = {
          ContentEN = "That was all thanks to me, Mistress Patience!",
          TextMapId = "voice_ch_char_Baonu_vo_victory"
        },
        voice_ch_char_Baonu_vo_welcome = {
          ContentEN = "Hey! I'm taking Samael out for some fresh air — soaking up the sunlight, getting a feel for this place together. Wanna say hi? It'll be thrilled! ...Well, probably! Hehe~",
          TextMapId = "voice_ch_char_Baonu_vo_welcome"
        },
        voice_ch_char_Dafu_vo_appear = {
          ContentEN = "Emergency supplies are packed. Ready to deploy at any time.",
          TextMapId = "voice_ch_char_Dafu_vo_appear"
        },
        voice_ch_char_Dafu_vo_battleidle = {
          ContentEN = "While the tide of battle shifts quickly, I trust your judgment.",
          TextMapId = "voice_ch_char_Dafu_vo_battleidle"
        },
        voice_ch_char_Dafu_vo_battlestart = {
          ContentEN = "This time, we'll make it back safely, just like always.",
          TextMapId = "voice_ch_char_Dafu_vo_battlestart"
        },
        voice_ch_char_Dafu_vo_be_hit_heavy_r01 = {
          ContentEN = "Watch out!",
          TextMapId = "voice_ch_char_Dafu_vo_be_hit_heavy_r01"
        },
        voice_ch_char_Dafu_vo_be_hit_heavy_r02 = {
          ContentEN = "Hang in there...",
          TextMapId = "voice_ch_char_Dafu_vo_be_hit_heavy_r02"
        },
        voice_ch_char_Dafu_vo_birthday = {
          ContentEN = "Do you know what makes today so special? That's right — it's your birthday.\nI know that as we grow older, life pulls us in all directions. We're always chasing after goals, juggling responsibilities, and rushing from one place to the next. It might sound a bit childish, but I truly believe birthdays should be different. For just one day, we deserve to let go of those burdens — to be carefree children again, basking in the love and warm wishes of those who care about us. So today, set your worries aside. Be a happy kid — enjoy the cake, blow out the candles, and make a wish...\nAnd if you're alone right now, let me take on the role of the \"grown-up\" for you.\nHappy birthday.",
          TextMapId = "voice_ch_char_Dafu_vo_birthday"
        },
        voice_ch_char_Dafu_vo_companio_01 = {
          ContentEN = "I once read medical texts from Huaxu in the capital's library. While their theories differ from those of Hyperborea's medical traditions, they've proven remarkably effective in treatment. There are still parts I don't fully understand — would you mind helping me with them?",
          TextMapId = "voice_ch_char_Dafu_vo_companio_01"
        },
        voice_ch_char_Dafu_vo_companio_02 = {
          ContentEN = "Madam Warden, I wonder — does justice that arrives late still deserve to be called justice?",
          TextMapId = "voice_ch_char_Dafu_vo_companio_02"
        },
        voice_ch_char_Dafu_vo_companio_03 = {
          ContentEN = "It's been so long. Since I left the Spathatoi, we've barely spoken. How... have you been?",
          TextMapId = "voice_ch_char_Dafu_vo_companio_03"
        },
        voice_ch_char_Dafu_vo_companio_04 = {
          ContentEN = "Even though I've left the Spathatoi, it remains a place that shaped me. I know forgiveness might be too much to hope for, but I still want to say — I'm sorry.",
          TextMapId = "voice_ch_char_Dafu_vo_companio_04"
        },
        voice_ch_char_Dafu_vo_die_r01 = {
          ContentEN = "I'm a medic... I can't...",
          TextMapId = "voice_ch_char_Dafu_vo_die_r01"
        },
        voice_ch_char_Dafu_vo_die_r02 = {
          ContentEN = "Don't stop for me... Fight on...",
          TextMapId = "voice_ch_char_Dafu_vo_die_r02"
        },
        voice_ch_char_Dafu_vo_fail = {
          ContentEN = "I'll cover you all.",
          TextMapId = "voice_ch_char_Dafu_vo_fail"
        },
        voice_ch_char_Dafu_vo_gain = {
          ContentEN = "I am Daphne Theodore, a medic with the Griffins under Hyperborea's 13th Legion. The battlefield is fraught with peril, but rest assured — I'll always be here to provide aid.",
          TextMapId = "voice_ch_char_Dafu_vo_gain"
        },
        voice_ch_char_Dafu_vo_idle = {
          ContentEN = "Moments like these are rare — no cries for help, no urgent reports. Hmm... Perhaps I'll make some coffee and finally finish that novel. Whom does the princess end up with, I wonder?",
          TextMapId = "voice_ch_char_Dafu_vo_idle"
        },
        voice_ch_char_Dafu_vo_lvup = {
          ContentEN = "With this, I'll be able to ease more of their pain.",
          TextMapId = "voice_ch_char_Dafu_vo_lvup"
        },
        voice_ch_char_Dafu_vo_revive = {
          ContentEN = "I promised — we'll make it back together, safe and sound.",
          TextMapId = "voice_ch_char_Dafu_vo_revive"
        },
        voice_ch_char_Dafu_vo_skill01_r01 = {
          ContentEN = "Anesthesia and debridement ready.",
          TextMapId = "voice_ch_char_Dafu_vo_skill01_r01"
        },
        voice_ch_char_Dafu_vo_skill01_r02 = {
          ContentEN = "Tourniquet for hemorrhage!",
          TextMapId = "voice_ch_char_Dafu_vo_skill01_r02"
        },
        voice_ch_char_Dafu_vo_skill02_r01 = {
          ContentEN = "How much longer must the flames of war demand our blood?",
          TextMapId = "voice_ch_char_Dafu_vo_skill02_r01"
        },
        voice_ch_char_Dafu_vo_skill02_r02 = {
          ContentEN = "I will maintain the utmost respect for human life.",
          TextMapId = "voice_ch_char_Dafu_vo_skill02_r02"
        },
        voice_ch_char_Dafu_vo_skill02_r03 = {
          ContentEN = "For the peace that will come one day.",
          TextMapId = "voice_ch_char_Dafu_vo_skill02_r03"
        },
        voice_ch_char_Dafu_vo_topic_01_1 = {
          ContentEN = "I... don't think I have any particular hobbies. Reading, maybe, if that counts.",
          TextMapId = "voice_ch_char_Dafu_vo_topic_01_1"
        },
        voice_ch_char_Dafu_vo_topic_01_2 = {
          ContentEN = "My mother always says staying home with my books and skipping all those balls and salons will cost me countless opportunities to climb the social ladder...",
          TextMapId = "voice_ch_char_Dafu_vo_topic_01_2"
        },
        voice_ch_char_Dafu_vo_topic_01_3 = {
          ContentEN = "But honestly, I prefer it this way.",
          TextMapId = "voice_ch_char_Dafu_vo_topic_01_3"
        },
        voice_ch_char_Dafu_vo_topic_01_4 = {
          ContentEN = "Mostly books on battlefield medicine — Emergency Field Aid Manual, Practical Guide to Trauma Care, How to Set Up a Temporary Field Hospital...",
          TextMapId = "voice_ch_char_Dafu_vo_topic_01_4"
        },
        voice_ch_char_Dafu_vo_topic_01_5 = {
          ContentEN = "You may know that my previous studies never focused on first aid, so even with my medic qualifications, I still feel out of my depth sometimes.",
          TextMapId = "voice_ch_char_Dafu_vo_topic_01_5"
        },
        voice_ch_char_Dafu_vo_topic_01_6 = {
          ContentEN = "I know, which is why I've been reading... Glass Heels. It's about a—a princess and a knight... Not that I'm into romantic novels or anything! I just... happened to flip through it, that's all...",
          TextMapId = "voice_ch_char_Dafu_vo_topic_01_6"
        },
        voice_ch_char_Dafu_vo_topic_02_1 = {
          ContentEN = "Certainly! Alchemy is the cornerstone of Hyperborea — scholars call it the \"primordial miracle.\"",
          TextMapId = "voice_ch_char_Dafu_vo_topic_02_1"
        },
        voice_ch_char_Dafu_vo_topic_02_2 = {
          ContentEN = "At first, its purpose was simple: to extract gold from Phoxene. But over time, we discovered this tiny crystal could do so much more — power machinery, generate electricity... It's Solarian magic.",
          TextMapId = "voice_ch_char_Dafu_vo_topic_02_2"
        },
        voice_ch_char_Dafu_vo_topic_02_3 = {
          ContentEN = "...But then, the Academy...",
          TextMapId = "voice_ch_char_Dafu_vo_topic_02_3"
        },
        voice_ch_char_Dafu_vo_topic_02_4 = {
          ContentEN = "...Yes, in the Spathatoi. But that chapter of my life is over now.",
          TextMapId = "voice_ch_char_Dafu_vo_topic_02_4"
        },
        voice_ch_char_Dafu_vo_topic_02_5 = {
          ContentEN = "I left because the Spathatoi lost its way. What began as a pursuit of knowledge turned into something darker. It's become the blazing core of Hyperborea's war machine, but its fuel brings suffering and misfortune to its people.",
          TextMapId = "voice_ch_char_Dafu_vo_topic_02_5"
        },
        voice_ch_char_Dafu_vo_topic_02_6 = {
          ContentEN = "I suppose... I wasn't as strong as I thought. I couldn't reconcile with what it had become, and I lacked the courage or strength to change it. So, I did the only thing I could — I walked away.",
          TextMapId = "voice_ch_char_Dafu_vo_topic_02_6"
        },
        voice_ch_char_Dafu_vo_topic_03_1 = {
          ContentEN = "Some emergency tools and supplies — bandages, antiseptics, anesthetics, and the basic tools for wound care like surgical blades and sutures.",
          TextMapId = "voice_ch_char_Dafu_vo_topic_03_1"
        },
        voice_ch_char_Dafu_vo_topic_03_2 = {
          ContentEN = "I also keep a handkerchief and a comb in it.",
          TextMapId = "voice_ch_char_Dafu_vo_topic_03_2"
        },
        voice_ch_char_Dafu_vo_topic_03_3 = {
          ContentEN = "Oh, it's not what you think... They're not for me — they're for my patients. I use them to help those who don't make it... tidy up a bit.",
          TextMapId = "voice_ch_char_Dafu_vo_topic_03_3"
        },
        voice_ch_char_Dafu_vo_topic_03_4 = {
          ContentEN = "The cruelty of death robs people of more than just their lives — it strips them of their dignity.",
          TextMapId = "voice_ch_char_Dafu_vo_topic_03_4"
        },
        voice_ch_char_Dafu_vo_topic_03_5 = {
          ContentEN = "I just want... when their families come to say their final goodbyes, for them to see their loved ones at peace, as though they're merely asleep. After being apart for so long, no parent should have to see their child's face twisted in pain...",
          TextMapId = "voice_ch_char_Dafu_vo_topic_03_5"
        },
        voice_ch_char_Dafu_vo_topic_04_1 = {
          ContentEN = "Oh, it's fine! I can handle it... Well, maybe just a little tough sometimes. The emergency care and nursing lessons aren't too bad, but the physical fitness tests... those are a real struggle for me.",
          TextMapId = "voice_ch_char_Dafu_vo_topic_04_1"
        },
        voice_ch_char_Dafu_vo_topic_04_2 = {
          ContentEN = "Even though I get up earlier than everyone else for extra training, I still only manage to scrape by with passing scores... Please don't make fun of me! Building stamina is so much harder than studying.",
          TextMapId = "voice_ch_char_Dafu_vo_topic_04_2"
        },
        voice_ch_char_Dafu_vo_topic_04_3 = {
          ContentEN = "It is. But when I take my mind off my tired legs and look up, I see the wheat fields stretching beyond the city and the cottages on the horizon, and hear the windmills creaking and the herdsmen whistling. It always helps me feel so much better.",
          TextMapId = "voice_ch_char_Dafu_vo_topic_04_3"
        },
        voice_ch_char_Dafu_vo_topic_04_4 = {
          ContentEN = "Because... running along that road feels like my way of protecting these simple, precious things from being taken away.",
          TextMapId = "voice_ch_char_Dafu_vo_topic_04_4"
        },
        voice_ch_char_Dafu_vo_topic_05_1 = {
          ContentEN = "...The last time I spoke with my father was over the radio. It was on the battlefield of Lonza Fortress, and despite the danger, he told me, \"Don't worry, I'll be fine.\"",
          TextMapId = "voice_ch_char_Dafu_vo_topic_05_1"
        },
        voice_ch_char_Dafu_vo_topic_05_2 = {
          ContentEN = "After everything that happened, I'd often turn on my radio in the dead of night, tune to his channel, and press the call button, hoping to hear his voice again...",
          TextMapId = "voice_ch_char_Dafu_vo_topic_05_2"
        },
        voice_ch_char_Dafu_vo_topic_05_3 = {
          ContentEN = "It wasn't until I sat there in silence for what felt like an eternity that I realized... he was never coming back.",
          TextMapId = "voice_ch_char_Dafu_vo_topic_05_3"
        },
        voice_ch_char_Dafu_vo_topic_05_4 = {
          ContentEN = "Thank you. Don't worry, I'll stay strong and keep pushing on. Until I clear my father's name and honour the wronged who fell in the Lonza battle, I won't stop.",
          TextMapId = "voice_ch_char_Dafu_vo_topic_05_4"
        },
        voice_ch_char_Dafu_vo_victory = {
          ContentEN = "How I wish this could be the last battle...",
          TextMapId = "voice_ch_char_Dafu_vo_victory"
        },
        voice_ch_char_Dafu_vo_welcome = {
          ContentEN = "It's delightful to see you safe and well today. Take care... The peace we all long for will surely arrive someday.",
          TextMapId = "voice_ch_char_Dafu_vo_welcome"
        },
        voice_ch_char_Feina_vo_appear = {
          ContentEN = "Are you taking me out to play? Pinky promise, no backsies!",
          TextMapId = "voice_ch_char_Feina_vo_appear"
        },
        voice_ch_char_Feina_vo_battleidle = {
          ContentEN = "Where did everyone... go?",
          TextMapId = "voice_ch_char_Feina_vo_battleidle"
        },
        voice_ch_char_Feina_vo_battlestart = {
          ContentEN = "What a huge garden!",
          TextMapId = "voice_ch_char_Feina_vo_battlestart"
        },
        voice_ch_char_Feina_vo_be_hit_heavy_r02 = {
          ContentEN = "I'm not scared!",
          TextMapId = "voice_ch_char_Feina_vo_be_hit_heavy_r02"
        },
        voice_ch_char_Feina_vo_be_hit_r02 = {
          ContentEN = "Don't touch me!",
          TextMapId = "voice_ch_char_Feina_vo_be_hit_r02"
        },
        voice_ch_char_Feina_vo_birthday = {
          ContentEN = "On the day of {性别:his|her} birthday, {性别:Mr|Miss} White Unicorn returned to {性别:his|her} cosy little home. The pure white bird brought cinnamon leaves; the magician chanted spells that brought laughter; and the brave knight stood faithfully by {性别:his|her} side, just like before. Flames danced merrily in the stove, while snowflakes delivered distant blessings from the sky. The little home brimmed with great happiness...",
          TextMapId = "voice_ch_char_Feina_vo_birthday"
        },
        voice_ch_char_Feina_vo_companio_01 = {
          ContentEN = "Promise me that you'll never, ever, ever... go to that scary place with lots and lots of bad sorcerers, okay?",
          TextMapId = "voice_ch_char_Feina_vo_companio_01"
        },
        voice_ch_char_Feina_vo_companio_02 = {
          ContentEN = "What's that? Is it your elf pet, Miss Hamster? Wow, unbelievable... It must be able to carry you as it flies over the walls of castles.",
          TextMapId = "voice_ch_char_Feina_vo_companio_02"
        },
        voice_ch_char_Feina_vo_companio_03 = {
          ContentEN = "Miss Lioness, are you trying to wake up the fairy inside the giant sword? Perhaps you need to chant a lot of incantations, like, \"O chosen one who awoke the sacred greatsword Samael, destined to be the king of Elysium!\"",
          TextMapId = "voice_ch_char_Feina_vo_companio_03"
        },
        voice_ch_char_Feina_vo_companio_04 = {
          ContentEN = "Mr Seahorse from the southern realm, you look familiar. Hmm... Oh! A long, long time ago, Papa hung a portrait of you on our wall at home.",
          TextMapId = "voice_ch_char_Feina_vo_companio_04"
        },
        voice_ch_char_Feina_vo_die_r01 = {
          ContentEN = "Time for me to go to that faraway land...",
          TextMapId = "voice_ch_char_Feina_vo_die_r01"
        },
        voice_ch_char_Feina_vo_die_r02 = {
          ContentEN = "It's like I've had a very long dream...",
          TextMapId = "voice_ch_char_Feina_vo_die_r02"
        },
        voice_ch_char_Feina_vo_fail = {
          ContentEN = "I don't like this ending at all...",
          TextMapId = "voice_ch_char_Feina_vo_fail"
        },
        voice_ch_char_Feina_vo_gain = {
          ContentEN = "\"Chirp, chirp!\" said the little nightingale. It means — \"Hello there, {性别:Mr|Miss} White Unicorn! From now on, you and Fina are going to be good friends!\"",
          TextMapId = "voice_ch_char_Feina_vo_gain"
        },
        voice_ch_char_Feina_vo_idle = {
          ContentEN = "♪ What a tiny, tiny, little home... It rests in and hides in the treetops; and the magical golden river flow... Do you see that stove? The embers crackle, crackle... Papa making a toy shining so bright, and Mama humming a lullaby... Good night~",
          TextMapId = "voice_ch_char_Feina_vo_idle"
        },
        voice_ch_char_Feina_vo_lvup = {
          ContentEN = "Wow...!",
          TextMapId = "voice_ch_char_Feina_vo_lvup"
        },
        voice_ch_char_Feina_vo_revive = {
          ContentEN = "Huh...? What happened?",
          TextMapId = "voice_ch_char_Feina_vo_revive"
        },
        voice_ch_char_Feina_vo_skill01_r01 = {
          ContentEN = "♪ Starlight, shining bright~",
          TextMapId = "voice_ch_char_Feina_vo_skill01_r01"
        }
      }
    end
  },
  {
    MinKey = "voice_ch_char_Feina_vo_skill01_r02",
    MaxKey = "voice_ch_char_Kezhou_vo_skill01_r02",
    Loader = function()
      return {
        voice_ch_char_Feina_vo_skill01_r02 = {
          ContentEN = "♪ My pretty pretty garden~",
          TextMapId = "voice_ch_char_Feina_vo_skill01_r02"
        },
        voice_ch_char_Feina_vo_skill02_r01 = {
          ContentEN = "O friends, come and protect everyone!",
          TextMapId = "voice_ch_char_Feina_vo_skill02_r01"
        },
        voice_ch_char_Feina_vo_skill02_r02 = {
          ContentEN = "No brawls in the garden!",
          TextMapId = "voice_ch_char_Feina_vo_skill02_r02"
        },
        voice_ch_char_Feina_vo_skill02_r03 = {
          ContentEN = "Be careful, my valiant soldiers!",
          TextMapId = "voice_ch_char_Feina_vo_skill02_r03"
        },
        voice_ch_char_Feina_vo_topic_01_1 = {
          ContentEN = "Um, I was wondering... if there were a candy that could make me grow very tall...",
          TextMapId = "voice_ch_char_Feina_vo_topic_01_1"
        },
        voice_ch_char_Feina_vo_topic_01_2 = {
          ContentEN = "So tall that I could see above the clouds and even touch the stars!",
          TextMapId = "voice_ch_char_Feina_vo_topic_01_2"
        },
        voice_ch_char_Feina_vo_topic_01_3 = {
          ContentEN = "I'd walk carefully, I promise! Well... if you're really worried, you could perch on my hand and we'll go for a spin. What do you think?",
          TextMapId = "voice_ch_char_Feina_vo_topic_01_3"
        },
        voice_ch_char_Feina_vo_topic_02_1 = {
          ContentEN = "I have a big glass chest filled with the soft snow from outside my window and marshmallows as white as the snow. I'd also like to put in clouds as fluffy as those marshmallows, and breezes as warm as those clouds...",
          TextMapId = "voice_ch_char_Feina_vo_topic_02_1"
        },
        voice_ch_char_Feina_vo_topic_02_2 = {
          ContentEN = "And our giggles and chuckles in there too, every single one~",
          TextMapId = "voice_ch_char_Feina_vo_topic_02_2"
        },
        voice_ch_char_Feina_vo_topic_02_3 = {
          ContentEN = "Well... if you nibble one of those candies that shrinks you down tiny, you could get in for a visit. But everything's white in there, so be careful not to wander off and lose your way.",
          TextMapId = "voice_ch_char_Feina_vo_topic_02_3"
        },
        voice_ch_char_Feina_vo_topic_02_4 = {
          ContentEN = "Mmm... If you get lost, I'll scatter breadcrumbs in a trail for you... Follow them and you'll find the way out!",
          TextMapId = "voice_ch_char_Feina_vo_topic_02_4"
        },
        voice_ch_char_Feina_vo_topic_03_1 = {
          ContentEN = "Mm-hmm! I dreamed of a nightingale, pure as driven snow, resting on my hand one moment, and playing hide-and-seek with me the next... Hmm, was it me who dreamed, or did it dream of me, I wonder?",
          TextMapId = "voice_ch_char_Feina_vo_topic_03_1"
        },
        voice_ch_char_Feina_vo_topic_03_2 = {
          ContentEN = "You might be right! Maybe it's a wonderland where all the sleeping children and little animals can play together. Hmm... I wonder who I'll meet in my next dream — Owl the Wise, Miss Canary, or Sir Rabbit?",
          TextMapId = "voice_ch_char_Feina_vo_topic_03_2"
        },
        voice_ch_char_Feina_vo_topic_04_1 = {
          ContentEN = "I used to have a mum and two dads. But they've all gone...",
          TextMapId = "voice_ch_char_Feina_vo_topic_04_1"
        },
        voice_ch_char_Feina_vo_topic_04_2 = {
          ContentEN = "The first dad went to a faraway land with mum. And the second one... he's in that faraway land too... I sent him there.",
          TextMapId = "voice_ch_char_Feina_vo_topic_04_2"
        },
        voice_ch_char_Feina_vo_topic_05_1 = {
          ContentEN = "He's the greatest magician, with the most soothing voice and the gentlest soul in the world...",
          TextMapId = "voice_ch_char_Feina_vo_topic_05_1"
        },
        voice_ch_char_Feina_vo_topic_05_2 = {
          ContentEN = "Er, what's wrong? You look very confused.",
          TextMapId = "voice_ch_char_Feina_vo_topic_05_2"
        },
        voice_ch_char_Feina_vo_topic_05_3 = {
          ContentEN = "Huh...? You mean he's not kind or gentle to you? I'm so sorry... I'll give him a little tap on his head and ask him to be nicer!",
          TextMapId = "voice_ch_char_Feina_vo_topic_05_3"
        },
        voice_ch_char_Feina_vo_victory = {
          ContentEN = "\"And they lived happily ever after.\" Now, sleep tight. Have a sweet dream.",
          TextMapId = "voice_ch_char_Feina_vo_victory"
        },
        voice_ch_char_Feina_vo_welcome = {
          ContentEN = "...Ah, it's you. Hello, how are you?",
          TextMapId = "voice_ch_char_Feina_vo_welcome"
        },
        voice_ch_char_Fuluo01_vo_appear = {
          ContentEN = "If God's radiance fails to pierce the endless night, then I shall take up the scales in its stead.",
          TextMapId = "voice_ch_char_Fuluo01_vo_appear"
        },
        voice_ch_char_Fuluo01_vo_battlestart = {
          ContentEN = "Fear not the darkness, for I shall kindle the stars.",
          TextMapId = "voice_ch_char_Fuluo01_vo_battlestart"
        },
        voice_ch_char_Fuluo01_vo_gain = {
          ContentEN = "I shall purge this tainted land and judge the wicked. I shall usher in the dawn and grant mercy to the innocent. My companion, bear witness to it all.",
          TextMapId = "voice_ch_char_Fuluo01_vo_gain"
        },
        voice_ch_char_Fuluo01_vo_skill02_r01 = {
          ContentEN = "Beyond forgiveness.",
          TextMapId = "voice_ch_char_Fuluo01_vo_skill02_r01"
        },
        voice_ch_char_Fuluo01_vo_skill02_r02 = {
          ContentEN = "Blazing daylight, cleanse the ground I walk upon!",
          TextMapId = "voice_ch_char_Fuluo01_vo_skill02_r02"
        },
        voice_ch_char_Fuluo01_vo_skill02_r03 = {
          ContentEN = "Everlasting peace.",
          TextMapId = "voice_ch_char_Fuluo01_vo_skill02_r03"
        },
        voice_ch_char_Fuluo_vo_appear = {
          ContentEN = "There is no other course. I must see to everything myself.",
          TextMapId = "voice_ch_char_Fuluo_vo_appear"
        },
        voice_ch_char_Fuluo_vo_battleidle = {
          ContentEN = "Come. We have no time to squander.",
          TextMapId = "voice_ch_char_Fuluo_vo_battleidle"
        },
        voice_ch_char_Fuluo_vo_battlestart = {
          ContentEN = "Once I embark on this path, there will be no turning back.",
          TextMapId = "voice_ch_char_Fuluo_vo_battlestart"
        },
        voice_ch_char_Fuluo_vo_be_hit_heavy_r01 = {
          ContentEN = "Insolent wretch!",
          TextMapId = "voice_ch_char_Fuluo_vo_be_hit_heavy_r01"
        },
        voice_ch_char_Fuluo_vo_be_hit_r01 = {
          ContentEN = "How uncivilized!",
          TextMapId = "voice_ch_char_Fuluo_vo_be_hit_r01"
        },
        voice_ch_char_Fuluo_vo_birthday = {
          ContentEN = "Do you remember that station, Flodia Bloomfield? It was built on the day of my birth. Father named it after me, a token of that day. Heh... if, I mean, we would ever live to witness a different future, I hope one day to rename that station for you. After all, it was there we first met... and there I was given a different life.",
          TextMapId = "voice_ch_char_Fuluo_vo_birthday"
        },
        voice_ch_char_Fuluo_vo_companio_01 = {
          ContentEN = "Hilda, it offers me great comfort to know that you're by my side. Please... just stay a while longer.",
          TextMapId = "voice_ch_char_Fuluo_vo_companio_01"
        },
        voice_ch_char_Fuluo_vo_companio_02 = {
          ContentEN = "I know we're the same. There's no need to deny it. I can perceive the blazing fire within you. No matter how hard you try to hide it, I know it's there. The flame of anger that's never extinguished, burning deep inside you.",
          TextMapId = "voice_ch_char_Fuluo_vo_companio_02"
        },
        voice_ch_char_Fuluo_vo_companio_03 = {
          ContentEN = "What a disappointment... Once a lone wolf rescued by his hand, now reduced to a cringing hound, begging mercy at his betrayer's feet.",
          TextMapId = "voice_ch_char_Fuluo_vo_companio_03"
        },
        voice_ch_char_Fuluo_vo_die_r01 = {
          ContentEN = "I... still cannot...",
          TextMapId = "voice_ch_char_Fuluo_vo_die_r01"
        },
        voice_ch_char_Fuluo_vo_die_r02 = {
          ContentEN = "Are you coming... to take me home...?",
          TextMapId = "voice_ch_char_Fuluo_vo_die_r02"
        },
        voice_ch_char_Fuluo_vo_fail = {
          ContentEN = "This humiliation shall not be forgotten.",
          TextMapId = "voice_ch_char_Fuluo_vo_fail"
        },
        voice_ch_char_Fuluo_vo_gain_01 = {
          ContentEN = "I'm Flora. It seems we share much in common: unspoken secrets, and a heart drifting without anchor. I trust we now understand each other well enough.",
          TextMapId = "voice_ch_char_Fuluo_vo_gain_01"
        },
        voice_ch_char_Fuluo_vo_gain_02 = {
          ContentEN = "You have returned... you kept faith with our vow. ",
          TextMapId = "voice_ch_char_Fuluo_vo_gain_02"
        },
        voice_ch_char_Fuluo_vo_idle = {
          ContentEN = "\"The evening bell urges daylight toward the horizon. Weary travellers, led by the evening star, make their way home. Now, this world belongs to the night, and to me.\"",
          TextMapId = "voice_ch_char_Fuluo_vo_idle"
        },
        voice_ch_char_Fuluo_vo_lvup = {
          ContentEN = "It is the necessary path.",
          TextMapId = "voice_ch_char_Fuluo_vo_lvup"
        },
        voice_ch_char_Fuluo_vo_revive = {
          ContentEN = "I shall not fall until they pay the price.",
          TextMapId = "voice_ch_char_Fuluo_vo_revive"
        },
        voice_ch_char_Fuluo_vo_skill01_r01 = {
          ContentEN = "The dusk has arrived.",
          TextMapId = "voice_ch_char_Fuluo_vo_skill01_r01"
        },
        voice_ch_char_Fuluo_vo_skill01_r02 = {
          ContentEN = "I shall hesitate no longer.",
          TextMapId = "voice_ch_char_Fuluo_vo_skill01_r02"
        },
        voice_ch_char_Fuluo_vo_skill02_r01 = {
          ContentEN = "For the future I have yet to behold.",
          TextMapId = "voice_ch_char_Fuluo_vo_skill02_r01"
        },
        voice_ch_char_Fuluo_vo_skill02_r02 = {
          ContentEN = "For the grief that was never spoken.",
          TextMapId = "voice_ch_char_Fuluo_vo_skill02_r02"
        },
        voice_ch_char_Fuluo_vo_skill02_r03 = {
          ContentEN = "Let my wrath be the last thing you feel.",
          TextMapId = "voice_ch_char_Fuluo_vo_skill02_r03"
        },
        voice_ch_char_Fuluo_vo_topic_01_1 = {
          ContentEN = "Most do. Since childhood, the spine is trained to hold itself straight, yet never rigid, like a string; and a skirt must learn to turn slowly, like petals slowly coming into bloom.",
          TextMapId = "voice_ch_char_Fuluo_vo_topic_01_1"
        },
        voice_ch_char_Fuluo_vo_topic_01_2 = {
          ContentEN = "Joy and sorrow alike must be worn with restraint. One must neither grow indifferent nor lose composure. A smile, a tear — even the faintest curve of the lips — should carry the weight of measured grace.",
          TextMapId = "voice_ch_char_Fuluo_vo_topic_01_2"
        },
        voice_ch_char_Fuluo_vo_topic_01_3 = {
          ContentEN = "Heh... Every noblewoman has, at some point, lamented such tedious formalities to her maid. Only to be reminded that society is her battlefield — and the smallest lapse may stain her family's name.",
          TextMapId = "voice_ch_char_Fuluo_vo_topic_01_3"
        },
        voice_ch_char_Fuluo_vo_topic_01_4 = {
          ContentEN = "For the nobility, such courtesies are but the form of dignity. The newly wealthy, however, cling to the form desperately, hoping imitation alone might grant them nobility.",
          TextMapId = "voice_ch_char_Fuluo_vo_topic_01_4"
        },
        voice_ch_char_Fuluo_vo_topic_01_5 = {
          ContentEN = "It is not courtesy they value, but distinction — the careful line that sets them apart from the common folk. If one day, the emperor were to take delight in the sounds of the sty, then all the people in Dismania shall praise such sounds as the most beautiful.",
          TextMapId = "voice_ch_char_Fuluo_vo_topic_01_5"
        },
        voice_ch_char_Fuluo_vo_topic_02_1 = {
          ContentEN = "Dismania... The city encased in irony walls, the precious Phoxene yet the decaying root of Hyperborea... my so-called homeland.",
          TextMapId = "voice_ch_char_Fuluo_vo_topic_02_1"
        },
        voice_ch_char_Fuluo_vo_topic_02_2 = {
          ContentEN = "Many long for their hometowns. As for me... it was merely a place I spent years trying to escape.",
          TextMapId = "voice_ch_char_Fuluo_vo_topic_02_2"
        },
        voice_ch_char_Fuluo_vo_topic_02_3 = {
          ContentEN = "But I know the day will come when I walk those streets again. Not as the exile, but as the one who returns in triumph.",
          TextMapId = "voice_ch_char_Fuluo_vo_topic_02_3"
        },
        voice_ch_char_Fuluo_vo_topic_03_1 = {
          ContentEN = "Indeed. My mother chose it. She wished: \"Let the blossoms of spring remain unending, and the golden hours stay forever warm.\" A beautiful wish... one I have failed to fulfill.",
          TextMapId = "voice_ch_char_Fuluo_vo_topic_03_1"
        },
        voice_ch_char_Fuluo_vo_topic_03_2 = {
          ContentEN = "Then your kindness brings me warmth. Thank you.",
          TextMapId = "voice_ch_char_Fuluo_vo_topic_03_2"
        },
        voice_ch_char_Fuluo_vo_topic_04_1 = {
          ContentEN = "Why ask? It is but a dreary tale, long stretches of loneliness, and little else.",
          TextMapId = "voice_ch_char_Fuluo_vo_topic_04_1"
        },
        voice_ch_char_Fuluo_vo_topic_04_2 = {
          ContentEN = [[
That is true, at least by day. But... I wonder whether you can truly understand it.
To be surrounded at all hours, hands kissed, blessings murmured with reverence, and conversations of poetry, of plays, of the flowers in the garden...]],
          TextMapId = "voice_ch_char_Fuluo_vo_topic_04_2"
        },
        voice_ch_char_Fuluo_vo_topic_04_3 = {
          ContentEN = "Yet whenever I sought conversation beyond courtesy, they would lower their heads and claim they dared not overstep.",
          TextMapId = "voice_ch_char_Fuluo_vo_topic_04_3"
        },
        voice_ch_char_Fuluo_vo_topic_04_4 = {
          ContentEN = "Later, I came to understand. As the daughter of the late Emperor, any intimacy beyond propriety might place them at risks.",
          TextMapId = "voice_ch_char_Fuluo_vo_topic_04_4"
        },
        voice_ch_char_Fuluo_vo_topic_04_5 = {
          ContentEN = "At night, I would return to that high tower. Only the moon kept me company. Two solitary souls, adrift in the silence of darkness. For the most part, I simply watched it flowing slowly toward the far edge of the sky.",
          TextMapId = "voice_ch_char_Fuluo_vo_topic_04_5"
        },
        voice_ch_char_Fuluo_vo_topic_04_6 = {
          ContentEN = "I still remember that night at Icelake Station. I was gazing at the moon when you told me you would help me reclaim my freedom.",
          TextMapId = "voice_ch_char_Fuluo_vo_topic_04_6"
        },
        voice_ch_char_Fuluo_vo_topic_04_7 = {
          ContentEN = "In that moment, I knew a different future had begun, and the dark would never again feel so vast.",
          TextMapId = "voice_ch_char_Fuluo_vo_topic_04_7"
        },
        voice_ch_char_Fuluo_vo_topic_05_1 = {
          ContentEN = "She was sent to attend me. We share no blood. But... she felt closer to me than the Emperor ever did. In truth, Hilda was the one who felt like family.",
          TextMapId = "voice_ch_char_Fuluo_vo_topic_05_1"
        },
        voice_ch_char_Fuluo_vo_topic_05_2 = {
          ContentEN = "She was already used to overstepping the bounds. In her eyes, I am neither \"Her Highness\" nor some claimant to the throne. I am merely Flora. And I... like this overstepping.",
          TextMapId = "voice_ch_char_Fuluo_vo_topic_05_2"
        },
        voice_ch_char_Fuluo_vo_victory = {
          ContentEN = "Father, mother... grant me the strength to see this through.",
          TextMapId = "voice_ch_char_Fuluo_vo_victory"
        },
        voice_ch_char_Fuluo_vo_welcome = {
          ContentEN = "Good day. You may kiss my hand, and let this day bring us peace and safety. ",
          TextMapId = "voice_ch_char_Fuluo_vo_welcome"
        },
        voice_ch_char_Haier_vo_appear = {
          ContentEN = "Where are the sinners?",
          TextMapId = "voice_ch_char_Haier_vo_appear"
        },
        voice_ch_char_Haier_vo_battleidle = {
          ContentEN = "Are you frightened? I thought you were tougher than the other sinners. How disappointing.",
          TextMapId = "voice_ch_char_Haier_vo_battleidle"
        },
        voice_ch_char_Haier_vo_battlestart = {
          ContentEN = "All sins shall be purged in flames!",
          TextMapId = "voice_ch_char_Haier_vo_battlestart"
        },
        voice_ch_char_Haier_vo_be_hit_heavy_r01 = {
          ContentEN = "You sinner!",
          TextMapId = "voice_ch_char_Haier_vo_be_hit_heavy_r01"
        },
        voice_ch_char_Haier_vo_be_hit_heavy_r02 = {
          ContentEN = "Stand strong!",
          TextMapId = "voice_ch_char_Haier_vo_be_hit_heavy_r02"
        },
        voice_ch_char_Haier_vo_birthday = {
          ContentEN = [[
Birthday? Hah! As if a warden would care about such trivialities.
Hah, does receiving blessings make you happy, you simple creature? Tsk, well, happy birthday then. I'll make a rare exception and drink with you, but just today.]],
          TextMapId = "voice_ch_char_Haier_vo_birthday"
        },
        voice_ch_char_Haier_vo_companio_01 = {
          ContentEN = "I'm the warden and you're the Legion's chief. Together, we're the merciless keepers of the dark order that is the Empire. Their hatred of us means nothing, as long as we serve Hyperborea!",
          TextMapId = "voice_ch_char_Haier_vo_companio_01"
        },
        voice_ch_char_Haier_vo_companio_02 = {
          ContentEN = "We meet again.",
          TextMapId = "voice_ch_char_Haier_vo_companio_02"
        },
        voice_ch_char_Haier_vo_companio_03 = {
          ContentEN = "Tsk, you're Sibylle's adjutant... the one who's always being accused of failing your duties, huh? I can tell that you're hiding your prowess and ambition just so you can stand alongside Sibylle. So what are your ulterior motives.",
          TextMapId = "voice_ch_char_Haier_vo_companio_03"
        },
        voice_ch_char_Haier_vo_die_r01 = {
          ContentEN = "For the order of the Empire...",
          TextMapId = "voice_ch_char_Haier_vo_die_r01"
        },
        voice_ch_char_Haier_vo_die_r02 = {
          ContentEN = "I'm not afraid of... hell...",
          TextMapId = "voice_ch_char_Haier_vo_die_r02"
        },
        voice_ch_char_Haier_vo_fail = {
          ContentEN = "I must wipe out this filth with my own hands!",
          TextMapId = "voice_ch_char_Haier_vo_fail"
        },
        voice_ch_char_Haier_vo_gain = {
          ContentEN = [[
Interesting. The criminal of the Empire has come to me of their own free will. Well then, prepare yourself for agony as I burn you to a crisp.
I am Hellfire, and I'll show you what hell is truly like!]],
          TextMapId = "voice_ch_char_Haier_vo_gain"
        },
        voice_ch_char_Haier_vo_idle = {
          ContentEN = "What a blissful sight... Aren't you afraid of my fire, insect? Hmph, you'll regret your ignorance when I stomp you into the dirt.",
          TextMapId = "voice_ch_char_Haier_vo_idle"
        },
        voice_ch_char_Haier_vo_lvup = {
          ContentEN = "Yes. My flame's burning fiercely now.",
          TextMapId = "voice_ch_char_Haier_vo_lvup"
        },
        voice_ch_char_Haier_vo_revive = {
          ContentEN = "This world has more sinners than hell.",
          TextMapId = "voice_ch_char_Haier_vo_revive"
        },
        voice_ch_char_Haier_vo_skill01_r01 = {
          ContentEN = "Burn!",
          TextMapId = "voice_ch_char_Haier_vo_skill01_r01"
        },
        voice_ch_char_Haier_vo_skill01_r02 = {
          ContentEN = "Embrace fear!",
          TextMapId = "voice_ch_char_Haier_vo_skill01_r02"
        },
        voice_ch_char_Haier_vo_skill02_r01 = {
          ContentEN = "Prepare for a fiery interrogation!",
          TextMapId = "voice_ch_char_Haier_vo_skill02_r01"
        },
        voice_ch_char_Haier_vo_skill02_r02 = {
          ContentEN = "No mercy!",
          TextMapId = "voice_ch_char_Haier_vo_skill02_r02"
        },
        voice_ch_char_Haier_vo_skill02_r03 = {
          ContentEN = "Count your sins!",
          TextMapId = "voice_ch_char_Haier_vo_skill02_r03"
        },
        voice_ch_char_Haier_vo_topic_01_1 = {
          ContentEN = "If you learned about history, you'd know that the first warden of the Royal Military Prison had skin like molten lava. Even the most ruthless criminals feared her interrogations.",
          TextMapId = "voice_ch_char_Haier_vo_topic_01_1"
        },
        voice_ch_char_Haier_vo_topic_01_2 = {
          ContentEN = "As her descendant, I proudly bear her name, ready to incinerate all sins with my fire.",
          TextMapId = "voice_ch_char_Haier_vo_topic_01_2"
        },
        voice_ch_char_Haier_vo_topic_01_3 = {
          ContentEN = "It does pose some challenges — I can only sleep on iron beds and can't linger in wooden structures for long. However, it allows me to pull criminals from burning buildings and administer justice. And the cold never bothers me.",
          TextMapId = "voice_ch_char_Haier_vo_topic_01_3"
        },
        voice_ch_char_Haier_vo_topic_01_4 = {
          ContentEN = "My unusual appearance is more of a gift. If there's any downside... I've always wanted to try ice cream, but it melts in my hand before I can taste it...",
          TextMapId = "voice_ch_char_Haier_vo_topic_01_4"
        },
        voice_ch_char_Haier_vo_topic_02_1 = {
          ContentEN = "Since the Empire's inception, my family has managed the prison that holds the most heinous criminals, correcting wrongs and neutralising threats.",
          TextMapId = "voice_ch_char_Haier_vo_topic_02_1"
        },
        voice_ch_char_Haier_vo_topic_02_2 = {
          ContentEN = "My fiery red skin, a legacy from the first warden, predestined me to continue enforcing the iron-clad code she established. So it wasn't me who chose to become a warden; it was the mantle of warden that chose me.",
          TextMapId = "voice_ch_char_Haier_vo_topic_02_2"
        },
        voice_ch_char_Haier_vo_topic_02_3 = {
          ContentEN = "Becoming a warden is merely the beginning. It compels me to remain vigilant, eradicating any injustice within the Empire until my final breath.",
          TextMapId = "voice_ch_char_Haier_vo_topic_02_3"
        },
        voice_ch_char_Haier_vo_topic_03_1 = {
          ContentEN = "Certainly. The Imperial Prison is teeming with devious criminals. My duties include conducting interrogations, reviewing case files, and thwarting escape attempts.",
          TextMapId = "voice_ch_char_Haier_vo_topic_03_1"
        },
        voice_ch_char_Haier_vo_topic_03_2 = {
          ContentEN = "Every minute of rest delays justice a bit, and when justice is delayed, chaos and the law of the jungle take over.",
          TextMapId = "voice_ch_char_Haier_vo_topic_03_2"
        },
        voice_ch_char_Haier_vo_topic_03_3 = {
          ContentEN = "Some scholars have envisioned a crime-free world. Should such a day come, my purpose would vanish, for evil necessitates a warden's existence. Until then, I am committed to upholding order.",
          TextMapId = "voice_ch_char_Haier_vo_topic_03_3"
        },
        voice_ch_char_Haier_vo_topic_04_1 = {
          ContentEN = "Justice? It is the restraint of desire through power, the suppression of evil through strength, and the punishment of the wicked by the mighty.",
          TextMapId = "voice_ch_char_Haier_vo_topic_04_1"
        },
        voice_ch_char_Haier_vo_topic_04_2 = {
          ContentEN = "Hmph, broad? I wouldn't expect a naive child to understand. We don't live in a utopia where people simply hold hands and love each other. Only through absolute power and order can true justice be secured!",
          TextMapId = "voice_ch_char_Haier_vo_topic_04_2"
        },
        voice_ch_char_Haier_vo_topic_05_1 = {
          ContentEN = "With criminals still roaming the streets of the Empire, spare time is a luxury for a warden. The only respite I get is when I sneak in a few strong drinks amidst a busy schedule.",
          TextMapId = "voice_ch_char_Haier_vo_topic_05_1"
        },
        voice_ch_char_Haier_vo_topic_05_2 = {
          ContentEN = "Why so surprised? It's merely a diversion. During interrogations, I always hear about various kinds of alcohol, which made me curious about this so-called wicked potion that seems to be associated with crime. So I drink once in a while.",
          TextMapId = "voice_ch_char_Haier_vo_topic_05_2"
        },
        voice_ch_char_Haier_vo_topic_05_3 = {
          ContentEN = "And the more I drink, the more I'm convinced that it's not the drink that is wicked.",
          TextMapId = "voice_ch_char_Haier_vo_topic_05_3"
        },
        voice_ch_char_Haier_vo_victory = {
          ContentEN = "Can't take any more? This is just the beginning!",
          TextMapId = "voice_ch_char_Haier_vo_victory"
        },
        voice_ch_char_Haier_vo_welcome = {
          ContentEN = "Ready for the interrogation?",
          TextMapId = "voice_ch_char_Haier_vo_welcome"
        },
        voice_ch_char_Heitao_vo_appear = {
          ContentEN = "Let's go.",
          TextMapId = "voice_ch_char_Heitao_vo_appear"
        },
        voice_ch_char_Heitao_vo_battleidle = {
          ContentEN = "Let's quickly get this over with and go home.",
          TextMapId = "voice_ch_char_Heitao_vo_battleidle"
        },
        voice_ch_char_Heitao_vo_battlestart = {
          ContentEN = "I'll go first.",
          TextMapId = "voice_ch_char_Heitao_vo_battlestart"
        },
        voice_ch_char_Heitao_vo_birthday = {
          ContentEN = "You've told me you want to have a birthday celebration like others have, so I made you a cake, I've heard people said a birthday without any cake is no birthday at all. May you be filled with joy whenever you hear the word \"birthday\" in the years to come.",
          TextMapId = "voice_ch_char_Heitao_vo_birthday"
        },
        voice_ch_char_Heitao_vo_companio_01 = {
          ContentEN = "All these years, I've taken good care of {性别:him|her} and of myself, just as I promised you... Could you pat my head and tell me I've done well, like you used to when I was little? And this time, please, don't leave us again...",
          TextMapId = "voice_ch_char_Heitao_vo_companio_01"
        },
        voice_ch_char_Heitao_vo_companio_02_1 = {
          ContentEN = "Miss Truffle, may I... pet your pig? Just one stroke will do. Please hold her still for me; I'm afraid she might run off... Little animals always seem to flee from me.",
          TextMapId = "voice_ch_char_Heitao_vo_companio_02_1"
        },
        voice_ch_char_Heitao_vo_companio_02_2 = {
          ContentEN = "Thank you... Ah, it's so warm and soft. How nice...",
          TextMapId = "voice_ch_char_Heitao_vo_companio_02_2"
        },
        voice_ch_char_Heitao_vo_companio_03 = {
          ContentEN = "I'm not that \"No.0\" from the Legion, nor am I your stooge. Leave, as I will never leave with you alive.",
          TextMapId = "voice_ch_char_Heitao_vo_companio_03"
        },
        voice_ch_char_Heitao_vo_companio_04_1 = {
          ContentEN = "I heard you're quite the gourmet. Could you show me some of your recipes? {nickname} always raves about your cooking, and it was genuine, not just flattery.",
          TextMapId = "voice_ch_char_Heitao_vo_companio_04_1"
        },
        voice_ch_char_Heitao_vo_companio_04_2 = {
          ContentEN = "Wait, is that all? Then why... What's your secret?",
          TextMapId = "voice_ch_char_Heitao_vo_companio_04_2"
        },
        voice_ch_char_Heitao_vo_die_r01 = {
          ContentEN = "I must... protect...",
          TextMapId = "voice_ch_char_Heitao_vo_die_r01"
        },
        voice_ch_char_Heitao_vo_die_r02 = {
          ContentEN = "How I wish to return to that place...",
          TextMapId = "voice_ch_char_Heitao_vo_die_r02"
        },
        voice_ch_char_Heitao_vo_fail = {
          ContentEN = "I'm just glad you're safe.",
          TextMapId = "voice_ch_char_Heitao_vo_fail"
        },
        voice_ch_char_Heitao_vo_gain = {
          ContentEN = "I'm back.",
          TextMapId = "voice_ch_char_Heitao_vo_gain"
        },
        voice_ch_char_Heitao_vo_idle = {
          ContentEN = "{性别:He|She} was never meant to be caged. I always knew {性别:he|she} would someday leave the island to reach for the sky. What I couldn't tell was whether that would be a blessing or a curse for us.",
          TextMapId = "voice_ch_char_Heitao_vo_idle"
        },
        voice_ch_char_Heitao_vo_lvup = {
          ContentEN = "what do you think?",
          TextMapId = "voice_ch_char_Heitao_vo_lvup"
        },
        voice_ch_char_Heitao_vo_revive = {
          ContentEN = "It's not over yet.",
          TextMapId = "voice_ch_char_Heitao_vo_revive"
        },
        voice_ch_char_Heitao_vo_skill01_r01 = {
          ContentEN = "Tear you apart.",
          TextMapId = "voice_ch_char_Heitao_vo_skill01_r01"
        },
        voice_ch_char_Heitao_vo_skill01_r02 = {
          ContentEN = "Surrender.",
          TextMapId = "voice_ch_char_Heitao_vo_skill01_r02"
        },
        voice_ch_char_Heitao_vo_skill02_r01 = {
          ContentEN = "May you rest in peace.",
          TextMapId = "voice_ch_char_Heitao_vo_skill02_r01"
        },
        voice_ch_char_Heitao_vo_skill02_r02 = {
          ContentEN = "Farewell.",
          TextMapId = "voice_ch_char_Heitao_vo_skill02_r02"
        },
        voice_ch_char_Heitao_vo_skill02_r03 = {
          ContentEN = "Those who harm you will be shown no quarter.",
          TextMapId = "voice_ch_char_Heitao_vo_skill02_r03"
        },
        voice_ch_char_Heitao_vo_topic_01_1 = {
          ContentEN = "...I'm not sure either. Maybe it's a beautiful dream where I've never left your side, as always.",
          TextMapId = "voice_ch_char_Heitao_vo_topic_01_1"
        },
        voice_ch_char_Heitao_vo_topic_01_2 = {
          ContentEN = "I feel the same, very much so... May we truly reunite one day.",
          TextMapId = "voice_ch_char_Heitao_vo_topic_01_2"
        },
        voice_ch_char_Heitao_vo_topic_02_1 = {
          ContentEN = "Wishes? I... can't think of any. Your smile in the morning is already the greatest pick-me-up of all.",
          TextMapId = "voice_ch_char_Heitao_vo_topic_02_1"
        },
        voice_ch_char_Heitao_vo_topic_02_2 = {
          ContentEN = "Don't push yourself. If you ever feel down, just come to me for a chat. Or, if you don't feel like talking, we can just spend some quiet time together.",
          TextMapId = "voice_ch_char_Heitao_vo_topic_02_2"
        },
        voice_ch_char_Heitao_vo_topic_03_1 = {
          ContentEN = "Unlike Purgatorio Island, it snows here every day. Thankfully, you have a warm place to stay. Compared to our little shack back on the island, this place feels quite luxurious.",
          TextMapId = "voice_ch_char_Heitao_vo_topic_03_1"
        },
        voice_ch_char_Heitao_vo_topic_03_2 = {
          ContentEN = "Remember how your hands would always get very cold in winter? Here, let me warm them up.",
          TextMapId = "voice_ch_char_Heitao_vo_topic_03_2"
        },
        voice_ch_char_Heitao_vo_topic_04_1 = {
          ContentEN = "Well, that place is like a city made of steel... Mm, more like a prison, to be precise. I spent my early years there.",
          TextMapId = "voice_ch_char_Heitao_vo_topic_04_1"
        },
        voice_ch_char_Heitao_vo_topic_04_2 = {
          ContentEN = "Later on, along with you, I was taken away from there by someone, and we ended up on Purgatorio Island. I can't share much about her, though — Sorry, I promised her.",
          TextMapId = "voice_ch_char_Heitao_vo_topic_04_2"
        },
        voice_ch_char_Heitao_vo_topic_04_3 = {
          ContentEN = "...Life on Purgatorio Island was so peaceful, that I almost believed we could live that way forever. But it wasn't until the day they came for me that I realised I had never truly escaped that prison.",
          TextMapId = "voice_ch_char_Heitao_vo_topic_04_3"
        },
        voice_ch_char_Heitao_vo_topic_05_1 = {
          ContentEN = "It's somewhat noisy, but I don't hate it. You've made many new friends here, which is a good thing — I'm really happy for you.",
          TextMapId = "voice_ch_char_Heitao_vo_topic_05_1"
        },
        voice_ch_char_Heitao_vo_topic_05_2 = {
          ContentEN = "This way, you'll never feel lonely, even when I'm not around.",
          TextMapId = "voice_ch_char_Heitao_vo_topic_05_2"
        },
        voice_ch_char_Heitao_vo_topic_06_1 = {
          ContentEN = "Then rest your head on my lap for a while, just like old times.",
          TextMapId = "voice_ch_char_Heitao_vo_topic_06_1"
        },
        voice_ch_char_Heitao_vo_victory = {
          ContentEN = "It's all over.",
          TextMapId = "voice_ch_char_Heitao_vo_victory"
        },
        voice_ch_char_Heitao_vo_welcome = {
          ContentEN = "Welcome back. What are your plans for today? Or are you planning to rest at home?",
          TextMapId = "voice_ch_char_Heitao_vo_welcome"
        },
        voice_ch_char_Kami_vo_appear = {
          ContentEN = "Time to stock up on a few bottles for The Asphodel.",
          TextMapId = "voice_ch_char_Kami_vo_appear"
        },
        voice_ch_char_Kami_vo_battleidle = {
          ContentEN = "Time is money. You can rest when the deal's settled.",
          TextMapId = "voice_ch_char_Kami_vo_battleidle"
        },
        voice_ch_char_Kami_vo_battlestart = {
          ContentEN = "Then we do this my way... and you'll learn just how cold the world is.",
          TextMapId = "voice_ch_char_Kami_vo_battlestart"
        },
        voice_ch_char_Kami_vo_be_hit_heavy_r01 = {
          ContentEN = "Playing dirty?",
          TextMapId = "voice_ch_char_Kami_vo_be_hit_heavy_r01"
        },
        voice_ch_char_Kami_vo_be_hit_heavy_r02 = {
          ContentEN = "Damn it!",
          TextMapId = "voice_ch_char_Kami_vo_be_hit_heavy_r02"
        },
        voice_ch_char_Kami_vo_birthday = {
          ContentEN = [[
Come by The Asphodel today. We'll be waiting.
Who's "we", you ask? The people of Icelake you've helped since you became a Phoxhunter, of course.
It's your birthday. Busy as you are, you might've forgotten. They didn't.
Everything's on the house today. Have whatever you like, catch up with everyone, and stay as long as you want.]],
          TextMapId = "voice_ch_char_Kami_vo_birthday"
        },
        voice_ch_char_Kami_vo_companio_02 = {
          ContentEN = "Everyone's gifted in their own way. Some are born with a knack for comforting others... like you.",
          TextMapId = "voice_ch_char_Kami_vo_companio_02"
        },
        voice_ch_char_Kami_vo_companio_03 = {
          ContentEN = "You don't often make the journey to Icelake. So — what is it this time? After some local specialities? Or just here to catch a show?",
          TextMapId = "voice_ch_char_Kami_vo_companio_03"
        },
        voice_ch_char_Kami_vo_companio_04 = {
          ContentEN = "That scar... don't tell me you've taken another dangerous job. I've got ointment behind the bar. Go and put some on. If anything happens to you in here, it's bad for business. Well? What are you waiting for — do you expect me to bring it over?",
          TextMapId = "voice_ch_char_Kami_vo_companio_04"
        },
        voice_ch_char_Kami_vo_die_r01 = {
          ContentEN = "All for nothing...",
          TextMapId = "voice_ch_char_Kami_vo_die_r01"
        },
        voice_ch_char_Kami_vo_die_r02 = {
          ContentEN = "Just another deal with Death.",
          TextMapId = "voice_ch_char_Kami_vo_die_r02"
        },
        voice_ch_char_Kami_vo_fail = {
          ContentEN = "Next time, I'll tip the odds in my favour.",
          TextMapId = "voice_ch_char_Kami_vo_fail"
        },
        voice_ch_char_Kami_vo_gain = {
          ContentEN = "It doesn't come cheap to get the proprietress of The Asphodel to step in — and money isn't the only currency I take. A merchant's intuition tells me you're carrying secrets worth far more than coin.",
          TextMapId = "voice_ch_char_Kami_vo_gain"
        },
        voice_ch_char_Kami_vo_idle = {
          ContentEN = "Spirits are best kept pure. Too many flavours, and you lose the nose. Same goes for people.",
          TextMapId = "voice_ch_char_Kami_vo_idle"
        },
        voice_ch_char_Kami_vo_lvup = {
          ContentEN = "Thinking of investing in The Asphodel? Not bad. You've got a good nose for business.",
          TextMapId = "voice_ch_char_Kami_vo_lvup"
        },
        voice_ch_char_Kami_vo_revive = {
          ContentEN = "I do wonder which is worse — hell, or a homeland you can't reach.",
          TextMapId = "voice_ch_char_Kami_vo_revive"
        },
        voice_ch_char_Kami_vo_skill01_r01 = {
          ContentEN = "Now you want to talk terms?",
          TextMapId = "voice_ch_char_Kami_vo_skill01_r01"
        },
        voice_ch_char_Kami_vo_skill01_r02 = {
          ContentEN = "See yourself out.",
          TextMapId = "voice_ch_char_Kami_vo_skill01_r02"
        },
        voice_ch_char_Kami_vo_skill02_r01 = {
          ContentEN = "The bar's closed.",
          TextMapId = "voice_ch_char_Kami_vo_skill02_r01"
        },
        voice_ch_char_Kami_vo_skill02_r02 = {
          ContentEN = "You look cold. Let's fix that.",
          TextMapId = "voice_ch_char_Kami_vo_skill02_r02"
        },
        voice_ch_char_Kami_vo_skill02_r03 = {
          ContentEN = "Fire's the same colour as wine. Look at that lovely crimson...",
          TextMapId = "voice_ch_char_Kami_vo_skill02_r03"
        },
        voice_ch_char_Kami_vo_topic_01_1 = {
          ContentEN = "Barrels? For keeping the good stuff, naturally. Tales of Icelake — crisp, refreshing. Legion Wolfblood — bold, with a kick. Azure Loong's Draught, brought in from Huaxu — clean, with a long finish. And Luca's Masquerade Rhapsody... ten flavours in one. Everyone swears it tastes different.",
          TextMapId = "voice_ch_char_Kami_vo_topic_01_1"
        },
        voice_ch_char_Kami_vo_topic_01_2 = {
          ContentEN = "Well? Fancy a glass?",
          TextMapId = "voice_ch_char_Kami_vo_topic_01_2"
        },
        voice_ch_char_Kami_vo_topic_01_3 = {
          ContentEN = "Heh. You've gotten a lot sharper — not like that wide-eyed greenhorn who first wandered into Icelake.",
          TextMapId = "voice_ch_char_Kami_vo_topic_01_3"
        },
        voice_ch_char_Kami_vo_topic_01_4 = {
          ContentEN = "Go a little over a hundred kilometres north of Icelake. Cross the Vidofnir Mountains and you'll reach the fjordlands of Askard — the Charons' homeland, if the stories are true.",
          TextMapId = "voice_ch_char_Kami_vo_topic_01_4"
        },
        voice_ch_char_Kami_vo_topic_01_5 = {
          ContentEN = "For many Charons in Icelake, what's a hundred-odd kilometres and a mountain range? The promised land isn't so far out of reach after all... wouldn't you say?",
          TextMapId = "voice_ch_char_Kami_vo_topic_01_5"
        },
        voice_ch_char_Kami_vo_topic_01_6 = {
          ContentEN = "Shh. I never said that.",
          TextMapId = "voice_ch_char_Kami_vo_topic_01_6"
        },
        voice_ch_char_Kami_vo_topic_02_1 = {
          ContentEN = "You flatter me. Phoxhunters have been around far longer than my tavern. They just need somewhere to chat, brag, and pass work around. If it weren't The Asphodel, it would be some other name on the sign.",
          TextMapId = "voice_ch_char_Kami_vo_topic_02_1"
        },
        voice_ch_char_Kami_vo_topic_02_2 = {
          ContentEN = "As for why they come here... it's nothing more than good drinks, a broker who plays fair, and a small favour now and then when someone's down on their luck.",
          TextMapId = "voice_ch_char_Kami_vo_topic_02_2"
        },
        voice_ch_char_Kami_vo_topic_03_1 = {
          ContentEN = "Instead of asking me, shouldn't you ask yourself? I still remember you turning up in Icelake with nowhere to go. You know perfectly well money's what keeps you on your feet in this world.",
          TextMapId = "voice_ch_char_Kami_vo_topic_03_1"
        },
        voice_ch_char_Kami_vo_topic_03_2 = {
          ContentEN = "Get enough money behind you and, even if you can't change where you came from, you'll have the nerve to take on whatever fate throws at you. When times are rough, you can at least buy yourself a warm drink... maybe even share a sip, do someone a good turn, and bank a favour for later.",
          TextMapId = "voice_ch_char_Kami_vo_topic_03_2"
        },
        voice_ch_char_Kami_vo_topic_03_3 = {
          ContentEN = "Now, does that answer your question?",
          TextMapId = "voice_ch_char_Kami_vo_topic_03_3"
        },
        voice_ch_char_Kami_vo_topic_04_1 = {
          ContentEN = "Not much, I'm afraid. I've been in Icelake for years, and I've never seen them before. They were wrapped head to toe in a cloak, and they spoke through a voice modulator. Where they came from, whether they were a man or a woman, even their age — I've no idea.",
          TextMapId = "voice_ch_char_Kami_vo_topic_04_1"
        },
        voice_ch_char_Kami_vo_topic_04_2 = {
          ContentEN = "The only thing I can be certain of is that they were far stronger than they had any right to be. We exchanged a few moves. That was enough to tell me I wouldn't have come out on top.",
          TextMapId = "voice_ch_char_Kami_vo_topic_04_2"
        },
        voice_ch_char_Kami_vo_topic_04_3 = {
          ContentEN = "Heh. In my line of work, you learn to count your chips — and size up what the other side is holding. Bluffing only works when you're playing for similar stakes. I pick my fights. That's how you stay alive.",
          TextMapId = "voice_ch_char_Kami_vo_topic_04_3"
        },
        voice_ch_char_Kami_vo_topic_04_4 = {
          ContentEN = "Actually... there was one thing they said before they left.",
          TextMapId = "voice_ch_char_Kami_vo_topic_04_4"
        },
        voice_ch_char_Kami_vo_topic_04_5 = {
          ContentEN = "They said what they wanted from you... was an \"answer\".",
          TextMapId = "voice_ch_char_Kami_vo_topic_04_5"
        },
        voice_ch_char_Kami_vo_victory = {
          ContentEN = "Payment received. Goods delivered.",
          TextMapId = "voice_ch_char_Kami_vo_victory"
        },
        voice_ch_char_Kami_vo_welcome = {
          ContentEN = "Business is what gets me out of bed. What about you?",
          TextMapId = "voice_ch_char_Kami_vo_welcome"
        },
        voice_ch_char_Kezhou_vo_appear = {
          ContentEN = "To kill, use a sword in hand; to find peace, sharpen the sword within.",
          TextMapId = "voice_ch_char_Kezhou_vo_appear"
        },
        voice_ch_char_Kezhou_vo_battleidle = {
          ContentEN = "I'm not out of tricks yet. Let's go another round!",
          TextMapId = "voice_ch_char_Kezhou_vo_battleidle"
        },
        voice_ch_char_Kezhou_vo_battlestart = {
          ContentEN = "Even the lion gives its all when hunting a hare.",
          TextMapId = "voice_ch_char_Kezhou_vo_battlestart"
        },
        voice_ch_char_Kezhou_vo_be_hit_heavy_r01 = {
          ContentEN = "Good strike!",
          TextMapId = "voice_ch_char_Kezhou_vo_be_hit_heavy_r01"
        },
        voice_ch_char_Kezhou_vo_be_hit_heavy_r02 = {
          ContentEN = "Missed the vital parts.",
          TextMapId = "voice_ch_char_Kezhou_vo_be_hit_heavy_r02"
        },
        voice_ch_char_Kezhou_vo_birthday = {
          ContentEN = "Today's great for drinking and sing— what's that? It's your birthday?\nWe Drifters don't pay much mind to birthdays. Out there, living rough, you never know when it'll be your last, so we don't usually bother with celebrations.\nBut hey, since you're not from around here and spar with me every day, a celebration feels just right.\nThen — let today echo with songs of heroes! Let us sing for the young, brave Phoxhunter, bound by honour and promises worth their weight in gold!",
          TextMapId = "voice_ch_char_Kezhou_vo_birthday"
        },
        voice_ch_char_Kezhou_vo_companio_01 = {
          ContentEN = "They say the best swordsman doesn't even need a sword — anything, a blade of grass, a twig, can become a weapon. I heard you fight with cleaning tools. Guess that makes you a master of the blade too, huh? Mind showing me a trick or two?",
          TextMapId = "voice_ch_char_Kezhou_vo_companio_01"
        },
        voice_ch_char_Kezhou_vo_companio_02 = {
          ContentEN = "I'm holding onto your old sword for now. When you stop moping around with that gloomy face, I'll give it back — but only if you beat me in a duel. Lose, and it's mine for good.",
          TextMapId = "voice_ch_char_Kezhou_vo_companio_02"
        },
        voice_ch_char_Kezhou_vo_companio_03 = {
          ContentEN = "A sword can be a friend, a toy, or even a tool for all sorts of things — cutting, prying, shaving. But it should never be your master. Don't let that blade hold you back.",
          TextMapId = "voice_ch_char_Kezhou_vo_companio_03"
        },
        voice_ch_char_Kezhou_vo_die_r01 = {
          ContentEN = "A wise man knows when to retreat — til we meet again.",
          TextMapId = "voice_ch_char_Kezhou_vo_die_r01"
        },
        voice_ch_char_Kezhou_vo_die_r02 = {
          ContentEN = "Skill sharpens with effort… slacks dull the blade…",
          TextMapId = "voice_ch_char_Kezhou_vo_die_r02"
        },
        voice_ch_char_Kezhou_vo_fail = {
          ContentEN = "Some battles you win, some you lose, no big deal. We'll go again.",
          TextMapId = "voice_ch_char_Kezhou_vo_fail"
        },
        voice_ch_char_Kezhou_vo_gain = {
          ContentEN = "The sky is my cover, the earth my bed. Sword in hand, I roam beneath the heavens, seeking justice where it's been denied.\nUgh, forget it. This fancy intro never feels right. Let's keep it simple — I'm Kezhou, a Drifter from Huaxu. If you need a hand, just say the word.",
          TextMapId = "voice_ch_char_Kezhou_vo_gain"
        },
        voice_ch_char_Kezhou_vo_idle = {
          ContentEN = "Bright and roomy — would be a perfect spot for sparring if there weren't so many tables and chairs in the way.",
          TextMapId = "voice_ch_char_Kezhou_vo_idle"
        },
        voice_ch_char_Kezhou_vo_lvup = {
          ContentEN = "You gotta see a thousand swords before you really understand one.",
          TextMapId = "voice_ch_char_Kezhou_vo_lvup"
        },
        voice_ch_char_Kezhou_vo_revive = {
          ContentEN = "This fight's far from over!",
          TextMapId = "voice_ch_char_Kezhou_vo_revive"
        },
        voice_ch_char_Kezhou_vo_skill01_r01 = {
          ContentEN = "Swift as a shadow!",
          TextMapId = "voice_ch_char_Kezhou_vo_skill01_r01"
        },
        voice_ch_char_Kezhou_vo_skill01_r02 = {
          ContentEN = "Stay put and be good!",
          TextMapId = "voice_ch_char_Kezhou_vo_skill01_r02"
        }
      }
    end
  },
  {
    MinKey = "voice_ch_char_Kezhou_vo_skill02_r01",
    MaxKey = "voice_ch_char_NanzhuLight_vo_skill01_r02",
    Loader = function()
      return {
        voice_ch_char_Kezhou_vo_skill02_r01 = {
          ContentEN = "Ten steps in, nothing lives.",
          TextMapId = "voice_ch_char_Kezhou_vo_skill02_r01"
        },
        voice_ch_char_Kezhou_vo_skill02_r02 = {
          ContentEN = "Dance of the sword, your final call.",
          TextMapId = "voice_ch_char_Kezhou_vo_skill02_r02"
        },
        voice_ch_char_Kezhou_vo_skill02_r03 = {
          ContentEN = "Time to test this blade!",
          TextMapId = "voice_ch_char_Kezhou_vo_skill02_r03"
        },
        voice_ch_char_Kezhou_vo_topic_01_1 = {
          ContentEN = "You're into swordplay too? Figured as much — you've got a fine blade there. You must be pretty good with it. Let's have a friendly spar and see what you've got!",
          TextMapId = "voice_ch_char_Kezhou_vo_topic_01_1"
        },
        voice_ch_char_Kezhou_vo_topic_01_2 = {
          ContentEN = "Honestly, it's been ages since I've met anyone truly on par with me. Though, my shifu always said I need more honing because I'm too blunt — and that I should work on my acting.",
          TextMapId = "voice_ch_char_Kezhou_vo_topic_01_2"
        },
        voice_ch_char_Kezhou_vo_topic_01_3 = {
          ContentEN = "Not exactly how I see it, but he always said that swordsmanship isn't just about skill; it's about strategy. Stuff like \"conceal your strength by feigning weakness,\" \"subdue the enemy without fighting,\" and \"overwhelm the few with the many.\" Said that's what separates the good from the great.",
          TextMapId = "voice_ch_char_Kezhou_vo_topic_01_3"
        },
        voice_ch_char_Kezhou_vo_topic_01_4 = {
          ContentEN = "Back when I was a kid, he used to pull that same trick on me. He'd claim his skills were mediocre and tell me if I could knock him down, I wouldn't have to train anymore. Took me a whole year to realize I couldn't even touch his sleeve.",
          TextMapId = "voice_ch_char_Kezhou_vo_topic_01_4"
        },
        voice_ch_char_Kezhou_vo_topic_01_5 = {
          ContentEN = "One day, I was so wiped out I just collapsed. That's when I noticed — not a single drop of sweat beneath his feet. That doddering, clumsy look of his? All an act.",
          TextMapId = "voice_ch_char_Kezhou_vo_topic_01_5"
        },
        voice_ch_char_Kezhou_vo_topic_02_1 = {
          ContentEN = "Plenty of reasons, really, but if I had to sum it up: I hate being bound by them.",
          TextMapId = "voice_ch_char_Kezhou_vo_topic_02_1"
        },
        voice_ch_char_Kezhou_vo_topic_02_2 = {
          ContentEN = "I've been free-spirited all my life, doing everything my way, drawing my sword wherever I saw injustice. I only ever listened to what I wanted to hear from my Shifu or Yuming. The rest? In one ear and out the other, like the wind passing by. So tell me, why would I let myself be chained by some laws?",
          TextMapId = "voice_ch_char_Kezhou_vo_topic_02_2"
        },
        voice_ch_char_Kezhou_vo_topic_02_3 = {
          ContentEN = "I'd say it's the concern of a swordsman. Think of it this way — when you first learn swordsmanship, you follow the swordplay scroll move by move, right? Against regular foes, that's enough. Your sword moves instinctively.",
          TextMapId = "voice_ch_char_Kezhou_vo_topic_02_3"
        },
        voice_ch_char_Kezhou_vo_topic_02_4 = {
          ContentEN = "But if you stick too closely to the scroll and can't think on your feet, your sword's no better than a lump of scrap — dull, clumsy, useless. Face something unexpected, and you'll flail around like a headless chicken.",
          TextMapId = "voice_ch_char_Kezhou_vo_topic_02_4"
        },
        voice_ch_char_Kezhou_vo_topic_02_5 = {
          ContentEN = "To me, Huaxu is like a clumsy swordsman glued to their Nine Chapters of Dafeng. They can't even deal with a Drifter like me — what chance do they have against a true threat? It's only a matter of time before they fall.",
          TextMapId = "voice_ch_char_Kezhou_vo_topic_02_5"
        },
        voice_ch_char_Kezhou_vo_topic_03_1 = {
          ContentEN = "Of course! Being good with a sword doesn't mean you're stuck using only it. In Huaxu, there are people who can use pens and chopsticks as weapons — does that mean swordsmen are supposed to starve or never write?",
          TextMapId = "voice_ch_char_Kezhou_vo_topic_03_1"
        },
        voice_ch_char_Kezhou_vo_topic_03_2 = {
          ContentEN = "Oh, I can do that. But why bother? Dodging is way easier, after all. Even boars in the woods know to go for radishes over tree bark when they can.",
          TextMapId = "voice_ch_char_Kezhou_vo_topic_03_2"
        },
        voice_ch_char_Kezhou_vo_topic_03_3 = {
          ContentEN = "That said, if I ever meet a worthy opponent, you can bet I'll draw my sword and go all out.",
          TextMapId = "voice_ch_char_Kezhou_vo_topic_03_3"
        },
        voice_ch_char_Kezhou_vo_topic_04_1 = {
          ContentEN = "They sure do. Now that you mention it, I can think of quite a few. Stuff like \"King So-and-So,\" \"Lord Something,\" or \"Immortal This-and-That.\" Animals are the go-to — dragons, tigers, lions, cranes, you name it. It's like a whole zoo out there.",
          TextMapId = "voice_ch_char_Kezhou_vo_topic_04_1"
        },
        voice_ch_char_Kezhou_vo_topic_04_2 = {
          ContentEN = "Here's how it works: the longer the title, the lousier the skills. Four words? A newbie. Three? Not bad. Two — that's someone you don't want to mess with. And those with no nickname at all? They're the true grandmasters.",
          TextMapId = "voice_ch_char_Kezhou_vo_topic_04_2"
        },
        voice_ch_char_Kezhou_vo_topic_04_3 = {
          ContentEN = "I walk this world with my real name, of course. I know, it sounds made-up, doesn't it? Even my shifu used to say so — warned me that a name like this would have people mistaking me for some prodigy, and that'd only bring me trouble.",
          TextMapId = "voice_ch_char_Kezhou_vo_topic_04_3"
        },
        voice_ch_char_Kezhou_vo_topic_04_4 = {
          ContentEN = "But it's the name my old man gave me. Maybe he hoped I'd grow up to be some kind of hero. He didn't leave much behind, but carrying this name feels like his sword still leaves its mark on the world.",
          TextMapId = "voice_ch_char_Kezhou_vo_topic_04_4"
        },
        voice_ch_char_Kezhou_vo_victory = {
          ContentEN = "A blade in hand to right all wrongs — who's next?",
          TextMapId = "voice_ch_char_Kezhou_vo_victory"
        },
        voice_ch_char_Kezhou_vo_welcome = {
          ContentEN = "Today's perfect for drinking and singing! Come on, let me finish this glass, and then we'll chase down the sinners who deserve my sword. What? I said the same thing yesterday? Well, every day's a fine day to live like this, don't you think?",
          TextMapId = "voice_ch_char_Kezhou_vo_welcome"
        },
        voice_ch_char_Landi_vo_appear = {
          ContentEN = "Do I really have to go there this time?",
          TextMapId = "voice_ch_char_Landi_vo_appear"
        },
        voice_ch_char_Landi_vo_battleidle = {
          ContentEN = "I wish they could understand the value of taking a break like me.",
          TextMapId = "voice_ch_char_Landi_vo_battleidle"
        },
        voice_ch_char_Landi_vo_battlestart = {
          ContentEN = "Let's target the weak spot in their defences.",
          TextMapId = "voice_ch_char_Landi_vo_battlestart"
        },
        voice_ch_char_Landi_vo_be_hit_heavy_r01 = {
          ContentEN = "That was brutal.",
          TextMapId = "voice_ch_char_Landi_vo_be_hit_heavy_r01"
        },
        voice_ch_char_Landi_vo_be_hit_heavy_r02 = {
          ContentEN = "This is so tiring.",
          TextMapId = "voice_ch_char_Landi_vo_be_hit_heavy_r02"
        },
        voice_ch_char_Landi_vo_birthday = {
          ContentEN = "I've been waiting here for ages, sacrificing my precious downtime, all so that I can give you an unforgettable birthday. I even upgraded your kitchen utensils and baked you a cake last night. It might not look like much, but I hope you like it. After all, it was quite a challenge for a baking newbie like me.",
          TextMapId = "voice_ch_char_Landi_vo_birthday"
        },
        voice_ch_char_Landi_vo_companio_01 = {
          ContentEN = "Reporting, Chief Sibylle. Today's tasks have been arranged. If you have any additional orders, I'm ready to carry them out. However, today was quite demanding, so you should take some rest to avoid burning out.",
          TextMapId = "voice_ch_char_Landi_vo_companio_01"
        },
        voice_ch_char_Landi_vo_companio_02 = {
          ContentEN = "Great job on the last mission, but I've received some complaints about damage to public property... I find it kinda awkward to apologise to people on your behalf... After all, I'm a bit shy. Soooo, lovely and kind-hearted Miss Lynn, could you handle these urgent tasks for me? Pretty please with a cherry on top!",
          TextMapId = "voice_ch_char_Landi_vo_companio_02"
        },
        voice_ch_char_Landi_vo_companio_03 = {
          ContentEN = "Wha... How can this be? Maybe I'm just so tired that I'm seeing things now. Might as well file for a work-related injury and take a few more days off.",
          TextMapId = "voice_ch_char_Landi_vo_companio_03"
        },
        voice_ch_char_Landi_vo_die_r01 = {
          ContentEN = "I shouldn't have taken this task...",
          TextMapId = "voice_ch_char_Landi_vo_die_r01"
        },
        voice_ch_char_Landi_vo_die_r02 = {
          ContentEN = "Falling into a deep sleep... isn't as nice as I thought...",
          TextMapId = "voice_ch_char_Landi_vo_die_r02"
        },
        voice_ch_char_Landi_vo_fail = {
          ContentEN = "The art of war also involves knowing when to withdraw! Sooo, I'm going now!",
          TextMapId = "voice_ch_char_Landi_vo_fail"
        },
        voice_ch_char_Landi_vo_gain = {
          ContentEN = [[
Hah, you got me. Looks like my easy days are over... Still, you seem like a decent sort,
so I suppose I could lend a hand. In my own personal capacity, of course.]],
          TextMapId = "voice_ch_char_Landi_vo_gain"
        },
        voice_ch_char_Landi_vo_idle = {
          ContentEN = "Hmm... This sneak folding shotgun could use an auto-fire upgrade, and if I give it more firepower... Then, we can take out our enemies even faster on our next mission and head home early.",
          TextMapId = "voice_ch_char_Landi_vo_idle"
        },
        voice_ch_char_Landi_vo_lvup = {
          ContentEN = "It may be irritating, but preparing before battle is never a waste of time.",
          TextMapId = "voice_ch_char_Landi_vo_lvup"
        },
        voice_ch_char_Landi_vo_revive = {
          ContentEN = "Time to perk up. It's work time...",
          TextMapId = "voice_ch_char_Landi_vo_revive"
        },
        voice_ch_char_Landi_vo_skill01_r01 = {
          ContentEN = "Hurry up and surrender.",
          TextMapId = "voice_ch_char_Landi_vo_skill01_r01"
        },
        voice_ch_char_Landi_vo_skill01_r02 = {
          ContentEN = "Relax.",
          TextMapId = "voice_ch_char_Landi_vo_skill01_r02"
        },
        voice_ch_char_Landi_vo_skill02_r01 = {
          ContentEN = "Weakness identified.",
          TextMapId = "voice_ch_char_Landi_vo_skill02_r01"
        },
        voice_ch_char_Landi_vo_skill02_r02 = {
          ContentEN = "Here's the winning move.",
          TextMapId = "voice_ch_char_Landi_vo_skill02_r02"
        },
        voice_ch_char_Landi_vo_skill02_r03 = {
          ContentEN = "Never get in the way of me and my rest.",
          TextMapId = "voice_ch_char_Landi_vo_skill02_r03"
        },
        voice_ch_char_Landi_vo_topic_01_1 = {
          ContentEN = "My family? My parents haven't really fussed over me for years; just my sisters occasionally trying to boss me around. But now that I'm in the Legion, they're out of reach.",
          TextMapId = "voice_ch_char_Landi_vo_topic_01_1"
        },
        voice_ch_char_Landi_vo_topic_01_2 = {
          ContentEN = "Oh, not at all! T-They're absolutely delightful, smart, kind-hearted, gentle, charming, beautiful, and just about perfect! Though, a bit more decorum would be nice...",
          TextMapId = "voice_ch_char_Landi_vo_topic_01_2"
        },
        voice_ch_char_Landi_vo_topic_02_1 = {
          ContentEN = "Huh, you're one of those who don't appreciate a good rest! Listen up: Beds are havens, where souls find ease; rooftops sanctuaries, where anxieties cease. In afternoon gardens, the sunlight gleams; take a nap, and enjoy the symphony of sweet dreams...",
          TextMapId = "voice_ch_char_Landi_vo_topic_02_1"
        },
        voice_ch_char_Landi_vo_topic_02_2 = {
          ContentEN = "...Hey! I wasn't done!",
          TextMapId = "voice_ch_char_Landi_vo_topic_02_2"
        },
        voice_ch_char_Landi_vo_topic_03_1 = {
          ContentEN = "She sure knows how to run you ragged... I'd need to split myself in three just to keep up... Ahem, I mean, Chief Sibylle is always perfectly strict with us.",
          TextMapId = "voice_ch_char_Landi_vo_topic_03_1"
        },
        voice_ch_char_Landi_vo_topic_03_2 = {
          ContentEN = "...How about I treat you to some afternoon tea, and we pretend this conversation never happened? Don't worry, it won't be spiked.",
          TextMapId = "voice_ch_char_Landi_vo_topic_03_2"
        },
        voice_ch_char_Landi_vo_topic_04_1 = {
          ContentEN = "I've rigged up something awesome for you — a tiny robot sidekick! It'll follow you around in battle, waving a little banner and cheering, \"Go get'em! You're smashing it!\"",
          TextMapId = "voice_ch_char_Landi_vo_topic_04_1"
        },
        voice_ch_char_Landi_vo_topic_04_2 = {
          ContentEN = "Pretty cool, huh? Just wait till I actually get it working...",
          TextMapId = "voice_ch_char_Landi_vo_topic_04_2"
        },
        voice_ch_char_Landi_vo_topic_04_3 = {
          ContentEN = "Hey, I didn't finish! I drew up these plans during my precious breaks — do you know how hard it was for me to keep them from Chief Sibylle?",
          TextMapId = "voice_ch_char_Landi_vo_topic_04_3"
        },
        voice_ch_char_Landi_vo_victory = {
          ContentEN = "I'm sure a smart and efficient commander like you can handle tying up loose ends on your own, right? Catch you later!",
          TextMapId = "voice_ch_char_Landi_vo_victory"
        },
        voice_ch_char_Landi_vo_welcome = {
          ContentEN = "Ahh... I feel so fresh after just waking up. Listen, buddy, there's no point in working all day. Your to-do list will never end. Remember, relaxation is a necessity, not a luxury.",
          TextMapId = "voice_ch_char_Landi_vo_welcome"
        },
        voice_ch_char_Linen_vo_appear = {
          ContentEN = "Who's the target today?",
          TextMapId = "voice_ch_char_Linen_vo_appear"
        },
        voice_ch_char_Linen_vo_battleidle = {
          ContentEN = "Move it, or else you won't live long enough to pay me.",
          TextMapId = "voice_ch_char_Linen_vo_battleidle"
        },
        voice_ch_char_Linen_vo_battlestart = {
          ContentEN = "Let's go!",
          TextMapId = "voice_ch_char_Linen_vo_battlestart"
        },
        voice_ch_char_Linen_vo_be_hit_heavy_r01 = {
          ContentEN = "** hurt!",
          TextMapId = "voice_ch_char_Linen_vo_be_hit_heavy_r01"
        },
        voice_ch_char_Linen_vo_be_hit_heavy_r02 = {
          ContentEN = "Not bad.",
          TextMapId = "voice_ch_char_Linen_vo_be_hit_heavy_r02"
        },
        voice_ch_char_Linen_vo_be_hit_r01 = {
          ContentEN = "Tsk.",
          TextMapId = "voice_ch_char_Linen_vo_be_hit_r01"
        },
        voice_ch_char_Linen_vo_be_hit_r02 = {
          ContentEN = "Uh.",
          TextMapId = "voice_ch_char_Linen_vo_be_hit_r02"
        },
        voice_ch_char_Linen_vo_birthday = {
          ContentEN = "Happy birthday. I'm not good with fancy words, so I'll just wish you never have money issues. As for today's mission, I'll give you a generous 20% discount. Sounds pretty sweet, right?",
          TextMapId = "voice_ch_char_Linen_vo_birthday"
        },
        voice_ch_char_Linen_vo_companio_01 = {
          ContentEN = "Keep it short and cut to the chase next time, will you? All this unnecessary mumbling is getting on my nerves.",
          TextMapId = "voice_ch_char_Linen_vo_companio_01"
        },
        voice_ch_char_Linen_vo_companio_02 = {
          ContentEN = "Good day, ma'am...",
          TextMapId = "voice_ch_char_Linen_vo_companio_02"
        },
        voice_ch_char_Linen_vo_companio_03 = {
          ContentEN = "You're a top soldier. That's all I've got to say. Also... make sure you look after yourself in your downtime. Chop-chop, you've heard enough, now get out of here.",
          TextMapId = "voice_ch_char_Linen_vo_companio_03"
        },
        voice_ch_char_Linen_vo_die_r01 = {
          ContentEN = "Who... else...?",
          TextMapId = "voice_ch_char_Linen_vo_die_r01"
        },
        voice_ch_char_Linen_vo_die_r02 = {
          ContentEN = "I can't take it... anymore...",
          TextMapId = "voice_ch_char_Linen_vo_die_r02"
        },
        voice_ch_char_Linen_vo_fail = {
          ContentEN = "Keep this to yourself. Otherwise, I'll bash your brains in.",
          TextMapId = "voice_ch_char_Linen_vo_fail"
        },
        voice_ch_char_Linen_vo_gain = {
          ContentEN = "Didn't think I'd be freelancing for you. What do you need? Let's start with my payment.",
          TextMapId = "voice_ch_char_Linen_vo_gain"
        },
        voice_ch_char_Linen_vo_idle = {
          ContentEN = "Not bad. I should have enough for this month. I thought that ** Randy would take it all himself. I'll send this lot home and get by with the rest.",
          TextMapId = "voice_ch_char_Linen_vo_idle"
        },
        voice_ch_char_Linen_vo_lvup = {
          ContentEN = "What a bore.",
          TextMapId = "voice_ch_char_Linen_vo_lvup"
        },
        voice_ch_char_Linen_vo_revive = {
          ContentEN = "Bring it on!",
          TextMapId = "voice_ch_char_Linen_vo_revive"
        },
        voice_ch_char_Linen_vo_skill01_r01 = {
          ContentEN = "Destroy!",
          TextMapId = "voice_ch_char_Linen_vo_skill01_r01"
        },
        voice_ch_char_Linen_vo_skill01_r02 = {
          ContentEN = "I'm gonna kick your asses.",
          TextMapId = "voice_ch_char_Linen_vo_skill01_r02"
        },
        voice_ch_char_Linen_vo_skill02_r01 = {
          ContentEN = "You asked for it.",
          TextMapId = "voice_ch_char_Linen_vo_skill02_r01"
        },
        voice_ch_char_Linen_vo_skill02_r02 = {
          ContentEN = "Pay for wasting my time!",
          TextMapId = "voice_ch_char_Linen_vo_skill02_r02"
        },
        voice_ch_char_Linen_vo_skill02_r03 = {
          ContentEN = "Now I'm mad.",
          TextMapId = "voice_ch_char_Linen_vo_skill02_r03"
        },
        voice_ch_char_Linen_vo_topic_01_1 = {
          ContentEN = "Sibylle? She's the chief of the 13th Legion.",
          TextMapId = "voice_ch_char_Linen_vo_topic_01_1"
        },
        voice_ch_char_Linen_vo_topic_01_2 = {
          ContentEN = "Ugh, what do you expect me to know? She calls the shots, I do the work. That's all.",
          TextMapId = "voice_ch_char_Linen_vo_topic_01_2"
        },
        voice_ch_char_Linen_vo_topic_02_1 = {
          ContentEN = "Tips? The only tip I have is there's no problem a good punch can't fix. If that doesn't work, throw another.",
          TextMapId = "voice_ch_char_Linen_vo_topic_02_1"
        },
        voice_ch_char_Linen_vo_topic_02_2 = {
          ContentEN = "Then a bullet usually does the trick.",
          TextMapId = "voice_ch_char_Linen_vo_topic_02_2"
        },
        voice_ch_char_Linen_vo_topic_02_3 = {
          ContentEN = "It's just a figure of speech. My point is: be as tough and strong as you can be, and that's all you need. Keep nitpicking, and your face will be getting those punches next.",
          TextMapId = "voice_ch_char_Linen_vo_topic_02_3"
        },
        voice_ch_char_Linen_vo_topic_03_1 = {
          ContentEN = "Saw a really nice gun the other day... Forget it, can't skimp on food just to buy it. The old one feels better in my hands anyway.",
          TextMapId = "voice_ch_char_Linen_vo_topic_03_1"
        },
        voice_ch_char_Linen_vo_topic_03_2 = {
          ContentEN = "Really?... Nah, you look as broke as me... I appreciate the gesture, but don't go break a piggy bank for me. I don't wanna owe anyone anything.",
          TextMapId = "voice_ch_char_Linen_vo_topic_03_2"
        },
        voice_ch_char_Linen_vo_topic_04_1 = {
          ContentEN = "No work, no food. What don't you get?",
          TextMapId = "voice_ch_char_Linen_vo_topic_04_1"
        },
        voice_ch_char_Linen_vo_topic_04_2 = {
          ContentEN = "Balance would be great, but my clients don't see it that way — always hounding me, \"Is the job done yet? Hurry up!\" Ugh, if I didn't have a family to feed, I'd punch them in their stupid faces.",
          TextMapId = "voice_ch_char_Linen_vo_topic_04_2"
        },
        voice_ch_char_Linen_vo_victory = {
          ContentEN = "That's it? How pathetic.",
          TextMapId = "voice_ch_char_Linen_vo_victory"
        },
        voice_ch_char_Linen_vo_welcome = {
          ContentEN = "Need anything? Spit it out quickly. I've got a mission to finish.",
          TextMapId = "voice_ch_char_Linen_vo_welcome"
        },
        voice_ch_char_Lise_vo_appear = {
          ContentEN = "Weapons, supplies, power levels, mission plans — check completed for the seventeenth time. Standing by.",
          TextMapId = "voice_ch_char_Lise_vo_appear"
        },
        voice_ch_char_Lise_vo_battleidle = {
          ContentEN = "I can't stop here. I have to keep fighting.",
          TextMapId = "voice_ch_char_Lise_vo_battleidle"
        },
        voice_ch_char_Lise_vo_battlestart = {
          ContentEN = "Rhythm Fischer, reporting in! Standing by for your orders!",
          TextMapId = "voice_ch_char_Lise_vo_battlestart"
        },
        voice_ch_char_Lise_vo_be_hit_heavy_r01 = {
          ContentEN = "I've had worse.",
          TextMapId = "voice_ch_char_Lise_vo_be_hit_heavy_r01"
        },
        voice_ch_char_Lise_vo_birthday = {
          ContentEN = "Birthday celebrations? It's been ages since I last attended one... When I was little, my family always made elaborate preparations for birthdays. But as the years went by, my brother and I hardly saw each other, and birthdays lost their meaning. \nI used to dream that one day, when we had both achieved something great, we'd host a grand celebration — like those extravagant parties in the inner city, with crystal chandeliers, a towering cake, silk gowns... everything perfect. But now, that dream will never come true...\nAh, I'm so sorry! I didn't mean to spoil the mood with my rambling on such a joyful occasion... Please, don't let my words dampen the day. While I may not celebrate my own birthday, I still want to extend my heartfelt wishes to you: may your day be filled with happiness, cherished memories, and the warmth of those you hold dear.",
          TextMapId = "voice_ch_char_Lise_vo_birthday"
        },
        voice_ch_char_Lise_vo_companio_01 = {
          ContentEN = "I can't seem to ignore things that are out of place — I always feel the urge to tidy them up. But your place, Miss Hilda, is an exception. Everything's perfectly in order, and I find that truly admirable.",
          TextMapId = "voice_ch_char_Lise_vo_companio_01"
        },
        voice_ch_char_Lise_vo_companio_02 = {
          ContentEN = "This proposal is remarkably detailed, down to every second accounted for. Following it through must be immensely satisfying. It's just... hard to believe something like this was put together by Lieutenant Colonel Randy.",
          TextMapId = "voice_ch_char_Lise_vo_companio_02"
        },
        voice_ch_char_Lise_vo_companio_03 = {
          ContentEN = "Would you mind playing a different tune? It's not that your music isn't beautiful — it is just that... it stirs memories I'd rather not dwell on.",
          TextMapId = "voice_ch_char_Lise_vo_companio_03"
        },
        voice_ch_char_Lise_vo_die_r01 = {
          ContentEN = "Sorry... I never meant to break my promise...",
          TextMapId = "voice_ch_char_Lise_vo_die_r01"
        },
        voice_ch_char_Lise_vo_die_r02 = {
          ContentEN = "This... isn't so bad after all...",
          TextMapId = "voice_ch_char_Lise_vo_die_r02"
        },
        voice_ch_char_Lise_vo_fail = {
          ContentEN = "Once again... I couldn't protect the ones around me.",
          TextMapId = "voice_ch_char_Lise_vo_fail"
        },
        voice_ch_char_Lise_vo_gain_01 = {
          ContentEN = "Warrant Officer Rhythm Fischer, Icelake Escort, 6th Legion of Hyperborea. What's the matter? If it's something beyond your control, I can assist — though consider it a personal favour, nothing more.",
          TextMapId = "voice_ch_char_Lise_vo_gain_01"
        },
        voice_ch_char_Lise_vo_gain_02 = {
          ContentEN = "Yes, Sir! Rhythm Fischer, reporting for—oh, it's you... My apologies. I often forget... I'm no longer part of the Escort... Forgive me.",
          TextMapId = "voice_ch_char_Lise_vo_gain_02"
        },
        voice_ch_char_Lise_vo_idle = {
          ContentEN = "Is there anything I can help with? It's not that I'm a workaholic — it's just... a habit, I guess. When I'm not busy, I feel unsettled.",
          TextMapId = "voice_ch_char_Lise_vo_idle"
        },
        voice_ch_char_Lise_vo_lvup = {
          ContentEN = "Chaotic currents... who are they meant to serve?",
          TextMapId = "voice_ch_char_Lise_vo_lvup"
        },
        voice_ch_char_Lise_vo_revive = {
          ContentEN = "I made a promise to live on.",
          TextMapId = "voice_ch_char_Lise_vo_revive"
        },
        voice_ch_char_Lise_vo_skill01_r01 = {
          ContentEN = "Zap!",
          TextMapId = "voice_ch_char_Lise_vo_skill01_r01"
        },
        voice_ch_char_Lise_vo_skill01_r02 = {
          ContentEN = "Shatter!",
          TextMapId = "voice_ch_char_Lise_vo_skill01_r02"
        },
        voice_ch_char_Lise_vo_skill02_r01 = {
          ContentEN = "Mission wrapping up.",
          TextMapId = "voice_ch_char_Lise_vo_skill02_r01"
        },
        voice_ch_char_Lise_vo_skill02_r02 = {
          ContentEN = "The currents will silence you.",
          TextMapId = "voice_ch_char_Lise_vo_skill02_r02"
        },
        voice_ch_char_Lise_vo_skill02_r03 = {
          ContentEN = "Because — I chose to live on!",
          TextMapId = "voice_ch_char_Lise_vo_skill02_r03"
        },
        voice_ch_char_Lise_vo_topic_01_1 = {
          ContentEN = "Oh... You've noticed. Yes, I have one — it was given to me by someone very dear. I keep it locked away safely, but... I can't help checking on it now and then, worried it might just vanish somehow.",
          TextMapId = "voice_ch_char_Lise_vo_topic_01_1"
        },
        voice_ch_char_Lise_vo_topic_01_2 = {
          ContentEN = "Actually, I only know one. The person who gave it to me taught me. I wasn't quick to pick it up back then... maybe because I've never been good at things that require emotional expression...",
          TextMapId = "voice_ch_char_Lise_vo_topic_01_2"
        },
        voice_ch_char_Lise_vo_topic_01_3 = {
          ContentEN = "But whenever I'm too tense or carried away, I find myself reaching for it. It's like an anchor — a reminder of the things that matter, the things I can trust. It always helps me find my calm again.",
          TextMapId = "voice_ch_char_Lise_vo_topic_01_3"
        },
        voice_ch_char_Lise_vo_topic_01_4 = {
          ContentEN = "Many of my peers rely on doctors for stress relief — sedatives, stimulants, that kind of stuff. I've never needed that. Whether my heart races or slows, the harmonica always steadies me.",
          TextMapId = "voice_ch_char_Lise_vo_topic_01_4"
        },
        voice_ch_char_Lise_vo_topic_02_1 = {
          ContentEN = "Not bad. The Legion is one of the few places where hard work truly gets rewarded. I've earned my position here, and now I even have a few subordinates. I make sure they treat Charons and Solas with the same respect.",
          TextMapId = "voice_ch_char_Lise_vo_topic_02_1"
        },
        voice_ch_char_Lise_vo_topic_02_2 = {
          ContentEN = "I've heard plenty of complaints — and bitter accusations — about how harshly the Legion treats the Charon community. I do everything I can to change that... Maybe someday, people will start to see the Legion in a better light.",
          TextMapId = "voice_ch_char_Lise_vo_topic_02_2"
        },
        voice_ch_char_Lise_vo_topic_02_3 = {
          ContentEN = "Not yet. But there will be. There was a time when you wouldn't find even a single Charon in the Legion. I know I can't make a big difference just yet, but if I guide my subordinates down the right path, I believe the conflicts between Charons and Solas will ease, bit by bit.",
          TextMapId = "voice_ch_char_Lise_vo_topic_02_3"
        },
        voice_ch_char_Lise_vo_topic_02_4 = {
          ContentEN = "Treating everyone fairly and keeping them safe from Filthoids and Deterioration... I believe these efforts can improve life for the Charon community. Maybe, it will quiet the weary sighs echoing through Icelake a little bit.",
          TextMapId = "voice_ch_char_Lise_vo_topic_02_4"
        },
        voice_ch_char_Lise_vo_topic_03_1 = {
          ContentEN = "I wouldn't call it responsibility. I'm simply following the Escort's regulations to the letter.",
          TextMapId = "voice_ch_char_Lise_vo_topic_03_1"
        },
        voice_ch_char_Lise_vo_topic_03_2 = {
          ContentEN = "The Escort's regulations forbid any legionary from commenting on the conduct of their fellow legionaries.",
          TextMapId = "voice_ch_char_Lise_vo_topic_03_2"
        },
        voice_ch_char_Lise_vo_topic_03_3 = {
          ContentEN = "That said, I really don't understand them. Maybe, to them, it's just a job. As long as their superiors don't notice, they think it's fine to slack off or mess around.",
          TextMapId = "voice_ch_char_Lise_vo_topic_03_3"
        },
        voice_ch_char_Lise_vo_topic_03_4 = {
          ContentEN = "I think that kind of attitude is wrong. People need something to keep themselves in check. Without it, they'll just drift through life, letting their standards erode little by little — until they're no better than rats in the sewers.",
          TextMapId = "voice_ch_char_Lise_vo_topic_03_4"
        },
        voice_ch_char_Lise_vo_topic_04_1 = {
          ContentEN = "No... Thank you. I don't really enjoy looking at myself in the mirror. Seeing my horns always makes me feel... uncomfortable.",
          TextMapId = "voice_ch_char_Lise_vo_topic_04_1"
        },
        voice_ch_char_Lise_vo_topic_04_2 = {
          ContentEN = "No, that's not it at all. I'm not ashamed of my Charon heritage. It's just... I think my horns would look much better if they were more regular, more symmetrical. Ah, don't get me wrong! I'm not saying there's anything wrong with your horn...",
          TextMapId = "voice_ch_char_Lise_vo_topic_04_2"
        },
        voice_ch_char_Lise_vo_topic_05_1 = {
          ContentEN = "I do... but it feels so heavy now, almost unbearably so. I'm not sure I have the strength to pick it up and play anymore.",
          TextMapId = "voice_ch_char_Lise_vo_topic_05_1"
        },
        voice_ch_char_Lise_vo_topic_05_2 = {
          ContentEN = "After all, it once carried all my hopes and dreams. Now, it just reminds me of everything I've lost.",
          TextMapId = "voice_ch_char_Lise_vo_topic_05_2"
        },
        voice_ch_char_Lise_vo_topic_05_3 = {
          ContentEN = "...Thank you. I promise, when the day comes that I can pick it up again — when I'm ready to learn a new tune — I'll make sure you're the first to hear it.",
          TextMapId = "voice_ch_char_Lise_vo_topic_05_3"
        },
        voice_ch_char_Lise_vo_topic_06_1 = {
          ContentEN = "I've been taking on odd jobs here and there. It's enough to cover my expenses. But honestly, earning a living isn't the point anymore. These days, work is more about keeping myself busy.",
          TextMapId = "voice_ch_char_Lise_vo_topic_06_1"
        },
        voice_ch_char_Lise_vo_topic_06_2 = {
          ContentEN = "Yes... Work gives me purpose. It makes me happy. When I'm busy, even the sunlight feels a little warmer.",
          TextMapId = "voice_ch_char_Lise_vo_topic_06_2"
        },
        voice_ch_char_Lise_vo_topic_07_1 = {
          ContentEN = "Better than if I'd stayed, I suppose. The Legion was once my refuge, the place where I thought my dreams could take flight. But those dreams... they turned out to be illusions, and that so-called refuge was a hell that dragged my loved one into an unending abyss of despair...",
          TextMapId = "voice_ch_char_Lise_vo_topic_07_1"
        },
        voice_ch_char_Lise_vo_topic_07_2 = {
          ContentEN = "Now, my heart burns with the desire for vengeance, yet I can't bring myself to aim my weapon at those I once called comrades. I feel lost... Tell me, what should I do?",
          TextMapId = "voice_ch_char_Lise_vo_topic_07_2"
        },
        voice_ch_char_Lise_vo_topic_07_3 = {
          ContentEN = "...Sorry, I lost my cool. You're right — I need to figure it out on my own, instead of placing that weight on you. Though... it might take me some time.",
          TextMapId = "voice_ch_char_Lise_vo_topic_07_3"
        },
        voice_ch_char_Lise_vo_victory = {
          ContentEN = "Such a pity it ended so quickly. Take me on the next mission — you'll win, and I'll stay occupied.",
          TextMapId = "voice_ch_char_Lise_vo_victory"
        },
        voice_ch_char_Lise_vo_welcome = {
          ContentEN = "Patrol complete. No signs of dangerous creatures, structural damage, or suspicious markings. Routine operations may proceed without interruption. Report concluded.",
          TextMapId = "voice_ch_char_Lise_vo_welcome"
        },
        voice_ch_char_Maer_vo_appear = {
          ContentEN = "Where are we heading for today's haul?",
          TextMapId = "voice_ch_char_Maer_vo_appear"
        },
        voice_ch_char_Maer_vo_battleidle = {
          ContentEN = "Chop-chop! There's room for more!",
          TextMapId = "voice_ch_char_Maer_vo_battleidle"
        },
        voice_ch_char_Maer_vo_battlestart = {
          ContentEN = "Let's see what we can find this time!",
          TextMapId = "voice_ch_char_Maer_vo_battlestart"
        },
        voice_ch_char_Maer_vo_be_hit_heavy_r01 = {
          ContentEN = "That really hurt!",
          TextMapId = "voice_ch_char_Maer_vo_be_hit_heavy_r01"
        },
        voice_ch_char_Maer_vo_be_hit_heavy_r02 = {
          ContentEN = "Owwww!",
          TextMapId = "voice_ch_char_Maer_vo_be_hit_heavy_r02"
        },
        voice_ch_char_Maer_vo_birthday = {
          ContentEN = "Happy Birthday! Look, I made this for you — a little Plumpytail doll, just like mine~ You've been dying to give Plumpytail a good squeeze, haven't you? Hehe, this reticent detective has figured you out!",
          TextMapId = "voice_ch_char_Maer_vo_birthday"
        },
        voice_ch_char_Maer_vo_companio_01 = {
          ContentEN = "Look at the fabric, the badge, and the leather! Ms Hilda, you are my angel! If you've got more of these ill-gotten goods that need \"proper disposal\", I'm your girl! You can count on me to take good care of them!",
          TextMapId = "voice_ch_char_Maer_vo_companio_01"
        },
        voice_ch_char_Maer_vo_companio_02 = {
          ContentEN = "Little Fina! It's been ages~ Wanna hear the next chapter of \"Snowball the Cat Ranger & Ginger the Cat Detective\"? No problem! Let me just grab a stool and settle in for a good tale!",
          TextMapId = "voice_ch_char_Maer_vo_companio_02"
        },
        voice_ch_char_Maer_vo_companio_03 = {
          ContentEN = "I assure you I'm an upstanding citizen, Ms Warden! Never pilfered or plundered, merely collecting some scraps from the bins to quiet my stomach. Even your dedication doesn't extend to rubbish, does it?",
          TextMapId = "voice_ch_char_Maer_vo_companio_03"
        },
        voice_ch_char_Maer_vo_companio_04 = {
          ContentEN = "You're living hand to mouth, aren't you...? That's really tough. Would you like to join me in scavenging? Might make things a bit easier...",
          TextMapId = "voice_ch_char_Maer_vo_companio_04"
        },
        voice_ch_char_Maer_vo_companio_05 = {
          ContentEN = "Ms Camilla! The kindest and most beautiful lady in Icelake! Could you maybe help me out of a tiny spot of bother... I promise this is the last time! Er, well, the last this month! You wouldn't have the heart to say no, right?",
          TextMapId = "voice_ch_char_Maer_vo_companio_05"
        },
        voice_ch_char_Maer_vo_die_r01 = {
          ContentEN = "Am I... being recycled too...?",
          TextMapId = "voice_ch_char_Maer_vo_die_r01"
        },
        voice_ch_char_Maer_vo_die_r02 = {
          ContentEN = "If only I could see Icelake... one last time...",
          TextMapId = "voice_ch_char_Maer_vo_die_r02"
        },
        voice_ch_char_Maer_vo_fail = {
          ContentEN = "It's okay, staying alive is what counts!",
          TextMapId = "voice_ch_char_Maer_vo_fail"
        },
        voice_ch_char_Maer_vo_gain_1 = {
          ContentEN = "Hello there, welcome to Icelake! Feeling a bit out of place? Let me, Margie, show you around the wonders of this place. First stop... surprise rubbish bins galore!",
          TextMapId = "voice_ch_char_Maer_vo_gain_1"
        },
        voice_ch_char_Maer_vo_gain_2 = {
          ContentEN = "What? You've already heard of my title \"Princess Rubbish Bin\"?! Ugh... please don't go along with it! Just call me Margie. No princess here, just a little scavenger of Icelake!",
          TextMapId = "voice_ch_char_Maer_vo_gain_2"
        },
        voice_ch_char_Maer_vo_idle = {
          ContentEN = "Aww~ What a lovely day! Perfect for picking flowers, and I'd smell great after that~ Care to join me?",
          TextMapId = "voice_ch_char_Maer_vo_idle"
        },
        voice_ch_char_Maer_vo_lvup = {
          ContentEN = "Wow! My hauling pockets just got roomier!",
          TextMapId = "voice_ch_char_Maer_vo_lvup"
        },
        voice_ch_char_Maer_vo_revive = {
          ContentEN = "Waste turned into wealth!",
          TextMapId = "voice_ch_char_Maer_vo_revive"
        },
        voice_ch_char_Maer_vo_skill01_r01 = {
          ContentEN = "Recyclable.",
          TextMapId = "voice_ch_char_Maer_vo_skill01_r01"
        },
        voice_ch_char_Maer_vo_skill01_r02 = {
          ContentEN = "Non-recyclable.",
          TextMapId = "voice_ch_char_Maer_vo_skill01_r02"
        },
        voice_ch_char_Maer_vo_skill02_r01 = {
          ContentEN = "Time to incinerate some waste!",
          TextMapId = "voice_ch_char_Maer_vo_skill02_r01"
        },
        voice_ch_char_Maer_vo_skill02_r02 = {
          ContentEN = "This is where you belong!",
          TextMapId = "voice_ch_char_Maer_vo_skill02_r02"
        },
        voice_ch_char_Maer_vo_skill02_r03 = {
          ContentEN = "Burn! Bury! Burst!",
          TextMapId = "voice_ch_char_Maer_vo_skill02_r03"
        },
        voice_ch_char_Maer_vo_topic_01_1 = {
          ContentEN = "Well... it's about giving discarded items a new home and providing those in need with a chance at a better life.",
          TextMapId = "voice_ch_char_Maer_vo_topic_01_1"
        },
        voice_ch_char_Maer_vo_topic_01_2 = {
          ContentEN = "For instance, turning an aristocrat's cast-off velvet curtains into warm winter coats for the elderly, or bringing discarded dolls to children whose only playthings are pebbles — they'll be overjoyed for a long time.",
          TextMapId = "voice_ch_char_Maer_vo_topic_01_2"
        },
        voice_ch_char_Maer_vo_topic_01_3 = {
          ContentEN = "There was one time, I dragged back a broken bookshelf someone had thrown out. Though I was half-dead from the effort, it quickly turned into a non-stop playground for a litter of kittens — totally worth it!",
          TextMapId = "voice_ch_char_Maer_vo_topic_01_3"
        },
        voice_ch_char_Maer_vo_topic_01_4 = {
          ContentEN = "That's scavenging for you! It's mostly small fry stuff, but never a dull moment. So, what do you say, wanna join us?",
          TextMapId = "voice_ch_char_Maer_vo_topic_01_4"
        },
        voice_ch_char_Maer_vo_topic_02_1 = {
          ContentEN = "Shhhh! That's a scavenger's top secret! I wouldn't have let you in on it if you hadn't helped me out with that thief!",
          TextMapId = "voice_ch_char_Maer_vo_topic_02_1"
        },
        voice_ch_char_Maer_vo_topic_02_2 = {
          ContentEN = "This map charts every rubbish bin in Icelake, and I've marked the few where the best stuff tends to gather — I've upgraded those bins to larger sizes and timed my visits to perfection!",
          TextMapId = "voice_ch_char_Maer_vo_topic_02_2"
        },
        voice_ch_char_Maer_vo_topic_02_3 = {
          ContentEN = "But scavenging is really hit-or-miss — mostly, it all comes down to luck...",
          TextMapId = "voice_ch_char_Maer_vo_topic_02_3"
        },
        voice_ch_char_Maer_vo_topic_02_4 = {
          ContentEN = "Ha, I knew you'd understand!",
          TextMapId = "voice_ch_char_Maer_vo_topic_02_4"
        },
        voice_ch_char_Maer_vo_topic_03_1 = {
          ContentEN = "Oh, you've got it backwards! I love Icelake through and through. It's just that I often reminisce about the days I spent wandering the snowfields with my dad; that's how I grew up.",
          TextMapId = "voice_ch_char_Maer_vo_topic_03_1"
        },
        voice_ch_char_Maer_vo_topic_03_2 = {
          ContentEN = "From here, the snowfields look like something out of a fairy tale. But once you step into it, you'd feel so very small. Even after trudging through knee-high snow for hours, that feeling would never leave.",
          TextMapId = "voice_ch_char_Maer_vo_topic_03_2"
        },
        voice_ch_char_Maer_vo_topic_03_3 = {
          ContentEN = "I don't hate those days. But the bustling, lively Icelake is my absolute favourite!",
          TextMapId = "voice_ch_char_Maer_vo_topic_03_3"
        },
        voice_ch_char_Maer_vo_topic_04_1 = {
          ContentEN = "That's the big cat that used to roam the snowfields with me when I was little! We called him \"Plumpytail\". He would only let me pet him in exchange for some jerky, but oh, the feel of his fur — hehehe, it's the best of the best!",
          TextMapId = "voice_ch_char_Maer_vo_topic_04_1"
        },
        voice_ch_char_Maer_vo_topic_04_2 = {
          ContentEN = "Mmm... it's certainly not like \"meow\"; it's more like, \"raawr—raawr—!\"",
          TextMapId = "voice_ch_char_Maer_vo_topic_04_2"
        },
        voice_ch_char_Maer_vo_topic_04_3 = {
          ContentEN = "Plumpytail prefers the wild over city life. We had to go our separate ways, but she'll always be a part of me, just like the snowfields.",
          TextMapId = "voice_ch_char_Maer_vo_topic_04_3"
        },
        voice_ch_char_Maer_vo_topic_05_1 = {
          ContentEN = "Nah-uh! That's not me! I'm too grown up for such a childish title! Please, I beg of you, don't ever call me that again!",
          TextMapId = "voice_ch_char_Maer_vo_topic_05_1"
        },
        voice_ch_char_Maer_vo_topic_05_2 = {
          ContentEN = "Ahem, that would be — Lady Margie the reticent detective, a lone shadow-walker of the city! Today, I will unveil for you the secrets of Icelake, as always!",
          TextMapId = "voice_ch_char_Maer_vo_topic_05_2"
        },
        voice_ch_char_Maer_vo_topic_05_3 = {
          ContentEN = "Hehe, now that's a proper title for me~",
          TextMapId = "voice_ch_char_Maer_vo_topic_05_3"
        },
        voice_ch_char_Maer_vo_victory = {
          ContentEN = "What a bountiful haul today!",
          TextMapId = "voice_ch_char_Maer_vo_victory"
        },
        voice_ch_char_Maer_vo_welcome = {
          ContentEN = "I've cleared the snow from your doorstep on my way here! Touched, huh? Bet you're thinking of treating me to a cup of cocoa~",
          TextMapId = "voice_ch_char_Maer_vo_welcome"
        },
        voice_ch_char_NanzhuDark_vo_appear = {
          ContentEN = "Even having faced death once, I won't change the way I walk this world. To deny who I was, that would be the only true death.",
          TextMapId = "voice_ch_char_NanzhuDark_vo_appear"
        },
        voice_ch_char_NanzhuDark_vo_battleidle = {
          ContentEN = "Rest a while. Then continue on. Just... don't stay too long.",
          TextMapId = "voice_ch_char_NanzhuDark_vo_battleidle"
        },
        voice_ch_char_NanzhuDark_vo_battlestart = {
          ContentEN = "I can still hear the call of the Misty Sea.",
          TextMapId = "voice_ch_char_NanzhuDark_vo_battlestart"
        },
        voice_ch_char_NanzhuDark_vo_die_r01 = {
          ContentEN = "Sorry... I failed...",
          TextMapId = "voice_ch_char_NanzhuDark_vo_die_r01"
        },
        voice_ch_char_NanzhuDark_vo_die_r02 = {
          ContentEN = "Still... Not enough...",
          TextMapId = "voice_ch_char_NanzhuDark_vo_die_r02"
        },
        voice_ch_char_NanzhuDark_vo_fail = {
          ContentEN = "Just another stumble on the road ahead. It's far too soon to lose heart.",
          TextMapId = "voice_ch_char_NanzhuDark_vo_fail"
        },
        voice_ch_char_NanzhuDark_vo_lvup = {
          ContentEN = "The road ahead demands more than I am now.",
          TextMapId = "voice_ch_char_NanzhuDark_vo_lvup"
        },
        voice_ch_char_NanzhuDark_vo_revive = {
          ContentEN = "I've returned from the Misty Sea. Now, it's your turn.",
          TextMapId = "voice_ch_char_NanzhuDark_vo_revive"
        },
        voice_ch_char_NanzhuDark_vo_skill01_r01 = {
          ContentEN = "Your fate is in my hands.",
          TextMapId = "voice_ch_char_NanzhuDark_vo_skill01_r01"
        },
        voice_ch_char_NanzhuDark_vo_skill01_r02 = {
          ContentEN = "Embrace the darkness.",
          TextMapId = "voice_ch_char_NanzhuDark_vo_skill01_r02"
        },
        voice_ch_char_NanzhuDark_vo_skill02_r01 = {
          ContentEN = "Enter your eternal rest.",
          TextMapId = "voice_ch_char_NanzhuDark_vo_skill02_r01"
        },
        voice_ch_char_NanzhuDark_vo_skill02_r02 = {
          ContentEN = "Shadows will grant you peace.",
          TextMapId = "voice_ch_char_NanzhuDark_vo_skill02_r02"
        },
        voice_ch_char_NanzhuDark_vo_skill02_r03 = {
          ContentEN = "May you rest in the Misty Sea.",
          TextMapId = "voice_ch_char_NanzhuDark_vo_skill02_r03"
        },
        voice_ch_char_NanzhuDark_vo_victory = {
          ContentEN = "One more step. That future's within reach.",
          TextMapId = "voice_ch_char_NanzhuDark_vo_victory"
        },
        voice_ch_char_NanzhuLight_vo_appear = {
          ContentEN = "The world outside Purgatorio Island defies all accounts — more expansive, yet more brutal. This cannot be its true destiny. That's why a change must be made.",
          TextMapId = "voice_ch_char_NanzhuLight_vo_appear"
        },
        voice_ch_char_NanzhuLight_vo_battleidle = {
          ContentEN = "Where's next? Let me check the map... Ugh... I know maps don't like me.",
          TextMapId = "voice_ch_char_NanzhuLight_vo_battleidle"
        },
        voice_ch_char_NanzhuLight_vo_battlestart = {
          ContentEN = "This sword still fulfils its duty.",
          TextMapId = "voice_ch_char_NanzhuLight_vo_battlestart"
        },
        voice_ch_char_NanzhuLight_vo_die_r01 = {
          ContentEN = "I can't stop... not now...",
          TextMapId = "voice_ch_char_NanzhuLight_vo_die_r01"
        },
        voice_ch_char_NanzhuLight_vo_die_r02 = {
          ContentEN = "If only... I could make it back to where we promised...",
          TextMapId = "voice_ch_char_NanzhuLight_vo_die_r02"
        },
        voice_ch_char_NanzhuLight_vo_fail = {
          ContentEN = "Next time, they will pay the price.",
          TextMapId = "voice_ch_char_NanzhuLight_vo_fail"
        },
        voice_ch_char_NanzhuLight_vo_lvup = {
          ContentEN = "Every step I've taken, every word I've heard, and every soul I've met — all have honed my view of this world and the edge of my sword.",
          TextMapId = "voice_ch_char_NanzhuLight_vo_lvup"
        },
        voice_ch_char_NanzhuLight_vo_revive = {
