        },
        voice_ch_char_Nifu_vo_die_r02 = {
          ContentEN = "Might as well enjoy the solace in this fleeting slumber.",
          TextMapId = "voice_ch_char_Nifu_vo_die_r02"
        },
        voice_ch_char_Nifu_vo_fail = {
          ContentEN = "It matters not. Victory and defeat are but fleeting moments. Rise, and begin anew.",
          TextMapId = "voice_ch_char_Nifu_vo_fail"
        },
        voice_ch_char_Nifu_vo_gain = {
          ContentEN = "I am Nifle, the Ferrywoman of the Misty Sea. Fear not — the Misty Sea does not reach this place, nor are you a wandering soul. Think of me merely as a passerby... or perhaps, a witness to your journey.",
          TextMapId = "voice_ch_char_Nifu_vo_gain"
        },
        voice_ch_char_Nifu_vo_idle = {
          ContentEN = "In a land so fraught with turmoil, having such a tranquil place for even a brief moment of peace is a rare comfort.",
          TextMapId = "voice_ch_char_Nifu_vo_idle"
        },
        voice_ch_char_Nifu_vo_lvup = {
          ContentEN = "Like springtime's gentle return, when grasses break through the earth and trees bud anew.",
          TextMapId = "voice_ch_char_Nifu_vo_lvup"
        },
        voice_ch_char_Nifu_vo_revive = {
          ContentEN = "It seems my time to depart has not yet arrived.",
