        voice_ch_char_Nifu_vo_skill01_r01 = {
          ContentEN = "Samsara's Pulse.",
          TextMapId = "voice_ch_char_Nifu_vo_skill01_r01"
        },
        voice_ch_char_Nifu_vo_skill01_r02 = {
          ContentEN = "Night turns to dawn.",
          TextMapId = "voice_ch_char_Nifu_vo_skill01_r02"
        },
        voice_ch_char_Nifu_vo_skill02_r01 = {
          ContentEN = "Like the merciful tears of Mother Embla.",
          TextMapId = "voice_ch_char_Nifu_vo_skill02_r01"
        },
        voice_ch_char_Nifu_vo_skill02_r02 = {
          ContentEN = "As every river returns to the Misty Sea.",
          TextMapId = "voice_ch_char_Nifu_vo_skill02_r02"
        },
        voice_ch_char_Nifu_vo_skill02_r03 = {
          ContentEN = "Be still the lost soul, 'tis my guide you follow.",
          TextMapId = "voice_ch_char_Nifu_vo_skill02_r03"
        },
        voice_ch_char_Nifu_vo_topic_01_1 = {
          ContentEN = "Indeed. Over the course of endless time, I've travelled — or perhaps wandered — through every corner of Atlasia, treading upon every inch of its soil and tracing every grain of sand with my fingertips.",
          TextMapId = "voice_ch_char_Nifu_vo_topic_01_1"
        },
        voice_ch_char_Nifu_vo_topic_01_2 = {
          ContentEN = "Once you've seen enough, you'll find that the scenery of all places is not so different after all. Whether it's the snows of the North, the sands of Khemet, or the smoke curling from the chimneys of Huaxu, they are all but different shades of mist drifting through the forest.",
          TextMapId = "voice_ch_char_Nifu_vo_topic_01_2"
        },
        voice_ch_char_Nifu_vo_topic_01_3 = {
          ContentEN = "If I had to choose, though... it would be the mountains and forests of Aethyrie. The air there brings me the most peace.",
          TextMapId = "voice_ch_char_Nifu_vo_topic_01_3"
        },
        voice_ch_char_Nifu_vo_topic_01_4 = {
          ContentEN = "Perhaps you will.",
          TextMapId = "voice_ch_char_Nifu_vo_topic_01_4"
        },
        voice_ch_char_Nifu_vo_topic_01_5 = {
          ContentEN = "Should you wander into the Emerald Forest, would you mind bringing a bouquet of white asters for me? Beneath its earth rest my friends, my child, and a version of myself from long ago.",
          TextMapId = "voice_ch_char_Nifu_vo_topic_01_5"
        },
        voice_ch_char_Nifu_vo_topic_02_1 = {
          ContentEN = "The Misty Sea is the birthplace and final rest of all living beings. To the Misty Sea, the deceased return, and from there, life begins anew... just as dying clouds dissolve into the earth as rain, only for flowers to bloom again from that very soil.",
          TextMapId = "voice_ch_char_Nifu_vo_topic_02_1"
        },
        voice_ch_char_Nifu_vo_topic_02_2 = {
          ContentEN = "I believe so, my child. One day, you will journey to the Misty Sea, into the embrace of Mother Embla.",
          TextMapId = "voice_ch_char_Nifu_vo_topic_02_2"
        },
        voice_ch_char_Nifu_vo_topic_02_3 = {
          ContentEN = "My dear child, cherish all that life offers, yet do not shrink from its passing. Demise is not suffering, but the inevitable conclusion of life's journey.",
          TextMapId = "voice_ch_char_Nifu_vo_topic_02_3"
        },
        voice_ch_char_Nifu_vo_topic_02_4 = {
          ContentEN = "Should you ever grow weary, rest in my arms for a while... There is no need to fear — this will not be your eternal sleep. There is still much for you to fulfil in this world.",
          TextMapId = "voice_ch_char_Nifu_vo_topic_02_4"
        },
        voice_ch_char_Nifu_vo_topic_03_1 = {
          ContentEN = "Did that surprise you? Long ago, during the Great Migration, I stood on the front lines as a soldier well-versed in close combat.",
          TextMapId = "voice_ch_char_Nifu_vo_topic_03_1"
        },
        voice_ch_char_Nifu_vo_topic_03_2 = {
          ContentEN = "Though those days are far behind me, I still remember the essentials of fighting.",
          TextMapId = "voice_ch_char_Nifu_vo_topic_03_2"
        },
        voice_ch_char_Nifu_vo_topic_03_3 = {
          ContentEN = "During my wanderings, I've often faced roaming beasts. Their claws and fangs have left me with scars, bruises, and even deaths I should have rightfully endured.",
          TextMapId = "voice_ch_char_Nifu_vo_topic_03_3"
        },
        voice_ch_char_Nifu_vo_topic_03_4 = {
          ContentEN = "Even the eternal moon wanes and waxes, ever changing. Humans, naturally, are far more complex — especially one who's lived countless lifetimes beyond a mortal span.",
          TextMapId = "voice_ch_char_Nifu_vo_topic_03_4"
        },
        voice_ch_char_Nifu_vo_topic_03_5 = {
          ContentEN = "If you're curious about those days, I'll recount them in detail for you another time.",
          TextMapId = "voice_ch_char_Nifu_vo_topic_03_5"
        },
        voice_ch_char_Nifu_vo_topic_04_1 = {
          ContentEN = "\"Friends\"... By the common definition of the word, I've had many over my long years.",
          TextMapId = "voice_ch_char_Nifu_vo_topic_04_1"
        },
        voice_ch_char_Nifu_vo_topic_04_10 = {
          ContentEN = "The funny thing is, I can't even recall why they argued in the first place. Strange, isn't it? When I think of them now, it's always these small, insignificant details that come to mind first.",
          TextMapId = "voice_ch_char_Nifu_vo_topic_04_10"
        },
        voice_ch_char_Nifu_vo_topic_04_11 = {
          ContentEN = "Indeed. Those were such precious, joyful days... But they are far behind me now.",
          TextMapId = "voice_ch_char_Nifu_vo_topic_04_11"
        },
        voice_ch_char_Nifu_vo_topic_04_2 = {
          ContentEN = "Yet when I hear that word, the first who come to mind are Lexis and Erika, the two who once led me away from Elysium.",
          TextMapId = "voice_ch_char_Nifu_vo_topic_04_2"
        },
        voice_ch_char_Nifu_vo_topic_04_3 = {
          ContentEN = "In the annals of history and the tales of heroes, they're often portrayed as the Sage who tore away the gods' veil of ignorance, and the Heroine who gave her life for the Sage's cause...",
          TextMapId = "voice_ch_char_Nifu_vo_topic_04_3"
        },
        voice_ch_char_Nifu_vo_topic_04_4 = {
          ContentEN = "But in my memories, they are simply Lexis and Erika.",
          TextMapId = "voice_ch_char_Nifu_vo_topic_04_4"
        },
        voice_ch_char_Nifu_vo_topic_04_5 = {
          ContentEN = "Erika was a brave and lively young woman, with a spirit that drew everyone to her. Lexis, though brilliant, often overthought things. He'd suddenly lapse into deep musings, which, ironically, made him seem a bit slow.",
          TextMapId = "voice_ch_char_Nifu_vo_topic_04_5"
        },
        voice_ch_char_Nifu_vo_topic_04_6 = {
          ContentEN = "Mm... There was one time Lexis tried to apologize to Erika for something he'd done. On a whim, she pointed to one of the soldiers' archery training dummies, saying she'd forgive him if he could hit the bullseye...",
          TextMapId = "voice_ch_char_Nifu_vo_topic_04_6"
        },
        voice_ch_char_Nifu_vo_topic_04_7 = {
          ContentEN = "Of course, she didn't mean it seriously. Not even all the soldiers could manage it, let alone Lexis, whose hands were meant for quills and scrolls, not bows or blades.",
          TextMapId = "voice_ch_char_Nifu_vo_topic_04_7"
        },
        voice_ch_char_Nifu_vo_topic_04_8 = {
          ContentEN = "But he took her words to heart. After the soldiers left, he stayed behind and practised alone, long into the night.",
          TextMapId = "voice_ch_char_Nifu_vo_topic_04_8"
        },
        voice_ch_char_Nifu_vo_topic_04_9 = {
          ContentEN = "As you might guess, true history is not a tale of omnipotent heroes. Even someone as brilliant as Lexis had his limits — he practised until his palms bled. Erika ended up wrapping them in linen, but he never did strike the mark.",
          TextMapId = "voice_ch_char_Nifu_vo_topic_04_9"
        },
        voice_ch_char_Nifu_vo_victory = {
          ContentEN = "Those drifting towards the Misty Sea shall find solace in her embrace, borne upon the rains of renewal, to merge with the next endless stream.",
          TextMapId = "voice_ch_char_Nifu_vo_victory"
        },
        voice_ch_char_Nifu_vo_welcome = {
          ContentEN = "Ah, it's you, my dear child. Good day. Is there something on your mind you'd like to share with me?",
          TextMapId = "voice_ch_char_Nifu_vo_welcome"
        },
        voice_ch_char_NvzhuLight_vo_appear = {
          ContentEN = "The world outside Purgatorio Island defies all accounts — more expansive, yet more brutal. This cannot be its true destiny. That's why a change must be made.",
          TextMapId = "voice_ch_char_NvzhuLight_vo_appear"
        },
        voice_ch_char_NvzhuLight_vo_battleidle = {
          ContentEN = "Where's next? Let me check the map... Ugh... I know maps don't like me.",
          TextMapId = "voice_ch_char_NvzhuLight_vo_battleidle"
        },
        voice_ch_char_NvzhuLight_vo_battlestart = {
          ContentEN = "This sword still fulfils its duty.",
          TextMapId = "voice_ch_char_NvzhuLight_vo_battlestart"
        },
        voice_ch_char_NvzhuLight_vo_die_r01 = {
          ContentEN = "I can't stop... not now...",
          TextMapId = "voice_ch_char_NvzhuLight_vo_die_r01"
        },
        voice_ch_char_NvzhuLight_vo_die_r02 = {
          ContentEN = "If only... I could make it back to where we promised...",
          TextMapId = "voice_ch_char_NvzhuLight_vo_die_r02"
        },
        voice_ch_char_NvzhuLight_vo_fail = {
          ContentEN = "Next time, they will pay the price.",
          TextMapId = "voice_ch_char_NvzhuLight_vo_fail"
        },
        voice_ch_char_NvzhuLight_vo_lvup = {
          ContentEN = "Every step I've taken, every word I've heard, and every soul I've met — all have honed my view of this world and the edge of my sword.",
          TextMapId = "voice_ch_char_NvzhuLight_vo_lvup"
        },
        voice_ch_char_NvzhuLight_vo_revive = {
          ContentEN = "Was that... just a nightmare?",
          TextMapId = "voice_ch_char_NvzhuLight_vo_revive"
        },
        voice_ch_char_NvzhuLight_vo_skill01_r01 = {
          ContentEN = "Vanish.",
          TextMapId = "voice_ch_char_NvzhuLight_vo_skill01_r01"
        },
        voice_ch_char_NvzhuLight_vo_skill01_r02 = {
          ContentEN = "Light slash.",
          TextMapId = "voice_ch_char_NvzhuLight_vo_skill01_r02"
        },
        voice_ch_char_NvzhuLight_vo_skill02_r01 = {
          ContentEN = "This time, I will be the shield.",
          TextMapId = "voice_ch_char_NvzhuLight_vo_skill02_r01"
        },
        voice_ch_char_NvzhuLight_vo_skill02_r02 = {
          ContentEN = "For the future we shall face together.",
          TextMapId = "voice_ch_char_NvzhuLight_vo_skill02_r02"
        },
        voice_ch_char_NvzhuLight_vo_skill02_r03 = {
          ContentEN = "Return to the Misty Sea.",
          TextMapId = "voice_ch_char_NvzhuLight_vo_skill02_r03"
        },
        voice_ch_char_NvzhuLight_vo_victory = {
          ContentEN = "Another step forward. As long as I keep proceeding, I'll get there...",
          TextMapId = "voice_ch_char_NvzhuLight_vo_victory"
        },
        voice_ch_char_Saiqi01_vo_appear = {
          ContentEN = "The butterfly's just fluttered over with an invitation. It told me there's a midsummer ball in the woods full of viola tricolor...",
          TextMapId = "voice_ch_char_Saiqi01_vo_appear"
        },
        voice_ch_char_Saiqi01_vo_battlestart = {
          ContentEN = "Let's go — to corners of the world I've never seen.",
          TextMapId = "voice_ch_char_Saiqi01_vo_battlestart"
        },
        voice_ch_char_Saiqi01_vo_gain = {
          ContentEN = "Look, those twinkling lights — are they fireflies pretending to be stars? And that racket matching the titmice — is it the cicadas singing? Oh, the baby deer and bunny asked me to play music for their ball, but I don't know how to play the violin... Can you teach me?",
          TextMapId = "voice_ch_char_Saiqi01_vo_gain"
        },
        voice_ch_char_Saiqi01_vo_skill02_r01 = {
          ContentEN = "Dance— for a life ablaze!",
          TextMapId = "voice_ch_char_Saiqi01_vo_skill02_r01"
        },
        voice_ch_char_Saiqi_vo_appear = {
          ContentEN = "I knew you'd bring me along.",
          TextMapId = "voice_ch_char_Saiqi_vo_appear"
        },
        voice_ch_char_Saiqi_vo_battleidle = {
          ContentEN = "I wish my journey wouldn't end so soon.",
          TextMapId = "voice_ch_char_Saiqi_vo_battleidle"
        },
        voice_ch_char_Saiqi_vo_battlestart = {
          ContentEN = "I'm so excited! I finally get to fight with you!",
          TextMapId = "voice_ch_char_Saiqi_vo_battlestart"
        },
        voice_ch_char_Saiqi_vo_be_hit_heavy_r01 = {
          ContentEN = "I won't surrender!",
          TextMapId = "voice_ch_char_Saiqi_vo_be_hit_heavy_r01"
        },
        voice_ch_char_Saiqi_vo_be_hit_heavy_r02 = {
          ContentEN = "I'm okay!",
          TextMapId = "voice_ch_char_Saiqi_vo_be_hit_heavy_r02"
        },
        voice_ch_char_Saiqi_vo_be_hit_r01 = {
          ContentEN = "Oww!",
          TextMapId = "voice_ch_char_Saiqi_vo_be_hit_r01"
        },
        voice_ch_char_Saiqi_vo_be_hit_r02 = {
          ContentEN = "Ouch!",
          TextMapId = "voice_ch_char_Saiqi_vo_be_hit_r02"
        },
        voice_ch_char_Saiqi_vo_birthday = {
          ContentEN = "Happy birthday, I have a gift for you.... I hope you like it. It's a snowflake lotus. It symbolises \"rebirth.\" You see, from the moment we met, we've shared countless adventures, and in that time, I've witnessed your growth and \"rebirth.\" So, I think this lotus is the perfect gift for you!",
          TextMapId = "voice_ch_char_Saiqi_vo_birthday"
        },
        voice_ch_char_Saiqi_vo_companio_01 = {
          ContentEN = "I heard you planned a great birthday celebration for Fina. I know that you possess a considerate heart, despite your sharp tongue. Can I join you next time when you prepare a big birthday surprise for her?",
          TextMapId = "voice_ch_char_Saiqi_vo_companio_01"
        },
        voice_ch_char_Saiqi_vo_companio_02 = {
          ContentEN = "Camilla, you remind me of your noisy yet homey tavern. I'm so blessed to have friends like you guys.",
          TextMapId = "voice_ch_char_Saiqi_vo_companio_02"
        },
        voice_ch_char_Saiqi_vo_companio_03 = {
          ContentEN = [[
Are you gonna tell me the story of Elysium? Thank you so much! I wonder what kind of flowers you'd like in return?
Delicious ones, you say?]],
          TextMapId = "voice_ch_char_Saiqi_vo_companio_03"
        },
        voice_ch_char_Saiqi_vo_die_r01 = {
          ContentEN = "After fighting alongside you... I have no regrets.",
          TextMapId = "voice_ch_char_Saiqi_vo_die_r01"
        },
        voice_ch_char_Saiqi_vo_die_r02 = {
          ContentEN = "My journey ends here...",
          TextMapId = "voice_ch_char_Saiqi_vo_die_r02"
        },
        voice_ch_char_Saiqi_vo_fail = {
          ContentEN = "It's okay. Here's a flower for you. Next time, fortune will be on our side.",
          TextMapId = "voice_ch_char_Saiqi_vo_fail"
        },
        voice_ch_char_Saiqi_vo_gain = {
          ContentEN = "Is that you... My friend from afar? Does your voice call out to me?",
          TextMapId = "voice_ch_char_Saiqi_vo_gain"
        },
        voice_ch_char_Saiqi_vo_idle = {
          ContentEN = "I feel like time flies when I do nothing but watch you guys... I wish time wouldn't go so fast.",
          TextMapId = "voice_ch_char_Saiqi_vo_idle"
        },
        voice_ch_char_Saiqi_vo_lvup = {
          ContentEN = "Now I can protect you all!",
          TextMapId = "voice_ch_char_Saiqi_vo_lvup"
        },
        voice_ch_char_Saiqi_vo_revive = {
          ContentEN = "I'm still... alive?",
          TextMapId = "voice_ch_char_Saiqi_vo_revive"
        },
        voice_ch_char_Saiqi_vo_skill01_r01 = {
          ContentEN = "Sorry.",
          TextMapId = "voice_ch_char_Saiqi_vo_skill01_r01"
        },
        voice_ch_char_Saiqi_vo_skill01_r02 = {
          ContentEN = "Blow them away.",
          TextMapId = "voice_ch_char_Saiqi_vo_skill01_r02"
        },
        voice_ch_char_Saiqi_vo_skill02_r01 = {
          ContentEN = "Blossom like flowers.",
          TextMapId = "voice_ch_char_Saiqi_vo_skill02_r01"
        },
        voice_ch_char_Saiqi_vo_skill02_r02 = {
          ContentEN = "Break free from the cocoon.",
          TextMapId = "voice_ch_char_Saiqi_vo_skill02_r02"
        },
        voice_ch_char_Saiqi_vo_skill02_r03 = {
          ContentEN = "Decay, or burn in the sunshine.",
          TextMapId = "voice_ch_char_Saiqi_vo_skill02_r03"
        },
        voice_ch_char_Saiqi_vo_topic_01_1 = {
          ContentEN = "Thank you! Actually, we Charons are quite resilient to the cold, so there's no need for expensive, heavy coats.",
          TextMapId = "voice_ch_char_Saiqi_vo_topic_01_1"
        },
        voice_ch_char_Saiqi_vo_topic_01_2 = {
          ContentEN = "My mom made this dress, but I chose the colour — this vibrant green — and the butterfly details too. They'd look right at home somewhere warm, like the south.",
          TextMapId = "voice_ch_char_Saiqi_vo_topic_01_2"
        },
        voice_ch_char_Saiqi_vo_topic_01_3 = {
          ContentEN = "Really? That's so nice to hear! Actually, I've only seen blue butterflies around Icelake. I'd love to see what other colours are out there someday.",
          TextMapId = "voice_ch_char_Saiqi_vo_topic_01_3"
        },
        voice_ch_char_Saiqi_vo_topic_02_1 = {
          ContentEN = "Yeah, it's been that way for ages. We're treated like pests and I've faced harassment and insults for no reason.",
          TextMapId = "voice_ch_char_Saiqi_vo_topic_02_1"
        },
        voice_ch_char_Saiqi_vo_topic_02_2 = {
          ContentEN = "Probably. They say \"Magic is the root of all evil.\" History books claim our ancestors used it to rule over Solas more than a thousand years ago, committing terrible acts.",
          TextMapId = "voice_ch_char_Saiqi_vo_topic_02_2"
        },
        voice_ch_char_Saiqi_vo_topic_02_3 = {
          ContentEN = "Honestly, I can hardly imagine that... The Charons I know are too terrified of Solas to even speak up around them, let alone use magic.",
          TextMapId = "voice_ch_char_Saiqi_vo_topic_02_3"
        },
        voice_ch_char_Saiqi_vo_topic_02_4 = {
          ContentEN = "And Most Charon magic is quite ordinary — just good for simple things like lighting fireplaces or freezing food.",
          TextMapId = "voice_ch_char_Saiqi_vo_topic_02_4"
        },
        voice_ch_char_Saiqi_vo_topic_02_5 = {
          ContentEN = "Not at all. Why must one rule over the other? Why can't Charons and Solas just live in peace?",
          TextMapId = "voice_ch_char_Saiqi_vo_topic_02_5"
        },
        voice_ch_char_Saiqi_vo_topic_02_6 = {
          ContentEN = "All I wish for is that when spring comes, everyone can go out together to enjoy all kinds of flowers. That would be enough for me.",
          TextMapId = "voice_ch_char_Saiqi_vo_topic_02_6"
        },
        voice_ch_char_Saiqi_vo_topic_03_1 = {
          ContentEN = "Ah, that might be from my new gardening project. The courtyard at the Hypnos' House looked a bit barren with just a few trees, so I planted some white flowers there.",
          TextMapId = "voice_ch_char_Saiqi_vo_topic_03_1"
        },
        voice_ch_char_Saiqi_vo_topic_03_2 = {
          ContentEN = "Perhaps we should plant some here too — bellflowers, windflowers, white dryas... Which would suit this place best?",
          TextMapId = "voice_ch_char_Saiqi_vo_topic_03_2"
        },
        voice_ch_char_Saiqi_vo_topic_03_3 = {
          ContentEN = "Right, it should be a group decision... I'll ask around! By the way, which flower do you like best? I'll pick some for you when they bloom.",
          TextMapId = "voice_ch_char_Saiqi_vo_topic_03_3"
        },
        voice_ch_char_Saiqi_vo_topic_04_1 = {
          ContentEN = "No, I've been here my whole life. I always hear those trains and wonder about the places they're heading to. I'd really love to see what's out there.",
          TextMapId = "voice_ch_char_Saiqi_vo_topic_04_1"
        },
        voice_ch_char_Saiqi_vo_topic_04_2 = {
          ContentEN = "Mm, I'd definitely want to visit the capital, for starters; Uncle Henrik once told me the sunsets in Scarletriver are breathtaking... Oh, and I'd love to visit Purgatorio Island you told me about — to feel the sea breeze and see if it's as salty as you described!",
          TextMapId = "voice_ch_char_Saiqi_vo_topic_04_2"
        },
        voice_ch_char_Saiqi_vo_topic_05_1 = {
          ContentEN = "Oh, it's just that... I want to take a good look at you all, to memorize your faces better.",
          TextMapId = "voice_ch_char_Saiqi_vo_topic_05_1"
        },
        voice_ch_char_Saiqi_vo_topic_05_2 = {
          ContentEN = "Could you maybe take a moment to look at me carefully? I'd like you to remember me... just as I am right now.",
          TextMapId = "voice_ch_char_Saiqi_vo_topic_05_2"
        },
        voice_ch_char_Saiqi_vo_victory = {
          ContentEN = "This journey will be etched in my heart forever.",
          TextMapId = "voice_ch_char_Saiqi_vo_victory"
        },
        voice_ch_char_Saiqi_vo_welcome = {
          ContentEN = "Such a relief — I'm still here today. And so are you...",
          TextMapId = "voice_ch_char_Saiqi_vo_welcome"
        },
        voice_ch_char_Shuimu01_vo_appear = {
          ContentEN = "\"Thump... thump...\" Do you hear it? It's my heartbeat, every beat a syllable of missing you.",
          TextMapId = "voice_ch_char_Shuimu01_vo_appear"
        },
        voice_ch_char_Shuimu01_vo_battlestart = {
          ContentEN = "Shall we begin with a waltz? Like this... one, and two...",
          TextMapId = "voice_ch_char_Shuimu01_vo_battlestart"
        },
        voice_ch_char_Shuimu01_vo_gain = {
          ContentEN = "Before the dawn comes, let's dance together, forever and ever — until I kiss your pale lips, until death do us part.",
          TextMapId = "voice_ch_char_Shuimu01_vo_gain"
        },
        voice_ch_char_Shuimu01_vo_skill02_r01 = {
          ContentEN = "Let's tint the seven-ply sapphire gauze with crimson.",
          TextMapId = "voice_ch_char_Shuimu01_vo_skill02_r01"
        },
        voice_ch_char_Shuimu02_vo_appear = {
          ContentEN = "My love, lift my veil.",
          TextMapId = "voice_ch_char_Shuimu02_vo_appear"
        },
        voice_ch_char_Shuimu02_vo_battlestart = {
          ContentEN = "Some guests wish to intrude. Best we give them a proper welcome.",
          TextMapId = "voice_ch_char_Shuimu02_vo_battlestart"
        },
        voice_ch_char_Shuimu02_vo_gain = {
          ContentEN = "I will love you still, even through the haze, through ruin, through the fall — down to the depths. Let Heaven bear witness now, to the vow we speak, and the promise we make. You won't break it, will you?",
          TextMapId = "voice_ch_char_Shuimu02_vo_gain"
        },
        voice_ch_char_Shuimu02_vo_skill02_r01 = {
          ContentEN = "A birth… of love divine!",
          TextMapId = "voice_ch_char_Shuimu02_vo_skill02_r01"
        },
        voice_ch_char_Shuimu02_vo_skill02_r02 = {
          ContentEN = "Your blessings… I'm listening.",
          TextMapId = "voice_ch_char_Shuimu02_vo_skill02_r02"
        },
        voice_ch_char_Shuimu02_vo_skill02_r03 = {
          ContentEN = "Guests who make too much noise… will be punished.",
          TextMapId = "voice_ch_char_Shuimu02_vo_skill02_r03"
        },
        voice_ch_char_Shuimu_vo_appear = {
          ContentEN = "Are you inviting me on a date?",
          TextMapId = "voice_ch_char_Shuimu_vo_appear"
        },
        voice_ch_char_Shuimu_vo_battleidle = {
          ContentEN = "Hurry up! I don't want to ruin our date by being late.",
          TextMapId = "voice_ch_char_Shuimu_vo_battleidle"
        },
        voice_ch_char_Shuimu_vo_battlestart = {
          ContentEN = "My venom is surging like my passion for love...",
          TextMapId = "voice_ch_char_Shuimu_vo_battlestart"
        },
        voice_ch_char_Shuimu_vo_be_hit_heavy_r01 = {
          ContentEN = "That's brutal.",
          TextMapId = "voice_ch_char_Shuimu_vo_be_hit_heavy_r01"
        },
        voice_ch_char_Shuimu_vo_be_hit_heavy_r02 = {
          ContentEN = "You're cold-blooded!",
          TextMapId = "voice_ch_char_Shuimu_vo_be_hit_heavy_r02"
        },
        voice_ch_char_Shuimu_vo_be_hit_r01 = {
          ContentEN = "Ah!",
          TextMapId = "voice_ch_char_Shuimu_vo_be_hit_r01"
        },
        voice_ch_char_Shuimu_vo_be_hit_r02 = {
          ContentEN = "Uh!",
          TextMapId = "voice_ch_char_Shuimu_vo_be_hit_r02"
        },
        voice_ch_char_Shuimu_vo_birthday = {
          ContentEN = "I heard today is your birthday. Would you like to accompany me to my aroma garden? That's where I keep the aromatic ingredients especially for you. Each one contains the pure aroma of love, which is meant for us, and us alone. What? *chuckle* Are they toxic? Well, come with me and you'll find out.",
          TextMapId = "voice_ch_char_Shuimu_vo_birthday"
        },
        voice_ch_char_Shuimu_vo_companio_01 = {
          ContentEN = [[
That dry scent... Oh, it's you. Long time no see. Still planning to take me away in handcuffs? That sounds like a fun idea...
After all, even if I gave you a thousand chances, I would still escape from your grasp... Wouldn't you agree, Ms. Warden?]],
          TextMapId = "voice_ch_char_Shuimu_vo_companio_01"
        },
        voice_ch_char_Shuimu_vo_companio_02 = {
          ContentEN = "You're scared of me? Don't worry. I'll make you love me eventually. Come, have a whiff of the perfume I've blended. It smells very sweet, and I believe you'll love it.",
          TextMapId = "voice_ch_char_Shuimu_vo_companio_02"
        },
        voice_ch_char_Shuimu_vo_companio_03 = {
          ContentEN = "You're a weirdo like me. You enjoy getting hurt, savour pains and immerse yourself in slaughtering your enemies without blinking an eye... I get it. *giggle* That must be how you express your love.",
          TextMapId = "voice_ch_char_Shuimu_vo_companio_03"
        },
        voice_ch_char_Shuimu_vo_die_r01 = {
          ContentEN = "God of Love... Please don't forsake me...",
          TextMapId = "voice_ch_char_Shuimu_vo_die_r01"
        },
        voice_ch_char_Shuimu_vo_die_r02 = {
          ContentEN = "Ciao, amore mio.",
          TextMapId = "voice_ch_char_Shuimu_vo_die_r02"
        },
        voice_ch_char_Shuimu_vo_fail = {
          ContentEN = "Failure hurts... I could really use a bit of comfort from you.",
          TextMapId = "voice_ch_char_Shuimu_vo_fail"
        },
        voice_ch_char_Shuimu_vo_gain = {
          ContentEN = "What a romantic encounter! Was this the God of Love's work? I'm Rebecca, a perfumer. How about indulging in a truly unique scent, the L'essence De L'amour? I made it myself.",
          TextMapId = "voice_ch_char_Shuimu_vo_gain"
        },
        voice_ch_char_Shuimu_vo_idle = {
          ContentEN = "Are you staying here to spend some lovely time with me? I'm already looking forward to it.",
          TextMapId = "voice_ch_char_Shuimu_vo_idle"
        },
        voice_ch_char_Shuimu_vo_lvup = {
          ContentEN = "Is this a reward for my overwhelming love?",
          TextMapId = "voice_ch_char_Shuimu_vo_lvup"
        },
        voice_ch_char_Shuimu_vo_revive = {
          ContentEN = "I can feel it, the power of love!",
          TextMapId = "voice_ch_char_Shuimu_vo_revive"
        },
        voice_ch_char_Shuimu_vo_skill01_r01 = {
          ContentEN = "Come closer.",
          TextMapId = "voice_ch_char_Shuimu_vo_skill01_r01"
        },
        voice_ch_char_Shuimu_vo_skill01_r02 = {
          ContentEN = "No violent contact.",
          TextMapId = "voice_ch_char_Shuimu_vo_skill01_r02"
        },
        voice_ch_char_Shuimu_vo_skill02_r01 = {
          ContentEN = "Sweet venom going down your throat!",
          TextMapId = "voice_ch_char_Shuimu_vo_skill02_r01"
        },
        voice_ch_char_Shuimu_vo_skill02_r02 = {
          ContentEN = "Rot in this sweet aroma!",
          TextMapId = "voice_ch_char_Shuimu_vo_skill02_r02"
        },
        voice_ch_char_Shuimu_vo_skill02_r03 = {
          ContentEN = "Fear not, for I'll send you to the Land of Love.",
          TextMapId = "voice_ch_char_Shuimu_vo_skill02_r03"
        },
        voice_ch_char_Shuimu_vo_topic_01_1 = {
          ContentEN = "Yes, I love rainy days. They remind me of the love stories I've read, where romantic encounters always happen on a rainy day.",
          TextMapId = "voice_ch_char_Shuimu_vo_topic_01_1"
        },
        voice_ch_char_Shuimu_vo_topic_01_2 = {
          ContentEN = "Have you ever observed those seeking shelter from the rain? They meet under eaves, the damp air enhancing the fragrance of greenery, love gently flowing with tentative advances...",
          TextMapId = "voice_ch_char_Shuimu_vo_topic_01_2"
        },
        voice_ch_char_Shuimu_vo_topic_01_3 = {
          ContentEN = "Hehe, join me next time it rains, and you'll see what I mean.",
          TextMapId = "voice_ch_char_Shuimu_vo_topic_01_3"
        },
        voice_ch_char_Shuimu_vo_topic_02_1 = {
          ContentEN = "Ah, you're initiating a conversation about love with me — how unexpected.",
          TextMapId = "voice_ch_char_Shuimu_vo_topic_02_1"
        },
        voice_ch_char_Shuimu_vo_topic_02_2 = {
          ContentEN = "Hmm, how should I put it? ...It's like water in perfume, which kisses and embraces each ingredient, devours and absorbs their fragrance, and eventually blends with them to create a long-lasting aroma...",
          TextMapId = "voice_ch_char_Shuimu_vo_topic_02_2"
        },
        voice_ch_char_Shuimu_vo_topic_02_3 = {
          ContentEN = "There's much more to that. I seek a love so profound that we become truly inseparable... Even if life itself ends, one will become the mulch for the flowers in our garden; the blooms will turn into perfume, lingering around the other for eternity.",
          TextMapId = "voice_ch_char_Shuimu_vo_topic_02_3"
        },
        voice_ch_char_Shuimu_vo_topic_03_1 = {
          ContentEN = "Special? Indeed... Many have seen me as a \"monster\" since I was young.",
          TextMapId = "voice_ch_char_Shuimu_vo_topic_03_1"
        },
        voice_ch_char_Shuimu_vo_topic_03_2 = {
          ContentEN = "The looks of disgust on their faces aren't pleasant, which should be corrected...",
          TextMapId = "voice_ch_char_Shuimu_vo_topic_03_2"
        },
        voice_ch_char_Shuimu_vo_topic_03_3 = {
          ContentEN = "Perhaps a little sting of my toxin in their skin will soften those harsh looks... Hehe.",
          TextMapId = "voice_ch_char_Shuimu_vo_topic_03_3"
        },
        voice_ch_char_Shuimu_vo_topic_03_4 = {
          ContentEN = "So, when you say \"special\", do you mean special like a monster... or specially enchanting?",
          TextMapId = "voice_ch_char_Shuimu_vo_topic_03_4"
        },
        voice_ch_char_Shuimu_vo_topic_04_1 = {
          ContentEN = "I'm perfectly fine. My venom is part of me, like a gift from the God of Love — it's harmless to me, and will help me find my destined lover.",
          TextMapId = "voice_ch_char_Shuimu_vo_topic_04_1"
        },
        voice_ch_char_Shuimu_vo_topic_04_2 = {
          ContentEN = "Of course. Though it often casts me as a monster, it also sets me apart. I believe that the destined lover meant for a monster must be quite special, don't you think?",
          TextMapId = "voice_ch_char_Shuimu_vo_topic_04_2"
        },
        voice_ch_char_Shuimu_vo_topic_05_1 = {
          ContentEN = "It's my signature perfume, with top notes as intense as a first encounter, heart notes of sweet nothings that fix the scent, and a base note that lingers with a bittersweet aftertaste.",
          TextMapId = "voice_ch_char_Shuimu_vo_topic_05_1"
        },
        voice_ch_char_Shuimu_vo_topic_05_2 = {
          ContentEN = "That's my little secret. However, I'd be delighted to guide you through the blending process myself, one step at a time.",
          TextMapId = "voice_ch_char_Shuimu_vo_topic_05_2"
        },
        voice_ch_char_Shuimu_vo_victory = {
          ContentEN = "I will punish those who aren't faithful to love in the God of Love's name.",
          TextMapId = "voice_ch_char_Shuimu_vo_victory"
        },
        voice_ch_char_Shuimu_vo_welcome = {
          ContentEN = "I've been waiting here ever since I woke up. My venom has almost run dry... So, it's a good thing you came. I can feel it bubbling through my veins again. Can you come a little closer...?",
          TextMapId = "voice_ch_char_Shuimu_vo_welcome"
        },
        voice_ch_char_Songlu01_vo_appear = {
          ContentEN = "Tap left, tap right, then spin around... Ooohhh! Almost stepped on my foot. Teach me once more, Filbert!",
          TextMapId = "voice_ch_char_Songlu01_vo_appear"
        },
        voice_ch_char_Songlu01_vo_battlestart = {
          ContentEN = "Just give me your hand and spin around together!",
          TextMapId = "voice_ch_char_Songlu01_vo_battlestart"
        },
        voice_ch_char_Songlu01_vo_gain = {
          ContentEN = "Ooh, look — sparkling stars, cute sunflowers, all fluffy-soft like freshly baked bread... Aww, I've never worn such a lovely dress! Oh? Filbert says she can't wait to dance already!",
          TextMapId = "voice_ch_char_Songlu01_vo_gain"
        },
        voice_ch_char_Songlu01_vo_skill02_r01 = {
          ContentEN = "Prepare yourself for Filbert's suuuuuper dance move!",
          TextMapId = "voice_ch_char_Songlu01_vo_skill02_r01"
        },
        voice_ch_char_Songlu_vo_appear = {
          ContentEN = "Filbert, wakey-wakey! It's time to leave! ",
          TextMapId = "voice_ch_char_Songlu_vo_appear"
        },
        voice_ch_char_Songlu_vo_battleidle = {
          ContentEN = "Nom nom nom...",
          TextMapId = "voice_ch_char_Songlu_vo_battleidle"
        },
        voice_ch_char_Songlu_vo_battlestart = {
          ContentEN = "Filbert, let's go go go!",
          TextMapId = "voice_ch_char_Songlu_vo_battlestart"
        },
        voice_ch_char_Songlu_vo_be_hit_heavy_r01 = {
          ContentEN = "Not fair...",
          TextMapId = "voice_ch_char_Songlu_vo_be_hit_heavy_r01"
        },
        voice_ch_char_Songlu_vo_be_hit_r01 = {
          ContentEN = "Ouch...",
          TextMapId = "voice_ch_char_Songlu_vo_be_hit_r01"
        },
        voice_ch_char_Songlu_vo_birthday = {
          ContentEN = "Happy birthday! I made a giant cream cake with nuts and jam. But, the smell lured in lots of people... so... um... I shared it with them too. But don't worry! I saved one piece for you! Look! I picked the biggest piece with jam and borealberry on it. Try it. It tastes much better than our army rations.",
          TextMapId = "voice_ch_char_Songlu_vo_birthday"
        },
        voice_ch_char_Songlu_vo_companio_01 = {
          ContentEN = "You found sprouting potatoes in the bin? Don't throw them away — let's plant them! With a little digging and watering, we'll have lots of potatoes for everyone soon enough!",
          TextMapId = "voice_ch_char_Songlu_vo_companio_01"
        },
        voice_ch_char_Songlu_vo_companio_02 = {
          ContentEN = "You're always working so hard. Don't you get hungry? Why not join the Church? I'm sure I'll make your tummy full!",
          TextMapId = "voice_ch_char_Songlu_vo_companio_02"
        },
        voice_ch_char_Songlu_vo_companio_03 = {
          ContentEN = "Helloooo! I heard that praying can make one's soul feel uplifted. Personally, I think that a good meal does the same thing. But which one works better, praying or dining?",
          TextMapId = "voice_ch_char_Songlu_vo_companio_03"
        },
        voice_ch_char_Songlu_vo_die_r01 = {
          ContentEN = "Look... huge ears of wheat... They're even bigger than berries.",
          TextMapId = "voice_ch_char_Songlu_vo_die_r01"
        },
        voice_ch_char_Songlu_vo_die_r02 = {
          ContentEN = "Impossible... I had a full meal before battle...",
          TextMapId = "voice_ch_char_Songlu_vo_die_r02"
        },
        voice_ch_char_Songlu_vo_fail = {
          ContentEN = "Filbert, are you okay? Are you hurt? Oh my little sweetie, lemme give you a hug.",
          TextMapId = "voice_ch_char_Songlu_vo_fail"
        },
        voice_ch_char_Songlu_vo_gain = {
          ContentEN = "Hellooo! It's me, the Commissary, Truffle, with my faithful followers by my side, Filbert and her family. That's it for my self-introduction - but I gotta say - your eyes look as big as saucers! You must be starving!",
          TextMapId = "voice_ch_char_Songlu_vo_gain"
        },
        voice_ch_char_Songlu_vo_idle = {
          ContentEN = "Let's take some rest, Filbert. Have some grains and nuts, and a few flowers for snacks. If you're full, I'll pin them to my hat for now.",
          TextMapId = "voice_ch_char_Songlu_vo_idle"
        },
        voice_ch_char_Songlu_vo_lvup = {
          ContentEN = "An empty tummy won't get you far in battle. So gobble up some grub and prepare to charge towards victory!",
          TextMapId = "voice_ch_char_Songlu_vo_lvup"
        },
        voice_ch_char_Songlu_vo_revive = {
          ContentEN = "Emergency food is gross... Well, at least it fills up my tummy.",
          TextMapId = "voice_ch_char_Songlu_vo_revive"
        },
        voice_ch_char_Songlu_vo_skill01_r01 = {
          ContentEN = "Gonna knock you flying!",
          TextMapId = "voice_ch_char_Songlu_vo_skill01_r01"
        },
        voice_ch_char_Songlu_vo_skill01_r02 = {
          ContentEN = "This is gonna hurt!",
          TextMapId = "voice_ch_char_Songlu_vo_skill01_r02"
        },
        voice_ch_char_Songlu_vo_skill02_r01 = {
          ContentEN = "The Commissary's coming. Bid farewell to your hunger!",
          TextMapId = "voice_ch_char_Songlu_vo_skill02_r01"
        },
        voice_ch_char_Songlu_vo_skill02_r02 = {
          ContentEN = "The special Commissary's here. Feast till forever!",
          TextMapId = "voice_ch_char_Songlu_vo_skill02_r02"
        },
        voice_ch_char_Songlu_vo_skill02_r03 = {
          ContentEN = "Gimme the food, or else I'll smash you.",
          TextMapId = "voice_ch_char_Songlu_vo_skill02_r03"
        },
        voice_ch_char_Songlu_vo_topic_01_1 = {
          ContentEN = "Huh? You don't know? A commissary's job is to make sure everyone's well-fed, dealing with all sorts of food every day.",
          TextMapId = "voice_ch_char_Songlu_vo_topic_01_1"
        },
        voice_ch_char_Songlu_vo_topic_01_2 = {
          ContentEN = "For example, I go out to gather all kinds of ingredients from the wild, have Filbert haul them back, and then get Mr Beard at the bakery to turn them into yummy food for everyone.",
          TextMapId = "voice_ch_char_Songlu_vo_topic_01_2"
        },
        voice_ch_char_Songlu_vo_topic_01_3 = {
          ContentEN = "And just so you know, haggling with Mr Beard is part of my job too! Hehe.",
          TextMapId = "voice_ch_char_Songlu_vo_topic_01_3"
        },
        voice_ch_char_Songlu_vo_topic_01_4 = {
          ContentEN = "Oh, not at all! The others seem to be brainy types; they're all about the paperwork — filling out application forms, then waiting for trains loaded with food to roll in.",
          TextMapId = "voice_ch_char_Songlu_vo_topic_01_4"
        },
        voice_ch_char_Songlu_vo_topic_01_5 = {
          ContentEN = "But for a small town like ours, just Filbert and I can feed everyone! Otherwise, I might have to start filling out those forms too — ugh, it's all gibberish to me.",
          TextMapId = "voice_ch_char_Songlu_vo_topic_01_5"
        },
        voice_ch_char_Songlu_vo_topic_02_1 = {
          ContentEN = "Hmm... maybe it does? I've never really thought about it, but Filbert only knocks down those no-good, shouty, fighty troublemakers! They totally deserve it!",
          TextMapId = "voice_ch_char_Songlu_vo_topic_02_1"
        },
        voice_ch_char_Songlu_vo_topic_02_2 = {
          ContentEN = "Those guys always end up hungry after their brawls. They'd do more good ploughing fields than swinging weapons — that way, less people would go to bed hungry.",
          TextMapId = "voice_ch_char_Songlu_vo_topic_02_2"
        },
        voice_ch_char_Songlu_vo_topic_02_3 = {
          ContentEN = "Absolutely! Fighting just leads to hunger — that's really awful! I've heard that in times of war, everyone ends up starving, which is just the worst! I hope I never have to see that.",
          TextMapId = "voice_ch_char_Songlu_vo_topic_02_3"
        },
        voice_ch_char_Songlu_vo_topic_02_4 = {
          ContentEN = "Right! Anyone who makes people go hungry will sooner or later get knocked over by Filbert!",
          TextMapId = "voice_ch_char_Songlu_vo_topic_02_4"
        },
        voice_ch_char_Songlu_vo_topic_03_1 = {
          ContentEN = "Yeah, she is! And you know what, even across several creeks, Filbert can sniff out ripe berries and then off we go charging! Pretty awesome, isn't she?",
          TextMapId = "voice_ch_char_Songlu_vo_topic_03_1"
        },
        voice_ch_char_Songlu_vo_topic_03_2 = {
          ContentEN = "No worries at all! Filbert always brings more food. So never ever make fun of her — it would hurt her feelings, and mine too.",
          TextMapId = "voice_ch_char_Songlu_vo_topic_03_2"
        },
        voice_ch_char_Songlu_vo_topic_04_1 = {
          ContentEN = "Thank you! Actually, these are shorts, not a dress. They did start as a pretty, long, white dress; then the lady at the tailor's shop turned them into shorts for me.",
          TextMapId = "voice_ch_char_Songlu_vo_topic_04_1"
        },
        voice_ch_char_Songlu_vo_topic_04_2 = {
          ContentEN = "Because dresses aren't the best for all the running around I do. One time, I tripped over the hem and all the bread in my arms went flying.",
          TextMapId = "voice_ch_char_Songlu_vo_topic_04_2"
        },
        voice_ch_char_Songlu_vo_topic_04_3 = {
          ContentEN = "But if the day comes, when no one's starving anymore, I'll have them changed back into a dress!",
          TextMapId = "voice_ch_char_Songlu_vo_topic_04_3"
        }
      }
    end
  },
  {
