        },
        voice_ch_char_Zhangyu_vo_topic_01_2 = {
          ContentEN = "\"Your smile in the morning is already the greatest pick-me-up of all. From now on, I'll always be there to keep you safe.\" Hee hee, pretty convincing, isn't it?",
          TextMapId = "voice_ch_char_Zhangyu_vo_topic_01_2"
